import { useEffect, useMemo, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import type { NewsletterCampaignConfig, NewsletterDesign } from '@capiro/shared/newsletter';
import { Monitor, Smartphone, ArrowLeft, Send, Check } from 'lucide-react';
import { useApi } from '../../../lib/use-api.js';
import { useApiScope } from '../../../lib/use-api-scope.js';
import type { Client } from '../../clients/clientTypes.js';
import { StepRecipientsSelect } from './v2/StepRecipientsSelect.js';
import { sanitizeTargets, type OutreachTarget } from './v2/targets.js';
import { recipientKey } from './v2/types.js';
import type { CollisionResolution } from './v2/RecipientCollisions.js';
import type { OutreachSenderInbox } from './v2/NewOutreachWizard.js';
import './newsletter-outreach.css';

interface Version {
  id: string;
  subject: string;
  body: string;
  sendable: boolean;
  auditStatus: string;
  approvalStatus: string;
  recipientEmail: string;
}
interface NewsletterOutreachRecord {
  id: string;
  name: string;
  status: string;
  subject: string;
  senderConnectionId: string | null;
  targets: OutreachTarget[];
  versions: Version[];
  intentId: string | null;
  tests?: TestReference[];
  excluded?: string[];
  stage: {
    id: string;
    documentId: string;
    revision: number;
    config: NewsletterCampaignConfig;
    design: NewsletterDesign;
  };
}
interface TestReference {
  id: string;
  requestKey: string;
  senderConnectionId: string;
  versionId: string;
}
interface Intent {
  id: string;
  status: string;
  totals: Record<string, number>;
  error: string | null;
  deliveries: Array<{
    id: string;
    status: string;
    to: Array<{ email: string }>;
    errorMessage: string | null;
  }>;
}

/** Newsletter lists/groups become private copies; no shared To exposes a client's
 * address or gives another group member their unsubscribe capability. */
export function newsletterDestinations(targets: OutreachTarget[]) {
  // A newsletter group is a source of individual contacts, rather than the
  // generic Outreach projection's one representative with shared To members.
  // Prefer the first personal entry's identity when a directory address repeats.
  const rows = (['individual', 'list', 'group'] as const).flatMap((type) =>
    targets
      .filter((target) => target.type === type)
      .flatMap((target) =>
        target.recipients.map((recipient) => {
          const key = recipientKey(recipient);
          return {
            ...recipient,
            cc: [
              ...(recipient.cc ?? []),
              ...target.cc,
              ...(target.ccContacts?.map((c) => c.email) ?? []),
              ...(target.type === 'list' ? (target.memberCc?.[key] ?? []) : []),
              ...(target.type === 'list'
                ? (target.memberCcContacts?.[key]?.map((c) => c.email) ?? [])
                : []),
            ],
            bcc: [
              ...(recipient.bcc ?? []),
              ...target.bcc,
              ...(target.bccContacts?.map((c) => c.email) ?? []),
              ...(target.type === 'list' ? (target.memberBcc?.[key] ?? []) : []),
              ...(target.type === 'list'
                ? (target.memberBccContacts?.[key]?.map((c) => c.email) ?? [])
                : []),
            ],
          };
        }),
      ),
  );
  const byEmail = new Map<
    string,
    {
      email: string;
      name?: string;
      clientId?: string;
      directoryContactId?: string;
      cc: string[];
      bcc: string[];
    }
  >();
  for (const row of rows) {
    const email = (row.email ?? '').trim().toLowerCase();
    if (!email) continue;
    const prior = byEmail.get(email);
    const copy = (values: string[] = []) => [
      ...new Set(values.map((v) => v.trim().toLowerCase()).filter((v) => v && v !== email)),
    ];
    byEmail.set(email, {
      email,
      name: prior ? prior.name : row.name,
      clientId: prior ? prior.clientId : row.clientId,
      directoryContactId: prior ? prior.directoryContactId : row.directoryContactId,
      cc: copy([...(prior?.cc ?? []), ...(row.cc ?? [])]),
      bcc: copy([...(prior?.bcc ?? []), ...(row.bcc ?? [])]),
    });
  }
  return [...byEmail.values()];
}
function errorMessage(error: unknown) {
  const value = (error as { response?: { data?: { message?: string | string[] } } })?.response?.data
    ?.message;
  return Array.isArray(value)
    ? value.join(' ')
    : (value ?? (error as Error)?.message ?? 'Please try again.');
}
export function NewsletterOutreach({ clients }: { clients: Client[] }) {
  const scope = useApiScope();
  const location = useLocation();
  return <NewsletterOutreachSession key={`${scope}:${location.search}`} clients={clients} />;
}
export function NewsletterOutreachSession({ clients }: { clients: Client[] }) {
  const api = useApi();
  const scope = useApiScope();
  const location = useLocation();
  const navigate = useNavigate();
  const qc = useQueryClient();
  const params = new URLSearchParams(location.search);
  const id = params.get('newsletter');
  const stageId = params.get('newsletterStage');
  const [record, setRecord] = useState<NewsletterOutreachRecord | null>(null);
  const [targets, setTargets] = useState<OutreachTarget[]>([]);
  const [collisionResolution, setCollisionResolution] = useState<CollisionResolution>(null);
  const [subject, setSubject] = useState('');
  const [sender, setSender] = useState('');
  const [step, setStep] = useState(0);
  const [device, setDevice] = useState<'desktop' | 'mobile'>('desktop');
  const [selectedVersion, setSelectedVersion] = useState(0);
  const [versions, setVersions] = useState<Version[]>([]);
  const [excluded, setExcluded] = useState<string[]>([]);
  const [intentId, setIntentId] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const sendKey = useRef<string | null>(null);
  const testKeys = useRef(new Map<string, string>());
  const [tests, setTests] = useState<TestReference[]>([]);
  const initialized = useRef(false);
  const recordQuery = useQuery({
    queryKey: ['newsletter-outreach', scope, id, stageId],
    retry: false,
    queryFn: async () =>
      (id
        ? await api.get<NewsletterOutreachRecord>(
            `/api/engagement/newsletters/${encodeURIComponent(id)}`,
          )
        : await api.post<NewsletterOutreachRecord>(
            `/api/engagement/newsletters/stages/${encodeURIComponent(stageId ?? '')}/open`,
          )
      ).data,
    refetchOnWindowFocus: false,
  });
  useEffect(() => {
    const row = recordQuery.data;
    if (!row || initialized.current) return;
    initialized.current = true;
    if (!id) {
      navigate(`/engagement/outreach?newsletter=${encodeURIComponent(row.id)}`, { replace: true });
      return;
    }
    setRecord(row);
    setTargets(sanitizeTargets(row.targets));
    setSubject(row.subject);
    setSender(row.senderConnectionId ?? '');
    setVersions(row.versions);
    setIntentId(row.intentId);
    setExcluded(row.excluded ?? []);
    setTests(row.tests ?? []);
    for (const test of row.tests ?? []) {
      const key = `${test.senderConnectionId}:${test.versionId}`;
      if (!testKeys.current.has(key)) testKeys.current.set(key, test.requestKey);
    }
    setStep(row.intentId ? 2 : row.versions.length ? 1 : 0);
  }, [recordQuery.data, id, navigate]);
  const integrations = useQuery({
    queryKey: ['engagement-integrations', 'newsletter', scope],
    queryFn: async () =>
      (
        await api.get<Array<OutreachSenderInbox & { status: string }>>(
          '/api/engagement/integrations',
        )
      ).data,
  });
  const inboxes = (integrations.data ?? []).filter(
    (r) => r.status === 'connected' && ['google_workspace', 'microsoft_365'].includes(r.provider),
  );
  const destinations = useMemo(() => newsletterDestinations(targets), [targets]);
  const intent = useQuery({
    queryKey: ['newsletter-send-intent', scope, intentId],
    enabled: Boolean(intentId),
    queryFn: async () =>
      (
        await api.get<Intent>(
          `/api/engagement/outreach/send-intents/${encodeURIComponent(intentId!)}`,
        )
      ).data,
    refetchInterval: (query) =>
      ['queued', 'running'].includes(query.state.data?.status ?? '') ? 3000 : false,
  });
  const selectedTest = tests.find(
    (test) =>
      test.senderConnectionId === sender && test.versionId === versions[selectedVersion]?.id,
  );
  const testIntent = useQuery({
    queryKey: ['newsletter-test-intent', scope, selectedTest?.id],
    enabled: Boolean(selectedTest),
    retry: false,
    queryFn: async () =>
      (
        await api.get<Intent>(
          `/api/engagement/outreach/send-intents/${encodeURIComponent(selectedTest!.id)}`,
        )
      ).data,
    refetchInterval: (query) =>
      ['queued', 'running'].includes(query.state.data?.status ?? '') ? 3000 : false,
  });
  useEffect(() => {
    window.dispatchEvent(new CustomEvent('capiro:workflow-lock', { detail: { locked: true } }));
    return () => {
      window.dispatchEvent(new CustomEvent('capiro:workflow-lock', { detail: { locked: false } }));
    };
  }, []);
  const invalidatePreview = () => {
    setVersions([]);
    setExcluded([]);
    sendKey.current = null;
  };
  const prepare = async () => {
    if (!record) return;
    setBusy(true);
    setError('');
    try {
      const { data } = await api.post<{ versions: Version[]; excluded: string[] }>(
        `/api/engagement/newsletters/${record.id}/prepare`,
        {
          recipients: destinations,
          targets,
          senderConnectionId: sender,
          subject,
        },
      );
      setVersions(data.versions);
      setExcluded(data.excluded);
      setSelectedVersion(0);
      setStep(1);
      sendKey.current = null;
      setTests([]);
      testKeys.current.clear();
      void qc.invalidateQueries({ queryKey: ['engagement-outreach'] });
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  };
  const send = async (test = false) => {
    if (!record) return;
    const versionId = versions[selectedVersion]?.id;
    if (test && !versionId) return;
    if (test && selectedTest) {
      await testIntent.refetch();
      return;
    }
    setBusy(true);
    setError('');
    try {
      if (!test) sendKey.current ??= crypto.randomUUID();
      const testKey = `${sender}:${versionId}`;
      if (test && !testKeys.current.has(testKey))
        testKeys.current.set(testKey, crypto.randomUUID());
      const requestKey = test ? testKeys.current.get(testKey)! : sendKey.current!;
      const { data } = await api.post<{ intentId: string }>(
        `/api/engagement/newsletters/${record.id}/${test ? 'test' : 'send'}`,
        {
          requestKey,
          senderConnectionId: sender,
          versionIds: test ? [versionId!] : versions.map((v) => v.id),
        },
      );
      if (test)
        setTests((previous) => [
          { id: data.intentId, requestKey, senderConnectionId: sender, versionId: versionId! },
          ...previous.filter(
            (entry) => entry.senderConnectionId !== sender || entry.versionId !== versionId,
          ),
        ]);
      else {
        setIntentId(data.intentId);
        setStep(2);
        void qc.invalidateQueries({ queryKey: ['engagement-outreach'] });
      }
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  };
  if (recordQuery.isError)
    return (
      <section className="newsletter-outreach" role="alert">
        <h2>Newsletter could not be opened</h2>
        <p>{errorMessage(recordQuery.error)}</p>
        <Link to="/workspace">Return to Workspace</Link>
      </section>
    );
  if (!record) return <p role="status">Opening your staged newsletter…</p>;
  const ready = versions.length > 0 && versions.every((v) => v.sendable);
  return (
    <section className="newsletter-outreach">
      <header>
        <Link to="/engagement/outreach">
          <ArrowLeft size={18} />
          Outreach
        </Link>
        <div>
          <h1>{record.name}</h1>
          <p>Workspace revision {record.stage.revision}</p>
        </div>
        <Link to={`/workspace/newsletters/${record.stage.documentId}`}>Edit in Workspace</Link>
      </header>
      <nav aria-label="Newsletter delivery steps">
        {['Destinations', 'Preview', 'Send'].map((label, index) => (
          <button
            key={label}
            aria-current={step === index ? 'step' : undefined}
            disabled={busy || Boolean(intentId) || index > step}
            onClick={() => setStep(index)}
          >
            <span>{index < step ? <Check size={16} /> : index + 1}</span>
            {label}
          </button>
        ))}
      </nav>
      {error ? (
        <p className="newsletter-outreach-error" role="alert">
          {error}
        </p>
      ) : null}
      {step === 0 ? (
        <>
          <h2>Select destinations</h2>
          <p>
            Choose people from your directories or saved audiences. Each destination receives a
            separate copy, including members selected through a group. Repeated addresses are
            combined into one destination.
          </p>
          <div className="newsletter-outreach-fields">
            <label>
              Send from
              <select
                aria-label="Send from"
                value={sender}
                onChange={(e) => {
                  setSender(e.target.value);
                  invalidatePreview();
                }}
              >
                <option value="">Select a connected mailbox</option>
                {inboxes.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.accountEmail ?? r.provider}
                  </option>
                ))}
              </select>
            </label>
            <label>
              Subject
              <input
                value={subject}
                maxLength={300}
                onChange={(e) => {
                  setSubject(e.target.value);
                  invalidatePreview();
                }}
              />
            </label>
          </div>
          {integrations.isError ? (
            <p role="alert">Connected mailboxes could not be loaded.</p>
          ) : !integrations.isLoading && !inboxes.length ? (
            <p>
              Connect a Google Workspace or Microsoft 365 mailbox in Engagement integrations to
              send.
            </p>
          ) : null}
          <StepRecipientsSelect
            deliveryMode="newsletter"
            clients={clients}
            targets={targets}
            clientId={record.stage.config.clientId}
            collisionResolution={collisionResolution}
            onCollisionResolutionChange={setCollisionResolution}
            onChange={(patch) => {
              if (patch.targets) {
                setTargets(patch.targets);
                invalidatePreview();
              }
            }}
          />
          <footer>
            <span>{destinations.length} destinations</span>
            <button
              className="primary"
              disabled={busy || !destinations.length || !sender || !subject.trim()}
              onClick={() => void prepare()}
            >
              {busy ? 'Preparing preview…' : 'Preview newsletter'}
            </button>
          </footer>
        </>
      ) : step === 1 ? (
        <>
          <div className="newsletter-outreach-previewbar">
            <label>
              Preview for
              <select
                value={selectedVersion}
                onChange={(e) => setSelectedVersion(Number(e.target.value))}
              >
                {versions.map((v, i) => (
                  <option key={v.id} value={i}>
                    {v.recipientEmail}
                  </option>
                ))}
              </select>
            </label>
            <button aria-pressed={device === 'desktop'} onClick={() => setDevice('desktop')}>
              <Monitor size={18} />
              Desktop
            </button>
            <button aria-pressed={device === 'mobile'} onClick={() => setDevice('mobile')}>
              <Smartphone size={18} />
              Mobile
            </button>
            <button
              disabled={busy || !versions[selectedVersion]?.sendable}
              onClick={() => void send(true)}
            >
              {busy
                ? 'Queuing email…'
                : selectedTest
                  ? 'View test status'
                  : 'Send test to my inbox'}
            </button>
          </div>
          <p>
            From: {inboxes.find((r) => r.id === sender)?.accountEmail} · Subject: {subject}
          </p>
          {selectedTest ? (
            <aside className="newsletter-outreach-test" aria-label="Test email status">
              <strong>Test email to your inbox</strong>
              {testIntent.isError ? (
                <p role="alert">
                  Test delivery status could not be loaded.{' '}
                  <button onClick={() => void testIntent.refetch()}>Refresh test status</button>
                </p>
              ) : !testIntent.data ? (
                <p role="status">Loading test delivery status…</p>
              ) : (
                <>
                  <p role="status">
                    {testIntent.data.status} · {testIntent.data.totals.sent ?? 0} sent ·{' '}
                    {testIntent.data.totals.failed ?? 0} failed ·{' '}
                    {testIntent.data.totals.unknown ?? 0} awaiting confirmation
                  </p>
                  <ul>
                    {testIntent.data.deliveries.map((delivery) => (
                      <li key={delivery.id}>
                        {delivery.to.map((recipient) => recipient.email).join(', ')} —{' '}
                        {delivery.status}
                        {delivery.errorMessage ? `: ${delivery.errorMessage}` : ''}
                      </li>
                    ))}
                  </ul>
                  {testIntent.data.error ? <p role="alert">{testIntent.data.error}</p> : null}
                  <p>
                    Client addresses and Cc/Bcc are excluded from this test. Check the received
                    email before sending to your destinations.
                  </p>
                </>
              )}
            </aside>
          ) : null}
          {excluded.length ? (
            <p role="status">{excluded.length} unsubscribed destinations excluded.</p>
          ) : null}
          {versions.some((v) => !v.sendable) ? (
            <p role="alert">
              Some drafts need verification or review before sending. Resolve them in Reviews, or
              edit the source in Workspace and stage it again.
            </p>
          ) : null}
          {versions[selectedVersion] ? (
            <iframe
              title="Newsletter email preview"
              sandbox=""
              srcDoc={versions[selectedVersion]!.body}
              className={`newsletter-outreach-frame ${device}`}
            />
          ) : (
            <p>No subscribed destinations remain. Select another audience.</p>
          )}
          <footer>
            <button onClick={() => setStep(0)}>Back to destinations</button>
            <button className="primary" disabled={busy || !ready} onClick={() => setStep(2)}>
              Continue to send
            </button>
          </footer>
        </>
      ) : (
        <>
          <h2>{intentId ? 'Newsletter delivery' : 'Send newsletter'}</h2>
          {intentId ? (
            <>
              {intent.isError ? (
                <p role="alert">
                  Delivery status could not be loaded.{' '}
                  <button onClick={() => void intent.refetch()}>Refresh status</button>
                </p>
              ) : (
                <p role="status">
                  {intent.data?.status ?? 'Loading delivery status…'} ·{' '}
                  {intent.data?.totals.sent ?? 0} sent · {intent.data?.totals.failed ?? 0} failed ·{' '}
                  {intent.data?.totals.unknown ?? 0} awaiting confirmation
                </p>
              )}
              <ul>
                {intent.data?.deliveries.map((d) => (
                  <li key={d.id}>
                    {d.to.map((r) => r.email).join(', ')} — {d.status}
                    {d.errorMessage ? `: ${d.errorMessage}` : ''}
                  </li>
                ))}
              </ul>
              {['queued', 'running'].includes(intent.data?.status ?? '') ? (
                <button
                  disabled={busy}
                  onClick={async () => {
                    setBusy(true);
                    try {
                      await api.post(`/api/engagement/outreach/send-intents/${intentId}/cancel`);
                      await intent.refetch();
                    } catch (e) {
                      setError(errorMessage(e));
                    } finally {
                      setBusy(false);
                    }
                  }}
                >
                  Cancel remaining deliveries
                </button>
              ) : null}
              <Link to="/engagement/outreach">Return to Outreach</Link>
            </>
          ) : (
            <>
              <p>
                {versions.length} separate emails from{' '}
                {inboxes.find((r) => r.id === sender)?.accountEmail}.
              </p>
              <p>
                <strong>{subject}</strong>
              </p>
              <p>
                Your newsletter is saved. Sending uses the content and destinations shown in the
                preview.
              </p>
              <footer>
                <button onClick={() => setStep(1)}>Back to preview</button>
                <button className="primary" disabled={busy || !ready} onClick={() => void send()}>
                  <Send size={18} />
                  {busy ? 'Queuing newsletter…' : `Send to ${versions.length} destinations`}
                </button>
              </footer>
            </>
          )}
        </>
      )}
    </section>
  );
}

.newsletter-outreach {
  max-width: 1440px;
  margin: 0 auto;
  padding: 24px;
  color: #263a42;
  background: #fff;
}
.newsletter-outreach > header {
  display: flex;
  align-items: center;
  gap: 24px;
  border-bottom: 1px solid #dce3e6;
  padding-bottom: 20px;
}
.newsletter-outreach > header > div {
  flex: 1;
}
.newsletter-outreach h1 {
  font-size: 24px;
  margin: 0;
}
.newsletter-outreach p {
  line-height: 1.6;
}
.newsletter-outreach a {
  color: #007b80;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.newsletter-outreach nav {
  display: flex;
  gap: 24px;
  padding: 24px 0;
}
.newsletter-outreach button {
  border: 1px solid #b9c9ce;
  border-radius: 6px;
  padding: 10px 16px;
  background: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
}
.newsletter-outreach button:disabled {
  opacity: 0.5;
  cursor: default;
}
.newsletter-outreach button.primary {
  background: #007b80;
  color: #fff;
  border-color: #007b80;
}
.newsletter-outreach nav button {
  border: 0;
}
.newsletter-outreach nav button[aria-current='step'] {
  color: #007b80;
  font-weight: 700;
}
.newsletter-outreach nav span {
  border-radius: 50%;
  background: #e8f4f3;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.newsletter-outreach-fields,
.newsletter-outreach-previewbar {
  display: flex;
  align-items: end;
  gap: 20px;
  margin: 20px 0;
  flex-wrap: wrap;
}
.newsletter-outreach label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-weight: 600;
  flex: 1;
  min-width: 240px;
}
.newsletter-outreach input,
.newsletter-outreach select {
  padding: 10px;
  border: 1px solid #b9c9ce;
  border-radius: 6px;
  background: white;
  font-weight: 400;
}
.newsletter-outreach footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 0;
  border-top: 1px solid #dce3e6;
  margin-top: 24px;
}
.newsletter-outreach-frame {
  display: block;
  width: 100%;
  height: 760px;
  border: 1px solid #dce3e6;
  margin: 24px auto;
  background: #f4f4f4;
}
.newsletter-outreach-frame.mobile {
  width: min(100%, 390px);
}
.newsletter-outreach-error {
  background: #fff0ec;
  color: #a22b13;
  padding: 16px;
  border-radius: 6px;
}
.newsletter-outreach-test {
  padding: 16px 20px;
  border: 1px solid #b9d9d7;
  border-radius: 8px;
  background: #f2f9f8;
}
.newsletter-outreach-test ul {
  margin: 8px 0;
  padding-left: 20px;
}
.newsletter-outreach-test p:last-child {
  margin-bottom: 0;
}
@media (max-width: 760px) {
  .newsletter-outreach {
    padding: 12px;
  }
  .newsletter-outreach > header {
    gap: 12px;
    flex-wrap: wrap;
  }
  .newsletter-outreach nav {
    gap: 0;
  }
  .newsletter-outreach nav button {
    padding: 8px;
  }
  .newsletter-outreach-previewbar {
    gap: 8px;
  }
  .newsletter-outreach footer {
    flex-wrap: wrap;
  }
}

import { useEffect, useRef, useState } from 'react';
import { Modal } from './controls.js';
import { newsletterError } from './api.js';
import { newsletterImageFile } from './NewsletterImageAi.js';

export const PHOTOPEA_ORIGIN = 'https://www.photopea.com';
const editorUrl = `${PHOTOPEA_ORIGIN}/#${encodeURIComponent(
  JSON.stringify({
    environment: { lang: 'en', theme: 1, intro: false, localsave: false, panels: [0, 2, 9] },
  }),
)}`;
type Phase = 'starting' | 'loading' | 'ready' | 'exporting' | 'saving' | 'failed';
const pngSignature = [137, 80, 78, 71, 13, 10, 26, 10];

export function NewsletterAdvancedImageEditor({
  url,
  onSave,
  onClose,
}: {
  url: string;
  onSave: (file: File) => Promise<void>;
  onClose: () => void;
}) {
  const frame = useRef<HTMLIFrameElement>(null);
  const [phase, setPhase] = useState<Phase>('starting');
  const state = useRef<Phase>('starting');
  const [error, setError] = useState('');
  const [session, setSession] = useState(0);
  const sequence = useRef(0);
  const exportRequest = useRef<{ id: number; acknowledged: boolean } | null>(null);
  const timeout = useRef<number | null>(null);
  const live = useRef(false);
  const callbacks = useRef({ onSave, onClose });
  callbacks.current = { onSave, onClose };
  const update = (next: Phase) => {
    state.current = next;
    setPhase(next);
  };
  const clearTimeout = () => {
    if (timeout.current) window.clearTimeout(timeout.current);
    timeout.current = null;
  };
  const armTimeout = (message: string, next: Phase) => {
    clearTimeout();
    timeout.current = window.setTimeout(() => {
      if (!live.current) return;
      exportRequest.current = null;
      setError(message);
      update(next);
    }, 60_000);
  };
  useEffect(() => {
    live.current = true;
    let canceled = false;
    let imageSent = false;
    const isLoading = () => !canceled && state.current === 'loading';
    update('starting');
    setError('');
    exportRequest.current = null;
    armTimeout('Photopea did not load. Check your connection and reload the editor.', 'failed');
    const receive = async (event: MessageEvent) => {
      if (
        event.origin !== PHOTOPEA_ORIGIN ||
        event.source !== frame.current?.contentWindow ||
        canceled
      )
        return;
      if (event.data === 'done' && state.current === 'starting') {
        update('loading');
        armTimeout('The image did not load. Reload the editor to try again.', 'failed');
        try {
          const file = await newsletterImageFile(url);
          const bytes = await file.arrayBuffer();
          if (!isLoading()) return;
          imageSent = true;
          frame.current?.contentWindow?.postMessage(bytes, PHOTOPEA_ORIGIN);
        } catch (reason) {
          if (isLoading()) {
            clearTimeout();
            setError(newsletterError(reason));
            update('failed');
          }
        }
      } else if (event.data === 'done' && state.current === 'loading' && imageSent) {
        clearTimeout();
        update('ready');
      } else if (typeof event.data === 'string' && state.current === 'exporting') {
        const request = exportRequest.current;
        if (request && event.data === `capiro:export:${request.id}`) request.acknowledged = true;
        else if (event.data === 'done' && request?.acknowledged) {
          clearTimeout();
          exportRequest.current = null;
          setError('No PNG was exported. Select an open image in Photopea and try again.');
          update('ready');
        }
      } else if (
        event.data instanceof ArrayBuffer &&
        state.current === 'exporting' &&
        exportRequest.current?.acknowledged
      ) {
        clearTimeout();
        exportRequest.current = null;
        const bytes = new Uint8Array(event.data);
        if (
          bytes.length > 10 * 1024 * 1024 ||
          bytes.length < 8 ||
          !pngSignature.every((value, index) => bytes[index] === value)
        ) {
          setError('Export a PNG image smaller than 10 MB.');
          update('ready');
          return;
        }
        update('saving');
        try {
          await callbacks.current.onSave(
            new File([event.data], 'newsletter-photopea.png', { type: 'image/png' }),
          );
          if (!canceled) callbacks.current.onClose();
        } catch (reason) {
          if (!canceled) {
            setError(newsletterError(reason));
            update('ready');
          }
        }
      }
    };
    window.addEventListener('message', receive);
    const leave = (event: BeforeUnloadEvent) => {
      if (!['ready', 'exporting', 'saving'].includes(state.current)) return;
      event.preventDefault();
      event.returnValue = '';
    };
    window.addEventListener('beforeunload', leave);
    return () => {
      canceled = true;
      live.current = false;
      clearTimeout();
      window.removeEventListener('message', receive);
      window.removeEventListener('beforeunload', leave);
    };
  }, [url, session]);
  const busy = phase === 'exporting' || phase === 'saving';
  const close = () => {
    if (!busy) onClose();
  };
  return (
    <Modal title="Advanced image editor" wide className="nl-advanced-editor" onClose={close}>
      <div className="nl-advanced-editor-info">
        <p>
          Edit layers, text, colors and filters in Photopea. Save a PNG back to this newsletter.
        </p>
        <span className="nl-muted">
          This image opens in Photopea. Its free editor includes ads and branding.
        </span>
        {error && <p role="alert">{error}</p>}
        {phase !== 'ready' && phase !== 'failed' && (
          <p role="status">
            {phase === 'saving'
              ? 'Saving image…'
              : phase === 'exporting'
                ? 'Exporting image…'
                : 'Loading editor and image…'}
          </p>
        )}
        {phase === 'failed' && (
          <button onClick={() => setSession((value) => value + 1)}>Reload editor</button>
        )}
      </div>
      <iframe
        key={session}
        ref={frame}
        src={editorUrl}
        title="Photopea image editor"
        referrerPolicy="no-referrer"
        sandbox="allow-scripts allow-same-origin allow-downloads"
        className={busy ? 'is-busy' : ''}
      />
      <footer>
        <button disabled={busy} onClick={close}>
          Cancel
        </button>
        <button
          className="nl-primary"
          disabled={phase !== 'ready'}
          onClick={() => {
            if (state.current !== 'ready') return;
            setError('');
            update('exporting');
            const id = ++sequence.current;
            exportRequest.current = { id, acknowledged: false };
            armTimeout('Export did not finish. You can try saving the image again.', 'ready');
            frame.current?.contentWindow?.postMessage(
              `app.echoToOE("capiro:export:${id}"); app.activeDocument.saveToOE("png");`,
              PHOTOPEA_ORIGIN,
            );
          }}
        >
          {busy ? (phase === 'saving' ? 'Saving image…' : 'Exporting image…') : 'Save image'}
        </button>
      </footer>
    </Modal>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { NewsletterLinkPreviewBlock } from '@capiro/shared/newsletter';
import { Check, Modal, SelectField, TextField } from './controls.js';
import { newsletterError, type NewsletterClient, type NewsletterLinkPreview } from './api.js';

const providers = [
  {
    name: 'AddEvent Calendar Links',
    publisher: 'AddEvent, Inc',
    description: 'Add calendar links for hearings, briefings and other events.',
  },
  {
    name: 'Google Business Profile',
    publisher: 'Google',
    description: 'Add business information from a connected Google Business Profile.',
  },
  {
    name: 'Instagram',
    publisher: 'Instagram',
    description: 'Add posts from a connected Instagram account.',
  },
  {
    name: 'Link Preview',
    publisher: 'Capiro',
    description: 'Add an article or resource preview from a public HTTPS URL.',
    builtin: true,
  },
  {
    name: 'Playable Video',
    publisher: 'Playable',
    description: 'Add video content through a Playable account.',
  },
  {
    name: 'Yelp for Business',
    publisher: 'Yelp',
    description: 'Add information from a connected Yelp business.',
  },
];
const emptyPreview = (): NewsletterLinkPreviewBlock => ({
  kind: 'link-preview',
  sourceUrl: '',
  title: '',
  description: '',
  imageUrl: '',
  size: 'large',
  showImage: true,
  showDescription: true,
  showBackground: true,
});

export function NewsletterApps({
  api,
  documentId,
  app,
  onBeforeLoad,
  onChange,
}: {
  api: NewsletterClient;
  documentId: string;
  app?: NewsletterLinkPreviewBlock;
  onBeforeLoad: () => Promise<unknown>;
  onChange: (value: NewsletterLinkPreviewBlock) => void;
}) {
  const [choosing, setChoosing] = useState(!app);
  const [managing, setManaging] = useState(false);
  const [url, setUrl] = useState(app?.sourceUrl || '');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [warnings, setWarnings] = useState<string[]>([]);
  const pending = useRef(false);
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  useEffect(() => {
    if (!pending.current) setUrl(app?.sourceUrl || '');
  }, [app?.sourceUrl]);
  const choose = () => {
    onChange(app || emptyPreview());
    setChoosing(false);
    setManaging(false);
    setError('');
  };
  const gallery = (
    <section className="nl-app-gallery" aria-label="Available apps">
      <h3>Available</h3>
      {providers.map((provider) => (
        <details key={provider.name}>
          <summary>
            <span>
              {provider.name}
              <small>By {provider.publisher}</small>
            </span>
          </summary>
          <p>{provider.description}</p>
          <p className="nl-muted">
            {provider.builtin
              ? 'Built in. No external account required.'
              : 'This integration is not available in Capiro yet.'}
          </p>
          <button
            disabled={busy || !provider.builtin}
            onClick={choose}
            className={provider.builtin ? 'nl-primary' : ''}
          >
            {provider.builtin ? 'Use Link Preview' : `Connect ${provider.name}`}
          </button>
        </details>
      ))}
    </section>
  );
  return (
    <div className="nl-app-controls">
      <div className="nl-flex">
        <h3>{choosing ? 'Select App' : 'Link Preview'}</h3>
        <button disabled={busy} onClick={() => setManaging(true)}>
          Manage apps
        </button>
      </div>
      {choosing ? (
        <>
          {gallery}
          {app && <button onClick={() => setChoosing(false)}>Back to Link Preview</button>}
        </>
      ) : (
        app && (
          <>
            <p>Create a preview of a public article, bill page or other resource.</p>
            <form
              onSubmit={async (event) => {
                event.preventDefault();
                if (pending.current || !url.trim()) return;
                try {
                  const parsed = new URL(url.trim());
                  if (
                    parsed.protocol !== 'https:' ||
                    parsed.username ||
                    parsed.password ||
                    url.length > 2048
                  )
                    throw new Error();
                } catch {
                  setError('Enter a public HTTPS URL without embedded credentials.');
                  return;
                }
                pending.current = true;
                setBusy(true);
                setError('');
                setWarnings([]);
                try {
                  await onBeforeLoad();
                  if (!mounted.current) return;
                  const preview: NewsletterLinkPreview = await api.linkPreview(
                    documentId,
                    url.trim(),
                  );
                  if (!mounted.current) return;
                  onChange({
                    ...app,
                    sourceUrl: preview.sourceUrl,
                    title: preview.title,
                    description: preview.description,
                    imageUrl: preview.imageUrl,
                  });
                  setUrl(preview.sourceUrl);
                  setWarnings(preview.warnings);
                } catch (cause) {
                  if (mounted.current) setError(newsletterError(cause));
                } finally {
                  pending.current = false;
                  if (mounted.current) setBusy(false);
                }
              }}
            >
              <label>
                Source URL
                <input
                  aria-label="Source URL"
                  type="url"
                  required
                  maxLength={2048}
                  value={url}
                  disabled={busy}
                  placeholder="https://"
                  onChange={(event) => setUrl(event.target.value)}
                />
              </label>
              <button className="nl-primary" disabled={busy || !url.trim()} type="submit">
                {busy ? 'Loading preview…' : app.sourceUrl ? 'Update preview' : 'Load preview'}
              </button>
            </form>
            {error && <p role="alert">{error}</p>}
            {warnings.map((warning) => (
              <p role="status" key={warning}>
                {warning}
              </p>
            ))}
            <fieldset disabled={busy}>
              <SelectField
                label="Block size"
                value={app.size}
                values={['small', 'medium', 'large']}
                onChange={(size) =>
                  onChange({ ...app, size: size as NewsletterLinkPreviewBlock['size'] })
                }
              />
              <Check
                label="Show image"
                checked={app.showImage}
                onChange={(showImage) => onChange({ ...app, showImage })}
              />
              <Check
                label="Show description"
                checked={app.showDescription}
                onChange={(showDescription) => onChange({ ...app, showDescription })}
              />
              <Check
                label="Show background"
                checked={app.showBackground}
                onChange={(showBackground) => onChange({ ...app, showBackground })}
              />
              {app.sourceUrl && (
                <>
                  <TextField
                    label="Preview title"
                    value={app.title}
                    onChange={(title) => onChange({ ...app, title })}
                  />
                  <TextField
                    label="Preview description"
                    multiline
                    value={app.description}
                    onChange={(description) => onChange({ ...app, description })}
                  />
                </>
              )}
            </fieldset>
            <button disabled={busy} onClick={() => setChoosing(true)}>
              Change app
            </button>
          </>
        )
      )}
      {managing && (
        <Modal title="Manage apps" onClose={() => setManaging(false)}>
          <div className="nl-modal-body">
            <p>
              Link Preview is built into Capiro. Other app connections are listed below with their
              current availability.
            </p>
            {gallery}
          </div>
          <footer>
            <button onClick={() => setManaging(false)}>Done</button>
          </footer>
        </Modal>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Modal } from './controls.js';
import { NewsletterAssetRevisions } from './NewsletterAssetRevisions.js';
import {
  newsletterError,
  type NewsletterAsset,
  type NewsletterAssetDetails as AssetDetails,
  type NewsletterClient,
} from './api.js';

export async function copyNewsletterAssetUrl(url: string): Promise<string> {
  try {
    await navigator.clipboard.writeText(url);
    return 'URL copied.';
  } catch {
    return 'Clipboard access is unavailable. Select and copy the Image URL field.';
  }
}

export function NewsletterAssetDetails({
  api,
  asset,
  onClose,
  onRenamed,
  onInsert,
}: {
  api: NewsletterClient;
  asset: NewsletterAsset;
  onClose: () => void;
  onRenamed: (asset: NewsletterAsset) => void;
  onInsert: (asset: NewsletterAsset) => void;
}) {
  const [details, setDetails] = useState<AssetDetails | null>(null);
  const [name, setName] = useState(asset.name);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [reload, setReload] = useState(0);
  const [saving, setSaving] = useState(false);
  const pending = useRef(false);
  const [notice, setNotice] = useState('');
  const [dimensions, setDimensions] = useState('');
  const [imageError, setImageError] = useState(false);
  const [historyRefresh, setHistoryRefresh] = useState(0);
  useEffect(() => {
    let canceled = false;
    setLoading(true);
    setError('');
    api.assetDetails(asset.id).then(
      (value) => {
        if (canceled) return;
        setDetails(value);
        setName(value.name);
        setLoading(false);
      },
      (error) => {
        if (canceled) return;
        setError(newsletterError(error));
        setLoading(false);
      },
    );
    return () => {
      canceled = true;
    };
  }, [api, asset.id, reload]);
  const rename = async () => {
    if (
      pending.current ||
      !details ||
      details.currentRevision === false ||
      !name.trim() ||
      name.length > 200
    )
      return;
    pending.current = true;
    setSaving(true);
    setError('');
    try {
      const updated = await api.renameAsset(details.id, name.trim());
      setDetails((previous) => (previous ? { ...previous, ...updated } : null));
      setName(updated.name);
      onRenamed(updated);
      setNotice('File name saved.');
      setHistoryRefresh((value) => value + 1);
    } catch (error) {
      setError(newsletterError(error));
    } finally {
      pending.current = false;
      setSaving(false);
    }
  };
  return (
    <Modal
      title="File Details"
      wide
      className="nl-asset-details"
      onClose={() => {
        if (!pending.current) onClose();
      }}
    >
      <div className="nl-modal-body">
        {loading && <p role="status">Loading file details…</p>}
        {error && (
          <div role="alert">
            <p>{error}</p>
            {!details && <button onClick={() => setReload((value) => value + 1)}>Try again</button>}
          </div>
        )}
        {details && (
          <div className="nl-asset-details-layout">
            <div className="nl-asset-details-preview">
              <img
                key={details.url}
                src={details.url}
                alt={details.name}
                onLoad={(event) => {
                  const image = event.currentTarget;
                  setDimensions(`${image.naturalWidth} × ${image.naturalHeight} px`);
                  setImageError(false);
                }}
                onError={() => {
                  setImageError(true);
                  setDimensions('');
                }}
              />
              {imageError && <p role="alert">The image preview could not load.</p>}
            </div>
            <div>
              <form
                onSubmit={(event) => {
                  event.preventDefault();
                  void rename();
                }}
              >
                <label className="nl-field">
                  File name
                  <input
                    value={name}
                    maxLength={200}
                    disabled={saving || details.currentRevision === false}
                    onChange={(event) => setName(event.target.value)}
                  />
                </label>
                {details.currentRevision !== false && (
                  <button
                    type="submit"
                    disabled={
                      saving || !name.trim() || name.length > 200 || name.trim() === details.name
                    }
                  >
                    {saving ? 'Saving…' : 'Save name'}
                  </button>
                )}
              </form>
              <dl>
                <dt>File type</dt>
                <dd>{details.mimeType.replace('image/', '').toUpperCase()}</dd>
                <dt>File size</dt>
                <dd>{details.sizeBytes.toLocaleString()} bytes</dd>
                <dt>Uploaded</dt>
                <dd>{new Date(details.createdAt).toLocaleString()}</dd>
                <dt>Version</dt>
                <dd>
                  {(details.revisionNumber ?? 1) === 1
                    ? 'Original'
                    : `Version ${details.revisionNumber}`}
                  {details.currentRevision ? ' · Latest' : ''}
                </dd>
                {dimensions && (
                  <>
                    <dt>Dimensions</dt>
                    <dd>{dimensions}</dd>
                  </>
                )}
              </dl>
              <label className="nl-field">
                Image URL
                <input
                  readOnly
                  value={details.url}
                  onFocus={(event) => event.currentTarget.select()}
                />
              </label>
              <button
                disabled={saving}
                onClick={() => {
                  void copyNewsletterAssetUrl(details.url).then(setNotice);
                }}
              >
                Copy URL
              </button>
              {notice && <p role="status">{notice}</p>}
            </div>
          </div>
        )}
        {details && (
          <NewsletterAssetRevisions
            api={api}
            assetId={asset.id}
            selectedId={details.id}
            disabled={saving || loading}
            refresh={historyRefresh}
            onSelect={(version) => {
              setDetails(version);
              setName(version.name);
              setDimensions('');
              setImageError(false);
              setNotice('');
            }}
          />
        )}
      </div>
      <footer className="nl-studio-import-actions">
        <button disabled={saving} onClick={onClose}>
          Close details
        </button>
        <button
          className="nl-primary"
          disabled={loading || saving || !details}
          onClick={() => {
            if (details) onInsert(details);
          }}
        >
          Insert
        </button>
      </footer>
    </Modal>
  );
}

import { useEffect, useState, type MutableRefObject } from 'react';
import { ChevronDown, Pencil, Trash2 } from 'lucide-react';
import { Modal } from './controls.js';
import { newsletterError, type NewsletterAssetFolder, type NewsletterClient } from './api.js';

type FolderDialog =
  { kind: 'create'; move: boolean } | { kind: 'rename' | 'delete'; folder: NewsletterAssetFolder };
export function NewsletterAssetFolders({
  api,
  folder,
  selectedIds,
  busy,
  pending,
  onBusy,
  onFilter,
  onComplete,
}: {
  api: NewsletterClient;
  folder?: string;
  selectedIds: string[];
  busy: boolean;
  pending: MutableRefObject<boolean>;
  onBusy: (busy: boolean) => void;
  onFilter: (folder: string | undefined) => void;
  onComplete: (message: string, options?: { folder?: string; clearSelection?: boolean }) => void;
}) {
  const [folders, setFolders] = useState<NewsletterAssetFolder[]>([]);
  const [loading, setLoading] = useState(true);
  const [readError, setReadError] = useState('');
  const [writeError, setWriteError] = useState('');
  const [reload, setReload] = useState(0);
  const [moveMenu, setMoveMenu] = useState(false);
  const [dialog, setDialog] = useState<FolderDialog | null>(null);
  const [name, setName] = useState('');
  const activeFolder = folders.find((item) => item.id === folder);
  useEffect(() => {
    let canceled = false;
    setLoading(true);
    setReadError('');
    api.assetFolders().then(
      (items) => {
        if (!canceled) {
          setFolders(items);
          setLoading(false);
        }
      },
      (error) => {
        if (!canceled) {
          setReadError(newsletterError(error));
          setLoading(false);
        }
      },
    );
    return () => {
      canceled = true;
    };
  }, [api, reload]);
  useEffect(() => {
    if (!selectedIds.length) setMoveMenu(false);
  }, [selectedIds.length]);
  const open = (next: FolderDialog) => {
    setDialog(next);
    setName(next.kind === 'rename' ? next.folder.name : '');
    setMoveMenu(false);
    setWriteError('');
  };
  const run = async <T,>(operation: () => Promise<T>, complete: (result: T) => void) => {
    if (pending.current) return;
    pending.current = true;
    onBusy(true);
    setWriteError('');
    try {
      const result = await operation();
      complete(result);
      setDialog(null);
      setMoveMenu(false);
      setReload((value) => value + 1);
    } catch (error) {
      setWriteError(newsletterError(error));
    } finally {
      pending.current = false;
      onBusy(false);
    }
  };
  const submit = () => {
    if (!dialog) return;
    if (dialog.kind === 'create') {
      const ids = dialog.move ? selectedIds : undefined;
      if (!name.trim() || name.length > 100) return;
      void run(
        () => api.createAssetFolder(name.trim(), ids),
        (created) =>
          onComplete(
            ids
              ? `${ids.length} ${ids.length === 1 ? 'file' : 'files'} moved to ${created.name}.`
              : `${created.name} folder created.`,
            { folder: created.id },
          ),
      );
    } else if (dialog.kind === 'rename') {
      if (!name.trim() || name.length > 100) return;
      void run(
        () => api.renameAssetFolder(dialog.folder.id, name.trim()),
        (updated) => onComplete(`Folder renamed to ${updated.name}.`, { clearSelection: false }),
      );
    } else {
      void run(
        () => api.deleteAssetFolder(dialog.folder.id),
        () => onComplete('Folder deleted. Its images are now in Unfiled.', { folder: 'unfiled' }),
      );
    }
  };
  return (
    <>
      <div className="nl-studio-folders">
        <label>
          Folder{' '}
          <select
            aria-label="Folder"
            value={folder || ''}
            disabled={busy || loading}
            onChange={(event) => {
              setMoveMenu(false);
              setWriteError('');
              onFilter(event.target.value || undefined);
            }}
          >
            <option value="">All files</option>
            <option value="unfiled">Unfiled</option>
            {folder && folder !== 'unfiled' && !activeFolder && (
              <option value={folder}>Folder unavailable</option>
            )}
            {folders.map((item) => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
          </select>
        </label>
        <button
          disabled={busy || loading || !!readError}
          onClick={() => open({ kind: 'create', move: false })}
        >
          Add Folder
        </button>
        {activeFolder && (
          <>
            <button
              aria-label={`Rename ${activeFolder.name} folder`}
              disabled={busy || loading || !!readError}
              onClick={() => open({ kind: 'rename', folder: activeFolder })}
            >
              <Pencil size={16} />
            </button>
            <button
              aria-label={`Delete ${activeFolder.name} folder`}
              disabled={busy || loading || !!readError}
              onClick={() => open({ kind: 'delete', folder: activeFolder })}
            >
              <Trash2 size={16} />
            </button>
          </>
        )}
        {!!selectedIds.length && (
          <div className="nl-studio-upload">
            <button
              aria-haspopup="menu"
              aria-expanded={moveMenu}
              disabled={busy || loading || !!readError}
              onClick={() => {
                setMoveMenu(!moveMenu);
                setWriteError('');
              }}
            >
              Move To <ChevronDown size={16} />
            </button>
            {moveMenu && (
              <div
                className="nl-studio-menu nl-studio-folder-menu"
                role="menu"
                aria-label="Move to folder"
              >
                <button
                  role="menuitem"
                  disabled={busy}
                  onClick={() =>
                    void run(
                      () => api.moveAssets(selectedIds, null),
                      (result) =>
                        onComplete(
                          `${result.moved} ${result.moved === 1 ? 'file' : 'files'} moved to Unfiled.`,
                        ),
                    )
                  }
                >
                  Unfiled
                </button>
                {folders.map((item) => (
                  <button
                    role="menuitem"
                    disabled={busy}
                    key={item.id}
                    onClick={() =>
                      void run(
                        () => api.moveAssets(selectedIds, item.id),
                        (result) =>
                          onComplete(
                            `${result.moved} ${result.moved === 1 ? 'file' : 'files'} moved to ${item.name}.`,
                          ),
                      )
                    }
                  >
                    {item.name}
                  </button>
                ))}
                <button
                  role="menuitem"
                  disabled={busy}
                  onClick={() => open({ kind: 'create', move: true })}
                >
                  Add Folder
                </button>
              </div>
            )}
          </div>
        )}
      </div>
      {loading && <p role="status">Loading folders…</p>}
      {readError && (
        <div role="alert">
          <p>{readError}</p>
          <button disabled={busy} onClick={() => setReload((value) => value + 1)}>
            Try folders again
          </button>
        </div>
      )}
      {writeError && !dialog && <p role="alert">{writeError}</p>}
      {dialog && (
        <Modal
          title={
            dialog.kind === 'create'
              ? 'Add Folder'
              : dialog.kind === 'rename'
                ? 'Rename Folder'
                : 'Delete Folder'
          }
          onClose={() => {
            if (!pending.current) setDialog(null);
          }}
        >
          <form
            onSubmit={(event) => {
              event.preventDefault();
              submit();
            }}
          >
            <div className="nl-modal-body">
              {dialog.kind === 'delete' ? (
                <>
                  <p>Delete the {dialog.folder.name} folder?</p>
                  <p>Its images will remain in your library under Unfiled.</p>
                </>
              ) : (
                <label className="nl-field">
                  Folder name
                  <input
                    value={name}
                    maxLength={100}
                    disabled={busy}
                    onChange={(event) => setName(event.target.value)}
                  />
                </label>
              )}
              {dialog.kind === 'create' && dialog.move && (
                <p>
                  {selectedIds.length} selected{' '}
                  {selectedIds.length === 1 ? 'file will' : 'files will'} move into this folder.
                </p>
              )}
              {writeError && <p role="alert">{writeError}</p>}
            </div>
            <footer className="nl-studio-import-actions">
              <button type="button" disabled={busy} onClick={() => setDialog(null)}>
                Cancel
              </button>
              <button
                type="submit"
                className="nl-primary"
                disabled={busy || (dialog.kind !== 'delete' && (!name.trim() || name.length > 100))}
              >
                {busy
                  ? 'Saving…'
                  : dialog.kind === 'create'
                    ? 'Add Folder'
                    : dialog.kind === 'rename'
                      ? 'Save'
                      : 'Delete Folder'}
              </button>
            </footer>
          </form>
        </Modal>
      )}
    </>
  );
}

import { useEffect, useState } from 'react';
import {
  newsletterError,
  type NewsletterAssetDetails,
  type NewsletterAssetRevisionPage,
  type NewsletterClient,
} from './api.js';

export function NewsletterAssetRevisions({
  api,
  assetId,
  selectedId,
  disabled,
  refresh,
  onSelect,
}: {
  api: NewsletterClient;
  assetId: string;
  selectedId: string;
  disabled: boolean;
  refresh: number;
  onSelect: (asset: NewsletterAssetDetails) => void;
}) {
  const [page, setPage] = useState(1);
  const [result, setResult] = useState<NewsletterAssetRevisionPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [reload, setReload] = useState(0);
  useEffect(() => {
    let canceled = false;
    setLoading(true);
    setError('');
    api.assetRevisions(assetId, page).then(
      (value) => {
        if (canceled) return;
        const lastPage = Math.max(1, Math.ceil(value.total / value.pageSize));
        if (page > lastPage) {
          setPage(lastPage);
          return;
        }
        setResult(value);
        setLoading(false);
      },
      (error) => {
        if (canceled) return;
        setError(newsletterError(error));
        setLoading(false);
      },
    );
    return () => {
      canceled = true;
    };
  }, [api, assetId, page, refresh, reload]);
  return (
    <section className="nl-asset-revisions" aria-label="Revision History">
      <h4>Revision History</h4>
      <p className="nl-muted">
        Choose a version to preview, then Insert to use it in your newsletter.
      </p>
      {loading && <p role="status">Loading image versions…</p>}
      {error && (
        <div role="alert">
          <p>{error}</p>
          <button disabled={disabled} onClick={() => setReload((value) => value + 1)}>
            Try history again
          </button>
        </div>
      )}
      {!!result && !error && (
        <>
          <div className="nl-asset-revision-grid">
            {result.items.map((item) => {
              const label =
                item.revisionNumber === 1 ? 'Original' : `Version ${item.revisionNumber}`;
              return (
                <button
                  key={item.id}
                  aria-label={`Preview ${label}`}
                  aria-pressed={selectedId === item.id}
                  disabled={disabled || loading}
                  onClick={() => onSelect(item)}
                >
                  <img src={item.url} alt="" />
                  <span>
                    {label}
                    {item.currentRevision ? ' · Latest' : ''}
                  </span>
                  <small>{new Date(item.createdAt).toLocaleString()}</small>
                </button>
              );
            })}
          </div>
          <div className="nl-asset-revision-pages">
            <button
              disabled={disabled || loading || page <= 1}
              onClick={() => setPage((value) => value - 1)}
            >
              Previous versions
            </button>
            <span>
              Page {page} of {Math.max(1, Math.ceil(result.total / result.pageSize))}
            </span>
            <button
              disabled={disabled || loading || page * result.pageSize >= result.total}
              onClick={() => setPage((value) => value + 1)}
            >
              Next versions
            </button>
          </div>
        </>
      )}
    </section>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import {
  newsletterBrandButtonStyle,
  newsletterId,
  newsletterCatalogStyle,
  type NewsletterBrandKit as BrandKit,
} from '@capiro/shared/newsletter';
import { newsletterFontCss, newsletterStyleCss } from '@capiro/shared/newsletter-render';
import { newsletterError, type NewsletterClient } from './api.js';
import { Check, ColorField, Modal, TextField, NewsletterFontField } from './controls.js';
import { NewsletterBrandContext, newsletterFontChoices } from './brand-context.js';
import { NewsletterWebFonts } from './NewsletterFontPicker.js';

const fingerprint = (kit: BrandKit) =>
  JSON.stringify({ ...kit, revision: undefined, updatedAt: undefined });
export function NewsletterBrandKit({
  api,
  initial,
  onSaved,
  onClose,
}: {
  api: NewsletterClient;
  initial: BrandKit;
  onSaved: (kit: BrandKit) => void;
  onClose: () => void;
}) {
  const [kit, setKit] = useState(() => structuredClone(initial));
  const latest = useRef(kit);
  const revision = useRef(kit.revision);
  const saved = useRef(fingerprint(kit));
  const serial = useRef(Promise.resolve());
  const mounted = useRef(true);
  const conflicted = useRef(false);
  const [category, setCategory] = useState('Logos');
  const [selection, setSelection] = useState<string | null>(null);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('Changes saved');
  const [uploading, setUploading] = useState(false);
  const logoInput = useRef<HTMLInputElement>(null);
  const fontInput = useRef<HTMLInputElement>(null);
  const change = (edit: (draft: BrandKit) => void) => {
    const draft = structuredClone(latest.current);
    edit(draft);
    latest.current = draft;
    setKit(draft);
    setError('');
    setStatus('Unsaved changes');
  };
  const persist = useCallback(async () => {
    const operation = serial.current
      .catch(() => {})
      .then(async () => {
        if (!mounted.current) return;
        if (conflicted.current)
          throw new Error('Reload the saved Brand Kit to resolve the conflicting edit.');
        while (mounted.current && saved.current !== fingerprint(latest.current)) {
          const snapshot = structuredClone(latest.current),
            sent = fingerprint(snapshot);
          if (mounted.current) setStatus('Saving…');
          try {
            const next = await api.saveBrandKit({ ...snapshot, revision: revision.current });
            revision.current = next.revision;
            saved.current = fingerprint(next);
            // Do not overwrite edits made while the request was in flight.
            latest.current =
              fingerprint(latest.current) === sent
                ? next
                : { ...latest.current, revision: next.revision, updatedAt: next.updatedAt };
            if (mounted.current) {
              setKit(latest.current);
              onSaved(next);
            }
          } catch (error) {
            if ((error as { response?: { status?: number } }).response?.status === 409)
              conflicted.current = true;
            if (mounted.current) {
              setError(newsletterError(error));
              setStatus('Changes not saved');
            }
            throw error;
          }
        }
        if (mounted.current) setStatus('Changes saved');
      });
    serial.current = operation;
    await operation;
  }, [api, onSaved]);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  useEffect(() => {
    const leave = (event: BeforeUnloadEvent) => {
      if (uploading || saved.current !== fingerprint(latest.current)) {
        event.preventDefault();
        event.returnValue = '';
      }
    };
    window.addEventListener('beforeunload', leave);
    return () => window.removeEventListener('beforeunload', leave);
  }, [uploading]);
  useEffect(() => {
    if (saved.current === fingerprint(kit)) return;
    const timer = setTimeout(() => void persist().catch(() => {}), 650);
    return () => clearTimeout(timer);
  }, [kit, persist]);
  const close = async () => {
    if (uploading) return;
    try {
      await persist();
      onClose();
    } catch {}
  };
  const logo = kit.logos.find((item) => item.assetId === selection);
  const button = kit.buttons.find((item) => item.id === selection);
  const upload = async (file: File | undefined, kind: 'logo' | 'font') => {
    if (!file) return;
    setUploading(true);
    setError('');
    try {
      if (kind === 'logo') {
        if (!['image/png', 'image/jpeg'].includes(file.type))
          throw new Error('Choose a PNG or JPG logo.');
        const asset = await api.upload(file);
        if (!mounted.current) return;
        change((draft) => {
          draft.logos.push({
            assetId: asset.id,
            name: asset.name,
            url: asset.url,
            link: '',
            alt: asset.name.replace(/\.[^.]+$/, ''),
          });
          if (!draft.primaryLogoId) draft.primaryLogoId = asset.id;
        });
      } else {
        const font = await api.uploadFont(file);
        if (!mounted.current) return;
        change((draft) => {
          draft.fonts.uploaded.push(font);
        });
      }
    } catch (error) {
      if (mounted.current) setError(newsletterError(error));
    } finally {
      if (mounted.current) setUploading(false);
    }
  };
  const previewStyle = (style: ReturnType<typeof newsletterBrandButtonStyle>) => {
    const node = document.createElement('span');
    node.setAttribute('style', newsletterStyleCss(style));
    const values: Record<string, string> = {};
    for (const key of Array.from(node.style))
      values[key.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase())] =
        node.style.getPropertyValue(key);
    return values;
  };
  return (
    <NewsletterBrandContext.Provider
      value={{
        fonts: newsletterFontChoices(kit.fonts.uploaded),
        colors: [...kit.colors.primary, ...kit.colors.secondary],
      }}
    >
      <Modal title="Brand Kit" wide onClose={() => void close()}>
        <style>{newsletterFontCss(kit.fonts.uploaded)}</style>
        <NewsletterWebFonts
          requests={[
            { value: kit.fonts.heading },
            { value: kit.fonts.body },
            ...kit.buttons.map((button) => ({ value: button.fontFamily })),
          ]}
        />
        <input
          hidden
          type="file"
          ref={logoInput}
          accept="image/png,image/jpeg"
          onChange={(event) => {
            void upload(event.target.files?.[0], 'logo');
            event.target.value = '';
          }}
        />
        <input
          hidden
          type="file"
          ref={fontInput}
          accept=".ttf,.otf,.woff,.woff2"
          onChange={(event) => {
            void upload(event.target.files?.[0], 'font');
            event.target.value = '';
          }}
        />
        <div className="nl-brand-status">
          <span role="status">{uploading ? 'Uploading…' : status}</span>
          {error && <p role="alert">{error}</p>}
          {conflicted.current && (
            <button
              onClick={async () => {
                try {
                  const next = await api.brandKit();
                  latest.current = next;
                  revision.current = next.revision;
                  saved.current = fingerprint(next);
                  conflicted.current = false;
                  setKit(next);
                  onSaved(next);
                  setError('');
                  setStatus('Changes saved');
                } catch (error) {
                  setError(newsletterError(error));
                }
              }}
            >
              Reload saved kit
            </button>
          )}
        </div>
        <div className="nl-brand-layout">
          <nav aria-label="Brand Kit sections">
            {['Logos', 'Colors', 'Fonts', 'Buttons'].map((item) => (
              <button
                key={item}
                aria-pressed={category === item}
                onClick={() => {
                  setCategory(item);
                  setSelection(null);
                }}
              >
                {item}
              </button>
            ))}
          </nav>
          <div className="nl-brand-main">
            {category === 'Logos' && (
              <>
                <div className="nl-brand-grid">
                  {kit.logos.map((item) => (
                    <div className="nl-brand-card" key={item.assetId}>
                      <img src={item.url} alt={item.alt || item.name} />
                      <strong>{item.name}</strong>
                      {kit.primaryLogoId === item.assetId && <span>Primary</span>}
                      <button
                        aria-label={`Logo settings for ${item.name}`}
                        onClick={() => setSelection(item.assetId)}
                      >
                        Logo settings
                      </button>
                      <button
                        aria-label={`Delete logo ${item.name}`}
                        onClick={() =>
                          change((draft) => {
                            draft.logos = draft.logos.filter(
                              (logo) => logo.assetId !== item.assetId,
                            );
                            if (draft.primaryLogoId === item.assetId) draft.primaryLogoId = null;
                          })
                        }
                      >
                        Delete logo
                      </button>
                    </div>
                  ))}
                  <button
                    className="nl-brand-card"
                    disabled={uploading || kit.logos.length >= 20}
                    onClick={() => logoInput.current?.click()}
                  >
                    Add Logo
                  </button>
                </div>
                <p className="nl-muted">
                  For best results, upload a full-size PNG with a transparent background. JPG is
                  also supported.
                </p>
                {logo && (
                  <aside className="nl-brand-settings" aria-label="Logo settings">
                    <Check
                      label="Primary logo — use this logo for all new content"
                      checked={kit.primaryLogoId === logo.assetId}
                      onChange={(value) =>
                        change((draft) => {
                          draft.primaryLogoId = value ? logo.assetId : null;
                        })
                      }
                    />
                    <TextField
                      label="Logo name"
                      value={logo.name}
                      onChange={(value) =>
                        change((draft) => {
                          draft.logos.find((item) => item.assetId === logo.assetId)!.name = value;
                        })
                      }
                    />
                    <TextField
                      label="Logo link"
                      value={logo.link}
                      placeholder="https://"
                      onChange={(value) =>
                        change((draft) => {
                          draft.logos.find((item) => item.assetId === logo.assetId)!.link = value;
                        })
                      }
                    />
                    <TextField
                      label="Alt text"
                      value={logo.alt}
                      onChange={(value) =>
                        change((draft) => {
                          draft.logos.find((item) => item.assetId === logo.assetId)!.alt = value;
                        })
                      }
                    />
                    <button onClick={() => setSelection(null)}>Done</button>
                  </aside>
                )}
              </>
            )}
            {category === 'Colors' && (
              <>
                {(['primary', 'secondary'] as const).map((group) => (
                  <section key={group}>
                    <h3>{group === 'primary' ? 'Primary colors' : 'Secondary colors'}</h3>
                    <div className="nl-brand-grid">
                      {kit.colors[group].map((value, index) => (
                        <div className="nl-brand-card" key={index}>
                          <ColorField
                            label={`${group === 'primary' ? 'Primary' : 'Secondary'} color ${index + 1}`}
                            value={value}
                            onChange={(value) =>
                              change((draft) => {
                                draft.colors[group][index] = value;
                              })
                            }
                          />
                          <button
                            aria-label={`Delete ${group} color ${index + 1}`}
                            onClick={() =>
                              change((draft) => {
                                draft.colors[group].splice(index, 1);
                              })
                            }
                          >
                            Delete color
                          </button>
                        </div>
                      ))}
                      <button
                        className="nl-brand-card"
                        disabled={kit.colors[group].length >= 20}
                        onClick={() =>
                          change((draft) => {
                            draft.colors[group].push('#ffffff');
                          })
                        }
                      >
                        Add {group === 'primary' ? 'primary' : 'secondary'} color
                      </button>
                    </div>
                  </section>
                ))}
              </>
            )}
            {category === 'Fonts' && (
              <>
                <NewsletterFontField
                  label="Heading"
                  value={kit.fonts.heading}
                  onChange={(value) =>
                    change((draft) => {
                      draft.fonts.heading = value;
                    })
                  }
                />
                <NewsletterFontField
                  label="Subheading and body"
                  value={kit.fonts.body}
                  onChange={(value) =>
                    change((draft) => {
                      draft.fonts.body = value;
                    })
                  }
                />
                <h3>Font Preview</h3>
                <div className="nl-brand-font-preview">
                  <h2
                    style={
                      newsletterCatalogStyle(kit.fonts.heading) ?? { fontFamily: kit.fonts.heading }
                    }
                  >
                    Your weekly policy briefing
                  </h2>
                  <p
                    style={newsletterCatalogStyle(kit.fonts.body) ?? { fontFamily: kit.fonts.body }}
                  >
                    Keep clients informed about the bills, news and developments that matter to
                    them.
                  </p>
                </div>
                <button
                  disabled={uploading || kit.fonts.uploaded.length >= 20}
                  onClick={() => fontInput.current?.click()}
                >
                  Upload Font
                </button>
                <p className="nl-muted">
                  TTF, OTF, WOFF or WOFF2 · up to 2 MB. Email apps that do not support custom fonts
                  use Arial.
                </p>
                <h3>Uploaded Custom Fonts</h3>
                {kit.fonts.uploaded.map((font) => (
                  <div className="nl-flex" key={font.assetId}>
                    <span style={{ fontFamily: font.family }}>{font.name}</span>
                    <button
                      aria-label={`Delete font ${font.name}`}
                      onClick={() =>
                        change((draft) => {
                          draft.fonts.uploaded = draft.fonts.uploaded.filter(
                            (item) => item.assetId !== font.assetId,
                          );
                          if (draft.fonts.heading.startsWith(font.family))
                            draft.fonts.heading = 'Arial';
                          if (draft.fonts.body.startsWith(font.family)) draft.fonts.body = 'Arial';
                          for (const button of draft.buttons)
                            if (button.fontFamily.startsWith(font.family))
                              button.fontFamily = 'Arial';
                        })
                      }
                    >
                      Delete font
                    </button>
                  </div>
                ))}
              </>
            )}
            {category === 'Buttons' && (
              <>
                <div className="nl-brand-grid">
                  {kit.buttons.map((item) => (
                    <div className="nl-brand-card" key={item.id}>
                      <span
                        className="nl-brand-button-preview"
                        style={previewStyle(newsletterBrandButtonStyle(item))}
                      >
                        Button
                      </span>
                      {kit.primaryButtonId === item.id && <span>Primary</span>}
                      <strong>{item.name}</strong>
                      <button
                        aria-label={`Button settings for ${item.name}`}
                        onClick={() => setSelection(item.id)}
                      >
                        Button settings
                      </button>
                      <button
                        aria-label={`Delete button ${item.name}`}
                        onClick={() =>
                          change((draft) => {
                            draft.buttons = draft.buttons.filter((button) => button.id !== item.id);
                            if (draft.primaryButtonId === item.id) draft.primaryButtonId = null;
                          })
                        }
                      >
                        Delete button
                      </button>
                    </div>
                  ))}
                  <button
                    className="nl-brand-card"
                    disabled={kit.buttons.length >= 20}
                    onClick={() => {
                      const id = newsletterId();
                      change((draft) => {
                        draft.buttons.push({
                          id,
                          name: `Button ${draft.buttons.length + 1}`,
                          shape: 'rounded',
                          variant: 'filled',
                          background: draft.colors.primary[0] || '#141414',
                          color: '#ffffff',
                          fontFamily: draft.fonts.body,
                        });
                      });
                      setSelection(id);
                    }}
                  >
                    Add Button
                  </button>
                </div>
                {button && (
                  <aside className="nl-brand-settings" aria-label="Button settings">
                    <Check
                      label="Primary button"
                      checked={kit.primaryButtonId === button.id}
                      onChange={(value) =>
                        change((draft) => {
                          draft.primaryButtonId = value ? button.id : null;
                        })
                      }
                    />
                    <TextField
                      label="Button name"
                      value={button.name}
                      onChange={(value) =>
                        change((draft) => {
                          draft.buttons.find((item) => item.id === button.id)!.name = value;
                        })
                      }
                    />
                    <fieldset className="nl-brand-segments">
                      <legend>Shape</legend>
                      {(['square', 'rounded', 'pill'] as const).map((shape) => (
                        <label key={shape}>
                          <input
                            type="radio"
                            name="brand-button-shape"
                            value={shape}
                            checked={button.shape === shape}
                            onChange={() =>
                              change((draft) => {
                                draft.buttons.find((item) => item.id === button.id)!.shape = shape;
                              })
                            }
                          />
                          {shape[0]!.toUpperCase() + shape.slice(1)}
                        </label>
                      ))}
                    </fieldset>
                    <fieldset className="nl-brand-segments">
                      <legend>Style</legend>
                      {(['filled', 'outlined'] as const).map((variant) => (
                        <label key={variant}>
                          <input
                            type="radio"
                            name="brand-button-variant"
                            value={variant}
                            checked={button.variant === variant}
                            onChange={() =>
                              change((draft) => {
                                draft.buttons.find((item) => item.id === button.id)!.variant =
                                  variant;
                              })
                            }
                          />
                          {variant[0]!.toUpperCase() + variant.slice(1)}
                        </label>
                      ))}
                    </fieldset>
                    <ColorField
                      label="Background"
                      value={button.background}
                      onChange={(value) =>
                        change((draft) => {
                          draft.buttons.find((item) => item.id === button.id)!.background = value;
                        })
                      }
                    />
                    <ColorField
                      label="Text"
                      value={button.color}
                      onChange={(value) =>
                        change((draft) => {
                          draft.buttons.find((item) => item.id === button.id)!.color = value;
                        })
                      }
                    />
                    <NewsletterFontField
                      value={button.fontFamily}
                      onChange={(value) =>
                        change((draft) => {
                          draft.buttons.find((item) => item.id === button.id)!.fontFamily = value;
                        })
                      }
                    />
                    <button onClick={() => setSelection(null)}>Done</button>
                  </aside>
                )}
              </>
            )}
          </div>
        </div>
        <footer>
          <button className="nl-primary" disabled={uploading} onClick={() => void close()}>
            Close
          </button>
        </footer>
      </Modal>
    </NewsletterBrandContext.Provider>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { NewsletterComment } from '@capiro/shared/newsletter';
import {
  newsletterError,
  type NewsletterClient,
  type NewsletterReviewers,
  type NewsletterAccountInvitation,
} from './api.js';
import { Modal, SelectField, Tabs, TextField } from './controls.js';
import { NewsletterThreadNotifications } from './NewsletterThreadNotifications.js';

export function NewsletterComments({
  api,
  documentId,
  blockId,
  onClose,
  onAnchor,
  beforeComment,
}: {
  api: NewsletterClient;
  documentId: string;
  blockId?: string;
  onClose?: () => void;
  onAnchor?: (id: string) => void;
  beforeComment?: () => Promise<unknown>;
}) {
  const [comments, setComments] = useState<NewsletterComment[]>([]);
  const [team, setTeam] = useState<NewsletterReviewers | null>(null);
  const [tab, setTab] = useState('Open');
  const [message, setMessage] = useState('');
  const [composing, setComposing] = useState(false);
  const [parent, setParent] = useState<string | undefined>();
  const [modal, setModal] = useState<'invite' | 'notifications' | 'thread' | null>(null);
  const [notificationTarget, setNotificationTarget] = useState<{ rootId?: string; draft: boolean }>(
    { draft: true },
  );
  const [draftUserIds, setDraftUserIds] = useState<string[] | undefined>();
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteMessage, setInviteMessage] = useState('');
  const [inviteNotice, setInviteNotice] = useState('');
  const [accountRole, setAccountRole] = useState<'member' | 'admin'>('member');
  const [accountInvitations, setAccountInvitations] = useState<
    Record<string, NewsletterAccountInvitation>
  >({});
  const inviteRequest = useRef<{ key: string; signature: string } | null>(null);
  const [role, setRole] = useState('commenter');
  const [mode, setMode] = useState('mentions');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [readError, setReadError] = useState('');
  const [reload, setReload] = useState(0);
  const [loading, setLoading] = useState(true);
  const composer = useRef<HTMLDivElement>(null);
  const addButton = useRef<HTMLButtonElement>(null);
  const writeGeneration = useRef(0);
  const writing = useRef(false);
  const wasComposing = useRef(false);
  useEffect(() => {
    let active = true;
    let latestRead = 0;
    const refresh = async () => {
      if (writing.current) return;
      const read = ++latestRead;
      const generation = writeGeneration.current;
      try {
        const [next, reviewers] = await Promise.all([
          api.comments(documentId),
          api.reviewers(documentId),
        ]);
        if (
          active &&
          read === latestRead &&
          generation === writeGeneration.current &&
          !writing.current
        ) {
          setComments(next);
          setTeam(reviewers);
          setReadError('');
        }
      } catch (error) {
        if (
          active &&
          read === latestRead &&
          generation === writeGeneration.current &&
          !writing.current
        )
          setReadError(newsletterError(error));
      } finally {
        if (active && read === latestRead) setLoading(false);
      }
    };
    void refresh();
    const timer = setInterval(() => void refresh(), 15000);
    return () => {
      active = false;
      clearInterval(timer);
    };
  }, [api, documentId, reload]);
  useEffect(() => {
    if (composing) composer.current?.querySelector('textarea')?.focus();
    else if (wasComposing.current) addButton.current?.focus();
    wasComposing.current = composing;
  }, [composing, parent]);
  const run = async (action: () => Promise<unknown>) => {
    if (writing.current) return;
    writing.current = true;
    writeGeneration.current++;
    setBusy(true);
    setError('');
    try {
      await action();
    } catch (error) {
      setError(newsletterError(error));
    } finally {
      writing.current = false;
      setBusy(false);
    }
  };
  const canComment = !!team && team.role !== 'viewer';
  const currentMember = team?.items.find((item) => item.userId === team.currentUserId);
  const editNotifications = () => {
    setMode(currentMember?.notifications || 'mentions');
    setModal('notifications');
  };
  const roots = comments.filter(
    (comment) => !comment.parentId && comment.resolved === (tab === 'Resolved'),
  );
  return (
    <aside className="nl-comments">
      <div className="nl-panel-head">
        <h2>Comments</h2>
        {onClose && (
          <button aria-label="Close comments" onClick={onClose}>
            ×
          </button>
        )}
      </div>
      {team?.role === 'owner' && <button onClick={() => setModal('invite')}>Invite</button>}
      {team && (
        <button disabled={busy} onClick={editNotifications}>
          In-app notifications
        </button>
      )}
      <Tabs value={tab} values={['Open', 'Resolved']} onChange={setTab} disabled={busy} />
      {error && <p role="alert">{error}</p>}
      {readError && (
        <p role="alert">
          {readError}{' '}
          <button onClick={() => setReload((value) => value + 1)}>Refresh comments</button>
        </p>
      )}
      {loading ? (
        <p role="status">Loading comments…</p>
      ) : (
        !roots.length &&
        !composing && (
          <p className="nl-muted">{tab === 'Open' ? 'No comments yet' : 'No resolved comments'}</p>
        )
      )}
      {roots.map((root) => (
        <article key={root.id}>
          {[root, ...comments.filter((comment) => comment.parentId === root.id)].map((comment) => (
            <div className={comment.parentId ? 'nl-comment-reply' : ''} key={comment.id}>
              <strong>{comment.authorName}</strong>
              <time>{new Date(comment.createdAt).toLocaleString()}</time>
              <p>{comment.message}</p>
            </div>
          ))}
          {root.blockId && onAnchor && (
            <button onClick={() => onAnchor(root.blockId!)}>View block</button>
          )}
          {canComment && (
            <>
              <button
                disabled={busy}
                onClick={() => {
                  setParent(root.id);
                  setDraftUserIds(undefined);
                  setMessage('');
                  setError('');
                  setComposing(true);
                }}
              >
                Reply
              </button>
              <button
                disabled={busy}
                onClick={() => {
                  setNotificationTarget({ rootId: root.id, draft: false });
                  setModal('thread');
                }}
              >
                Email notifications
              </button>
              <button
                disabled={busy}
                onClick={() =>
                  void run(async () =>
                    setComments(await api.resolve(documentId, root.id, !root.resolved)),
                  )
                }
              >
                {root.resolved ? 'Reopen' : 'Resolve'}
              </button>
            </>
          )}
        </article>
      ))}
      {canComment && !composing && tab === 'Open' && (
        <button
          ref={addButton}
          disabled={busy}
          onClick={() => {
            setError('');
            setParent(undefined);
            setDraftUserIds(undefined);
            setMessage('');
            setComposing(true);
          }}
        >
          Add comment
        </button>
      )}
      {canComment && composing && (
        <div className="nl-comment-composer" ref={composer}>
          <div className="nl-comment-author">
            <span className="nl-comment-avatar" aria-hidden="true">
              {(currentMember?.name || 'Team member')
                .split(/\s+/)
                .slice(0, 2)
                .map((part) => part[0])
                .join('')}
            </span>
            <strong>{currentMember?.name || 'Team member'}</strong>
          </div>
          {parent && (
            <p>
              Replying to a thread{' '}
              <button
                disabled={busy}
                onClick={() => {
                  setParent(undefined);
                  setDraftUserIds(undefined);
                  setMessage('');
                  setComposing(false);
                }}
              >
                Cancel reply
              </button>
            </p>
          )}
          <TextField
            label="Message"
            multiline
            value={message}
            onChange={setMessage}
            disabled={busy}
            placeholder="Add a comment"
          />
          {message.includes('@') && (
            <div className="nl-mention-list">
              {team?.items
                .filter((item) =>
                  item.name.toLowerCase().includes(message.split('@').pop()!.toLowerCase()),
                )
                .map((item) => (
                  <button
                    key={item.userId}
                    disabled={busy}
                    onClick={() =>
                      setMessage(message.slice(0, message.lastIndexOf('@')) + `@${item.name} `)
                    }
                  >
                    @{item.name}
                  </button>
                ))}
            </div>
          )}
          <p className="nl-muted">
            {blockId ? 'Comment on the selected block.' : 'Comment on the newsletter.'}
          </p>
          <button
            className="nl-primary"
            disabled={!message.trim() || busy}
            onClick={() =>
              void run(async () => {
                await beforeComment?.();
                setComments(
                  await (draftUserIds === undefined
                    ? api.comment(documentId, message, parent ? undefined : blockId, parent)
                    : api.comment(
                        documentId,
                        message,
                        parent ? undefined : blockId,
                        parent,
                        draftUserIds,
                      )),
                );
                setMessage('');
                setParent(undefined);
                setDraftUserIds(undefined);
                setComposing(false);
              })
            }
          >
            Comment
          </button>
          <button
            disabled={busy}
            onClick={() => {
              setMessage('');
              setParent(undefined);
              setDraftUserIds(undefined);
              setError('');
              setComposing(false);
            }}
          >
            Cancel
          </button>
          <button
            className="nl-comment-notifications"
            disabled={busy}
            onClick={() => {
              setNotificationTarget({ rootId: parent, draft: !parent });
              setModal('thread');
            }}
          >
            Edit notifications
          </button>
        </div>
      )}
      {modal === 'thread' && team && (
        <NewsletterThreadNotifications
          key={`${documentId}:${notificationTarget.rootId || 'new'}`}
          api={api}
          documentId={documentId}
          rootId={notificationTarget.rootId}
          currentUserId={team.currentUserId}
          draftUserIds={notificationTarget.draft ? draftUserIds : undefined}
          onClose={() => setModal(null)}
          onSaved={(ids) => {
            if (notificationTarget.draft) setDraftUserIds(ids);
            setModal(null);
          }}
        />
      )}
      {modal === 'invite' && (
        <Modal
          title="Invite your team"
          onClose={() => {
            if (!writing.current) {
              setModal(null);
              setInviteEmail('');
              setInviteMessage('');
              setAccountRole('member');
              inviteRequest.current = null;
            }
          }}
        >
          <div className="nl-modal-body nl-invite-form">
            <TextField
              label="Email address"
              type="email"
              value={inviteEmail}
              disabled={busy}
              placeholder="Ex: policy@example.com"
              onChange={setInviteEmail}
            />
            <SelectField
              label="Access level"
              disabled={busy}
              value={role}
              values={[
                ['editor', 'Author — Can edit, preview and comment'],
                ['commenter', 'Can preview and comment'],
                ['viewer', 'Can preview'],
              ]}
              onChange={setRole}
            />
            <TextField
              label="A message from you (optional)"
              multiline
              value={inviteMessage}
              disabled={busy}
              placeholder="Hi. Join me in reviewing this client newsletter."
              onChange={setInviteMessage}
            />
            {team?.canInviteAccounts && (
              <>
                <SelectField
                  label="Firm account role"
                  value={accountRole}
                  disabled={busy}
                  values={[
                    ['member', 'Member'],
                    ['admin', 'Admin'],
                  ]}
                  onChange={(value) => setAccountRole(value as 'member' | 'admin')}
                />
                <p>
                  {accountRole === 'admin'
                    ? 'Admin grants firm-wide user administration. This is separate from access to this newsletter.'
                    : 'New members receive a firm-joining invitation. Existing firm roles are preserved.'}
                </p>
              </>
            )}
            <p>
              {team?.canInviteAccounts
                ? 'Invite someone to join your firm and work on this newsletter. New members receive a firm-joining email, then the newsletter invitation with your personal message after joining and gaining client access.'
                : 'Invite a firm member to work on this newsletter. People outside your firm must join through Manage users first.'}{' '}
              Newsletter requests are saved for 30 days. Client access restrictions apply.
            </p>
            <h4>Who has access</h4>
            {team?.items.map((item) => (
              <p key={item.userId}>
                {item.name} ·{' '}
                {{ owner: 'Owner', editor: 'Author', commenter: 'Can comment', viewer: 'Viewer' }[
                  item.role
                ] || item.role}
                {item.role !== 'owner' && (
                  <button
                    disabled={busy}
                    onClick={() =>
                      void run(async () =>
                        setTeam(await api.removeReviewer(documentId, item.userId)),
                      )
                    }
                  >
                    Remove
                  </button>
                )}
              </p>
            ))}
            {!!team?.pending?.length && (
              <>
                <h4>Pending newsletter access</h4>
                {team.pending.map((item) => (
                  <div key={item.id}>
                    <p>
                      {item.email} · Waiting for firm membership and client access
                      <button
                        disabled={busy}
                        onClick={() =>
                          void run(async () =>
                            setTeam(await api.cancelInvitation(documentId, item.id)),
                          )
                        }
                      >
                        Cancel invitation
                      </button>
                    </p>
                    {item.accountRole === 'admin' && <p>Requested firm account role: Admin</p>}
                    {accountInvitations[item.id] && (
                      <p role="status">{accountInvitations[item.id]!.message}</p>
                    )}
                    {team?.canInviteAccounts && (
                      <div className="nl-flex">
                        {(!accountInvitations[item.id] ||
                          accountInvitations[item.id]!.canRetry) && (
                          <button
                            disabled={busy}
                            onClick={() =>
                              void run(async () => {
                                const result = await api.dispatchAccountInvitation(item.id);
                                setAccountInvitations((previous) => ({
                                  ...previous,
                                  [item.id]: result,
                                }));
                                setTeam(await api.reviewers(documentId));
                              })
                            }
                          >
                            Send firm invitation
                          </button>
                        )}
                        <button
                          disabled={busy}
                          onClick={() =>
                            void run(async () => {
                              const result = await api.accountInvitationStatus(item.id);
                              setAccountInvitations((previous) => ({
                                ...previous,
                                [item.id]: result,
                              }));
                              setTeam(await api.reviewers(documentId));
                            })
                          }
                        >
                          Check firm invitation
                        </button>
                      </div>
                    )}
                    {item.message && <blockquote>{item.message}</blockquote>}
                  </div>
                ))}
              </>
            )}
            {!!team?.pending?.length && (
              <p>
                Cancelling newsletter access retains firm invitations and firm membership. Manage
                users controls firm access.
              </p>
            )}
            <a href="/settings/team">Manage users</a>
          </div>
          <footer>
            <button
              disabled={busy}
              onClick={() => {
                setModal(null);
                setInviteEmail('');
                setInviteMessage('');
                setAccountRole('member');
                inviteRequest.current = null;
              }}
            >
              Cancel
            </button>
            <button
              className="nl-primary"
              disabled={
                !/^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(inviteEmail.trim()) ||
                inviteMessage.length > 2000 ||
                busy
              }
              onClick={() =>
                void run(async () => {
                  const email = inviteEmail.trim().toLowerCase(),
                    message = inviteMessage.trim();
                  const signature = JSON.stringify([documentId, email, role, message, accountRole]);
                  if (inviteRequest.current?.signature !== signature)
                    inviteRequest.current = { key: crypto.randomUUID(), signature };
                  const result = await api.inviteByEmail(documentId, {
                    email,
                    role,
                    message,
                    requestKey: inviteRequest.current.key,
                    ...(team?.canInviteAccounts ? { accountRole } : {}),
                  });
                  setTeam(result);
                  let account: NewsletterAccountInvitation | undefined;
                  if (result.invitation.status === 'pending' && team?.canInviteAccounts) {
                    try {
                      account = await api.dispatchAccountInvitation(result.invitation.id);
                      setAccountInvitations((previous) => ({
                        ...previous,
                        [account!.id]: account!,
                      }));
                      setTeam(await api.reviewers(documentId));
                    } catch (error) {
                      setInviteNotice(
                        `Newsletter request saved. ${newsletterError(error)} Use Check firm invitation before sending another request.`,
                      );
                      throw error;
                    }
                  }
                  setInviteNotice(
                    account
                      ? account.message
                      : result.invitation.status === 'pending'
                        ? 'Newsletter request saved. Add this person to your firm in Manage users; access activates after they join and have client access.'
                        : result.invitation.status === 'cancelled'
                          ? 'This invitation was cancelled. Its request was not sent again.'
                          : result.invitationEmailAvailable
                            ? 'Access saved. Invitation email queued.'
                            : 'Access saved. Invitation email delivery is currently unavailable.',
                  );
                  setInviteEmail('');
                  setInviteMessage('');
                  setAccountRole('member');
                  inviteRequest.current = null;
                  setModal(null);
                })
              }
            >
              Invite
            </button>
          </footer>
        </Modal>
      )}
      {inviteNotice && <p role="status">{inviteNotice}</p>}
      {modal === 'notifications' && (
        <Modal title="Comment notifications" onClose={() => setModal(null)}>
          <div className="nl-modal-body">
            <p>Notifications appear in your Capiro notification bell.</p>
            <SelectField
              label="Notify me about"
              value={mode}
              values={[
                ['all', 'All comments'],
                ['mentions', 'Mentions and replies'],
                ['none', 'No comments'],
              ]}
              onChange={setMode}
            />
          </div>
          <footer>
            <button onClick={() => setModal(null)}>Cancel</button>
            <button
              className="nl-primary"
              disabled={busy}
              onClick={() =>
                void run(async () => {
                  setTeam(await api.reviewNotifications(documentId, mode));
                  setModal(null);
                })
              }
            >
              Save
            </button>
          </footer>
        </Modal>
      )}
    </aside>
  );
}

import { useEffect, useRef, useState } from 'react';
import {
  ChevronDown,
  ChevronsLeft,
  ChevronLeft,
  ChevronRight,
  ChevronsRight,
  Grid2X2,
  List,
  Upload,
  Image,
} from 'lucide-react';
import { Modal, TextField } from './controls.js';
import { NewsletterAssetDetails, copyNewsletterAssetUrl } from './NewsletterAssetDetails.js';
import { NewsletterAssetFolders } from './NewsletterAssetFolders.js';
import { NewsletterStockImages } from './NewsletterStockImages.js';
import {
  newsletterError,
  type NewsletterAsset,
  type NewsletterAssetPage,
  type NewsletterAssetQuery,
  type NewsletterClient,
} from './api.js';

export function NewsletterContentStudio({
  api,
  onClose,
  onInsert,
}: {
  api: NewsletterClient;
  onClose: () => void;
  onInsert: (asset: NewsletterAsset) => void;
}) {
  const [query, setQuery] = useState<NewsletterAssetQuery>({
    page: 1,
    pageSize: 25,
    search: '',
    sort: 'newest',
  });
  const [result, setResult] = useState<NewsletterAssetPage | null>(null);
  const [selection, setSelection] = useState<NewsletterAsset[]>([]);
  const selected = selection.length === 1 ? selection[0] : null;
  const [details, setDetails] = useState<NewsletterAsset | null>(null);
  const [fileActions, setFileActions] = useState(false);
  const [copyAsset, setCopyAsset] = useState<NewsletterAsset | null>(null);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleteError, setDeleteError] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const pending = useRef(false);
  const [actions, setActions] = useState(false);
  const [importOpen, setImportOpen] = useState(false);
  const [importUrl, setImportUrl] = useState('');
  const [importError, setImportError] = useState('');
  const [view, setView] = useState<'grid' | 'list'>('grid');
  const [reload, setReload] = useState(0);
  const [pageInput, setPageInput] = useState('1');
  const [notice, setNotice] = useState('');
  const [source, setSource] = useState<'uploads' | 'stock'>('uploads');
  const [uploadProgress, setUploadProgress] = useState<{
    completed: number;
    total: number;
    name: string;
  } | null>(null);
  const [uploadFailures, setUploadFailures] = useState<{ name: string; message: string }[]>([]);
  const fileInput = useRef<HTMLInputElement>(null);
  const pages = Math.ceil((result?.total ?? 0) / query.pageSize);
  const setPage = (page: number) => {
    setQuery((previous) => ({ ...previous, page }));
    setPageInput(String(page));
    setSelection([]);
    setFileActions(false);
  };
  useEffect(() => {
    let canceled = false;
    setLoading(true);
    setError('');
    const timer = window.setTimeout(
      () => {
        api
          .assetPage(query)
          .then((page) => {
            if (canceled) return;
            if (!page.total && query.page > 1) {
              setPage(1);
              return;
            }
            if (page.total && (query.page - 1) * query.pageSize >= page.total) {
              setPage(Math.ceil(page.total / query.pageSize));
              return;
            }
            setResult(page);
            setLoading(false);
          })
          .catch((error) => {
            if (!canceled) {
              setError(newsletterError(error));
              setLoading(false);
            }
          });
      },
      query.search ? 200 : 0,
    );
    return () => {
      canceled = true;
      window.clearTimeout(timer);
    };
  }, [api, query, reload]);
  const filter = (next: Partial<NewsletterAssetQuery>) => {
    setQuery((previous) => ({ ...previous, ...next, page: 1 }));
    setPageInput('1');
    setSelection([]);
    setFileActions(false);
  };
  const add = async (operation: () => Promise<NewsletterAsset>, imported = false) => {
    if (pending.current) return;
    pending.current = true;
    setBusy(true);
    setError('');
    setImportError('');
    setUploadFailures([]);
    try {
      const asset = await operation();
      filter({ search: '', sort: 'newest' });
      setSelection([asset]);
      setReload((value) => value + 1);
      setImportOpen(false);
      setImportUrl('');
      setNotice(`${asset.name} added. Select Insert to use it in your newsletter.`);
    } catch (error) {
      if (imported) setImportError(newsletterError(error));
      else setError(newsletterError(error));
    } finally {
      pending.current = false;
      setBusy(false);
    }
  };
  const uploadFiles = async (files: File[]) => {
    if (pending.current || !files.length) return;
    pending.current = true;
    setBusy(true);
    setError('');
    setNotice('');
    setUploadFailures([]);
    setActions(false);
    const folderId = query.folder && query.folder !== 'unfiled' ? query.folder : undefined;
    const uploaded: NewsletterAsset[] = [];
    const failures: { name: string; message: string }[] = [];
    try {
      for (const [index, file] of files.entries()) {
        setUploadProgress({ completed: index, total: files.length, name: file.name });
        try {
          if (!file.size) throw new Error('Choose an image that is not empty.');
          if (file.size > 10 * 1024 * 1024) throw new Error('Images must be 10 MB or smaller.');
          const asset = folderId ? await api.upload(file, folderId) : await api.upload(file);
          uploaded.push(asset);
        } catch (error) {
          failures.push({ name: file.name, message: newsletterError(error) });
          setUploadFailures([...failures]);
        }
        setUploadProgress({ completed: index + 1, total: files.length, name: file.name });
      }
      if (uploaded.length) {
        filter({ search: '', sort: 'newest' });
        setSelection(uploaded.length === 1 ? uploaded : []);
        setNotice(
          uploaded.length === 1
            ? `${uploaded[0]!.name} added. Select Insert to use it in your newsletter.`
            : `${uploaded.length} images added. Select an image, then Insert to use it in your newsletter.`,
        );
      }
      setReload((value) => value + 1);
    } finally {
      setUploadProgress(null);
      pending.current = false;
      setBusy(false);
    }
  };
  const commitPage = () => {
    const requested = Number(pageInput);
    if (Number.isInteger(requested) && requested >= 1 && requested <= pages) setPage(requested);
    else setPageInput(String(query.page));
  };
  const remove = async () => {
    if (pending.current || !selection.length) return;
    pending.current = true;
    setBusy(true);
    setDeleteError('');
    try {
      const result = await api.deleteAssets(selection.map((asset) => asset.id));
      setSelection([]);
      setDeleteOpen(false);
      setFileActions(false);
      setReload((value) => value + 1);
      setNotice(
        `${result.deleted} ${result.deleted === 1 ? 'file' : 'files'} deleted from the library.`,
      );
    } catch (error) {
      setDeleteError(newsletterError(error));
    } finally {
      pending.current = false;
      setBusy(false);
    }
  };
  return (
    <Modal
      title="Content Studio"
      wide
      className="nl-content-studio"
      onClose={() => {
        if (!pending.current) onClose();
      }}
    >
      <input
        ref={fileInput}
        type="file"
        hidden
        multiple
        disabled={busy}
        accept="image/png,image/jpeg,image/gif,image/webp"
        onChange={(event) => {
          const files = Array.from(event.target.files ?? []);
          event.target.value = '';
          void uploadFiles(files);
        }}
      />
      <div className="nl-studio-layout">
        <aside className="nl-studio-sources" aria-label="Content sources">
          <div role="tablist" aria-label="Content Studio sources">
            <button
              role="tab"
              aria-selected={source === 'uploads'}
              disabled={busy}
              onClick={() => setSource('uploads')}
              aria-controls="nl-studio-uploads"
              id="nl-studio-uploads-tab"
            >
              <Upload size={19} /> Uploads
            </button>
            <button
              role="tab"
              aria-selected={source === 'stock'}
              aria-controls="nl-studio-stock"
              id="nl-studio-stock-tab"
              disabled={busy}
              onClick={() => {
                setSource('stock');
                setSelection([]);
                setFileActions(false);
                setActions(false);
              }}
            >
              <Image size={19} /> Stock images
            </button>
          </div>
        </aside>
        {source === 'stock' ? (
          <NewsletterStockImages
            api={api}
            onInsert={onInsert}
            onBusy={(value) => {
              pending.current = value;
              setBusy(value);
            }}
          />
        ) : (
          <div
            className="nl-modal-body nl-studio-uploads"
            role="tabpanel"
            id="nl-studio-uploads"
            aria-labelledby="nl-studio-uploads-tab"
            aria-busy={loading || busy}
          >
            <div className="nl-studio-toolbar">
              <label className="nl-studio-search">
                Search files
                <input
                  type="search"
                  value={query.search}
                  maxLength={200}
                  placeholder="Search files"
                  disabled={busy}
                  onChange={(event) => filter({ search: event.target.value })}
                />
              </label>
              <div className="nl-studio-upload">
                <button
                  className="nl-primary"
                  disabled={busy}
                  onClick={() => fileInput.current?.click()}
                >
                  {uploadProgress ? 'Uploading…' : busy ? 'Adding image…' : 'Upload'}
                </button>
                <button
                  className="nl-primary"
                  aria-label="Actions"
                  aria-haspopup="menu"
                  aria-expanded={actions}
                  disabled={busy}
                  onClick={() => setActions(!actions)}
                >
                  <ChevronDown size={16} />
                </button>
                {actions && (
                  <div role="menu" className="nl-studio-menu">
                    <button
                      role="menuitem"
                      onClick={() => {
                        setActions(false);
                        setImportOpen(true);
                        setImportError('');
                      }}
                    >
                      Import from URL
                    </button>
                  </div>
                )}
              </div>
            </div>
            <NewsletterAssetFolders
              api={api}
              folder={query.folder}
              selectedIds={loading || error ? [] : selection.map((asset) => asset.id)}
              busy={busy}
              pending={pending}
              onBusy={setBusy}
              onFilter={(folder) => filter({ folder })}
              onComplete={(message, options) => {
                if (options?.folder !== undefined) filter({ folder: options.folder });
                else if (options?.clearSelection !== false) setSelection([]);
                setNotice(message);
                setReload((value) => value + 1);
              }}
            />
            <div className="nl-studio-display">
              <label>
                Sort by{' '}
                <select
                  aria-label="Sort by"
                  value={query.sort}
                  disabled={busy}
                  onChange={(event) =>
                    filter({ sort: event.target.value as NewsletterAssetQuery['sort'] })
                  }
                >
                  <option value="newest">Newest first</option>
                  <option value="oldest">Oldest first</option>
                  <option value="name-asc">Name A–Z</option>
                  <option value="name-desc">Name Z–A</option>
                </select>
              </label>
              <div className="nl-studio-view">
                <button
                  aria-label="Grid view"
                  aria-pressed={view === 'grid'}
                  onClick={() => setView('grid')}
                >
                  <Grid2X2 size={18} />
                </button>
                <button
                  aria-label="List view"
                  aria-pressed={view === 'list'}
                  onClick={() => setView('list')}
                >
                  <List size={18} />
                </button>
              </div>
            </div>
            {!!result?.items.length && (
              <div className="nl-studio-file-actions">
                <button
                  disabled={busy || loading || !!error}
                  onClick={() => {
                    setSelection(selection.length === result.items.length ? [] : result.items);
                    setFileActions(false);
                  }}
                >
                  {selection.length === result.items.length
                    ? 'Clear selection'
                    : 'Select all on page'}
                </button>
                <span>{selection.length} selected</span>
                {selected && (
                  <div className="nl-studio-upload">
                    <button
                      disabled={busy || loading || !!error}
                      onClick={() => setDetails(selected)}
                    >
                      View Details
                    </button>
                    <button
                      aria-label="File actions"
                      aria-haspopup="menu"
                      aria-expanded={fileActions}
                      disabled={busy || loading || !!error}
                      onClick={() => setFileActions(!fileActions)}
                    >
                      <ChevronDown size={17} />
                    </button>
                    {fileActions && (
                      <div className="nl-studio-menu" role="menu">
                        <button
                          role="menuitem"
                          onClick={() => {
                            setFileActions(false);
                            void copyNewsletterAssetUrl(selected.url).then((message) => {
                              setNotice(message);
                              if (message !== 'URL copied.') setCopyAsset(selected);
                            });
                          }}
                        >
                          Copy URL
                        </button>
                      </div>
                    )}
                  </div>
                )}
                {!!selection.length && (
                  <button
                    disabled={busy || loading || !!error}
                    onClick={() => {
                      setDeleteError('');
                      setDeleteOpen(true);
                    }}
                  >
                    Delete
                  </button>
                )}
              </div>
            )}
            <p className="nl-muted">PNG, JPEG, GIF or WebP · up to 10 MB each</p>
            {uploadProgress && (
              <div className="nl-studio-upload-progress" role="status">
                <label>
                  Uploading images: {uploadProgress.completed} of {uploadProgress.total} complete
                  <progress
                    aria-label="Image upload progress"
                    max={uploadProgress.total}
                    value={uploadProgress.completed}
                  />
                </label>
                <span>{uploadProgress.name}</span>
              </div>
            )}
            {!!uploadFailures.length && (
              <div role="alert">
                <p>
                  {uploadFailures.length} {uploadFailures.length === 1 ? 'upload' : 'uploads'} could
                  not finish. Check the library before choosing those files again.
                </p>
                <ul>
                  {uploadFailures.map((failure, index) => (
                    <li key={index}>
                      {failure.name}: {failure.message}
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {error && (
              <div role="alert">
                <p>{error}</p>
                <button onClick={() => setReload((value) => value + 1)} disabled={busy}>
                  Try again
                </button>
              </div>
            )}
            {notice && <p role="status">{notice}</p>}
            {loading && <p role="status">Loading images…</p>}
            {!loading && !error && !result?.items.length && (
              <div className="nl-studio-empty">
                <Upload size={42} />
                <h3>
                  {query.search
                    ? 'No matching files'
                    : query.folder
                      ? 'Folder is empty'
                      : 'No uploaded files yet'}
                </h3>
                <p>
                  {query.search
                    ? 'Try another search.'
                    : query.folder
                      ? 'Add or move images into this folder.'
                      : 'Upload images to include in your newsletters.'}
                </p>
              </div>
            )}
            <div className={`nl-asset-grid${view === 'list' ? ' nl-studio-list' : ''}`}>
              {result?.items.map((asset) => (
                <button
                  key={asset.id}
                  aria-label={`Select ${asset.name}`}
                  aria-pressed={selection.some((item) => item.id === asset.id)}
                  disabled={loading || busy || !!error}
                  onClick={() => {
                    setSelection((previous) =>
                      previous.some((item) => item.id === asset.id)
                        ? previous.filter((item) => item.id !== asset.id)
                        : [...previous, asset],
                    );
                    setFileActions(false);
                  }}
                >
                  <img src={asset.url} alt="" />
                  <span>{asset.name}</span>
                  {view === 'list' && (
                    <span>{asset.mimeType.replace('image/', '').toUpperCase()}</span>
                  )}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
      {source === 'uploads' && (
        <footer className="nl-studio-footer">
          <div className="nl-studio-pagination">
            <label>
              Items per page{' '}
              <select
                aria-label="Items per page"
                value={query.pageSize}
                disabled={busy}
                onChange={(event) =>
                  filter({
                    pageSize: Number(event.target.value) as NewsletterAssetQuery['pageSize'],
                  })
                }
              >
                {[10, 25, 50, 100].map((size) => (
                  <option key={size}>{size}</option>
                ))}
              </select>
            </label>
            <span>
              Showing results{' '}
              <strong>
                {result?.total ? (query.page - 1) * query.pageSize + 1 : 0} –{' '}
                {Math.min(query.page * query.pageSize, result?.total ?? 0)} of {result?.total ?? 0}
              </strong>
            </span>
            <div className="nl-studio-page-buttons">
              <button
                aria-label="Go to first page"
                disabled={busy || loading || !!error || query.page === 1}
                onClick={() => setPage(1)}
              >
                <ChevronsLeft size={18} />
              </button>
              <button
                aria-label="Go to previous page"
                disabled={busy || loading || !!error || query.page === 1}
                onClick={() => setPage(query.page - 1)}
              >
                <ChevronLeft size={18} />
              </button>
              <label>
                Page{' '}
                <input
                  aria-label="Page number"
                  type="number"
                  min={1}
                  max={pages || 1}
                  value={pageInput}
                  disabled={busy || loading || !!error || !pages}
                  onChange={(event) => setPageInput(event.target.value)}
                  onBlur={commitPage}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter') {
                      event.preventDefault();
                      commitPage();
                    }
                  }}
                />
              </label>
              <span>of {pages}</span>
              <button
                aria-label="Go to next page"
                disabled={busy || loading || !!error || query.page >= pages}
                onClick={() => setPage(query.page + 1)}
              >
                <ChevronRight size={18} />
              </button>
              <button
                aria-label="Go to last page"
                disabled={busy || loading || !!error || query.page >= pages}
                onClick={() => setPage(pages)}
              >
                <ChevronsRight size={18} />
              </button>
            </div>
          </div>
          <div className="nl-studio-insert">
            <span>
              {selected?.name || (selection.length > 1 ? 'Select one image to insert.' : '')}
            </span>
            <button
              className="nl-primary"
              disabled={busy || loading || !!error || !selected}
              onClick={() => {
                if (selected) onInsert(selected);
              }}
            >
              Insert
            </button>
          </div>
        </footer>
      )}
      {details && (
        <NewsletterAssetDetails
          api={api}
          asset={details}
          onClose={() => setDetails(null)}
          onInsert={onInsert}
          onRenamed={(asset) => {
            setDetails(asset);
            setSelection((previous) =>
              previous.map((item) => (item.id === asset.id ? asset : item)),
            );
            setReload((value) => value + 1);
          }}
        />
      )}
      {copyAsset && (
        <Modal title="Image URL" onClose={() => setCopyAsset(null)}>
          <div className="nl-modal-body">
            <p>Clipboard access is unavailable. Select and copy the image URL.</p>
            <label className="nl-field">
              Image URL
              <input
                readOnly
                value={copyAsset.url}
                onFocus={(event) => event.currentTarget.select()}
              />
            </label>
          </div>
        </Modal>
      )}
      {deleteOpen && (
        <Modal
          title="Are you sure?"
          onClose={() => {
            if (!pending.current) setDeleteOpen(false);
          }}
        >
          <div className="nl-modal-body">
            <p>
              Delete {selection.length} {selection.length === 1 ? 'file' : 'files'} from the
              library, including their saved versions?
            </p>
            <p>Images remain available in newsletters that already use them.</p>
            <ul className="nl-studio-delete-list">
              {selection.map((asset) => (
                <li key={asset.id}>{asset.name}</li>
              ))}
            </ul>
            {deleteError && <p role="alert">{deleteError}</p>}
          </div>
          <div className="nl-studio-import-actions">
            <button disabled={busy} onClick={() => setDeleteOpen(false)}>
              Cancel
            </button>
            <button className="nl-primary" disabled={busy} onClick={() => void remove()}>
              {busy ? 'Deleting…' : 'Delete'}
            </button>
          </div>
        </Modal>
      )}
      {importOpen && (
        <Modal
          title="Import URL"
          onClose={() => {
            if (!pending.current) setImportOpen(false);
          }}
        >
          <form
            onSubmit={(event) => {
              event.preventDefault();
              if (importUrl.trim())
                void add(
                  () =>
                    query.folder && query.folder !== 'unfiled'
                      ? api.importAsset(importUrl.trim(), query.folder)
                      : api.importAsset(importUrl.trim()),
                  true,
                );
            }}
          >
            <div className="nl-modal-body">
              <TextField
                label="Import a file from a URL:"
                value={importUrl}
                onChange={setImportUrl}
                placeholder="https://example.com/image.png"
              />
              {importError && <p role="alert">{importError}</p>}
            </div>
            <div className="nl-studio-import-actions">
              <button type="submit" className="nl-primary" disabled={busy || !importUrl.trim()}>
                {busy ? 'Importing…' : 'Import'}
              </button>
              <button type="button" disabled={busy} onClick={() => setImportOpen(false)}>
                Cancel
              </button>
            </div>
          </form>
        </Modal>
      )}
    </Modal>
  );
}

