];
type ImageHistoryEntry = { edit: NewsletterImageEdit; selectedText: number };
export function NewsletterImageEditor({
  url,
  onClose,
  onSave,
}: {
  url: string;
  onClose: () => void;
  onSave: (file: File) => Promise<void>;
}) {
  const [image, setImage] = useState<HTMLImageElement | null>(null);
  const [edit, setEdit] = useState<NewsletterImageEdit | null>(null);
  const [history, setHistory] = useState<ImageHistoryEntry[]>([]);
  const [future, setFuture] = useState<ImageHistoryEntry[]>([]);
  const [panel, setPanel] = useState('Crop or Resize');
  const [locked, setLocked] = useState(false);
  const [selectedText, setSelectedText] = useState(0);
  const selectedTextRef = useRef(0);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [validPreview, setValidPreview] = useState(false);
  const [loadingFonts, setLoadingFonts] = useState(false);
  const [zoom, setZoom] = useState(100);
  const canvas = useRef<HTMLCanvasElement>(null);
  const previewArea = useRef<HTMLDivElement>(null);
  const zoomChanged = useRef(false);
  const [textLayouts, setTextLayouts] = useState<NewsletterImageTextLayout[]>([]);
  const dragStart = useRef<ImageHistoryEntry | null>(null);
  const plane =
    image && edit
      ? newsletterImagePlane(
          image.naturalWidth,
          image.naturalHeight,
          edit.rotate,
          edit.quarterTurns,
        )
      : null;
  const cropping = panel === 'Crop or Resize';
  const previewWidth = cropping && plane ? plane.width : (edit?.width ?? 1);
  const previewHeight = cropping && plane ? plane.height : (edit?.height ?? 1);
  const cropRatio =
    plane && edit ? (plane.width * edit.crop.width) / (plane.height * edit.crop.height) : 0;
  const activeCrop = locked
    ? (COMMON_CROPS.find(([, ratio]) => ratio && Math.abs(cropRatio - ratio) < 0.001)?.[0] ??
      'Custom')
    : 'Custom';
  useEffect(() => {
    let cancelled = false;
    void loadNewsletterImage(url)
      .then((value) => {
        if (cancelled) return;
        setImage(value);
        setEdit(defaultNewsletterImageEdit(value.naturalWidth, value.naturalHeight));
      })
      .catch((reason) => {
        if (!cancelled) setError(reason.message);
      });
    return () => {
      cancelled = true;
    };
  }, [url]);
  useEffect(() => {
    if (!image || !edit || !canvas.current) return;
    let cancelled = false;
    setValidPreview(false);
    setLoadingFonts(!!edit.texts.length);
    void loadNewsletterImageFonts(edit.texts)
      .then(() => {
        if (cancelled || !canvas.current) return;
        const preview = cropping
          ? drawNewsletterCropPreview(image, edit, 1000)
          : drawNewsletterImage(image, edit, 1000);
        const output = canvas.current;
        output.width = preview.width;
        output.height = preview.height;
        const context = output.getContext('2d');
        if (!context) throw new Error('Image editing is unavailable in this browser.');
        context.drawImage(preview, 0, 0);
        setTextLayouts(
          edit.texts.map((text) => newsletterImageTextLayout(context, text, edit.width)),
        );
        setValidPreview(true);
        setError('');
      })
      .catch((reason) => {
        if (!cancelled) setError((reason as Error).message);
      })
      .finally(() => {
        if (!cancelled) setLoadingFonts(false);
      });
    return () => {
      cancelled = true;
    };
  }, [image, edit, cropping]);
  useEffect(() => {
    const area = previewArea.current;
    if (!area || !edit || zoomChanged.current) return;
    const fit = () => {
      if (zoomChanged.current) return;
      const bounds = area.getBoundingClientRect();
      setZoom(
        Math.max(
          5,
          Math.min(
            300,
            Math.floor(
              Math.min((bounds.width - 48) / previewWidth, (bounds.height - 48) / previewHeight) *
                100,
            ),
          ),
        ),
      );
    };
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(area);
    return () => observer.disconnect();
  }, [image, previewWidth, previewHeight]);
  const changeZoom = (value: number) => {
    zoomChanged.current = true;
    setZoom(Math.max(5, Math.min(300, value)));
  };
  const tools = [
    ['Crop or Resize', Crop],
    ['Filters', Flame],
    ['Adjust', SlidersHorizontal],
    ['Focus', Droplet],
    ['Text', Type],
    ['Text Design', Bookmark],
  ] as const;
  function saveImage() {
    if (!image || !edit || busy || !validPreview) return;
    setBusy(true);
    setError('');
    void newsletterEditedImageFile(image, edit)
      .then(onSave)
      .then(onClose)
      .catch((reason) => setError(reason.message))
      .finally(() => setBusy(false));
  }
  function change(update: (value: NewsletterImageEdit) => void) {
    if (!edit || busy) return;
    const previous = { edit, selectedText: selectedTextRef.current };
    const next = structuredClone(edit);
    update(next);
    setHistory((items) => [...items.slice(-24), previous]);
    setFuture([]);
    setEdit(next);
  }
  const overlay = edit?.texts[selectedText];
  function selectText(index: number) {
    selectedTextRef.current = index;
    setSelectedText(index);
  }
  function restore(entry: ImageHistoryEntry) {
    setEdit(entry.edit);
    selectText(Math.min(entry.selectedText, Math.max(0, entry.edit.texts.length - 1)));
  }
  function selectTool(name: string) {
    setPanel(name);
    if (name === 'Text' && edit && !edit.texts.length) addText();
  }
  function finishDrag(cancelled: boolean) {
    const previous = dragStart.current;
    if (previous) {
      if (cancelled) restore(previous);
      else if (JSON.stringify(previous.edit) !== JSON.stringify(edit)) {
        setHistory((items) => [...items.slice(-24), previous]);
        setFuture([]);
      }
    }
    dragStart.current = null;
  }
  function addText(preset?: (typeof TEXT_DESIGNS)[number]) {
    if (!edit || busy) return;
    change((value) => {
      value.texts.push(
        preset
          ? { ...preset, text: preset.name, x: 50, y: 40, lineHeight: 1.1 }
          : {
              text: 'Double click to edit',
              font: 'Open Sans',
              size: 43,
              bold: true,
              fontWeight: 700,
              align: 'center',
              color: '#ffffff',
              background: 'transparent',
              x: 50,
              y: (Math.max(0, (value.height - 43 * 1.1) / 2) * 100) / value.height,
              lineHeight: 1.1,
              boxWidth: 50,
            },
      );
    });
    selectText(edit.texts.length);
  }
  function duplicateText() {
    if (!overlay || !edit || busy) return;
    change((next) => {
      next.texts.push(structuredClone(overlay));
    });
    selectText(edit.texts.length);
  }
  function removeText() {
    if (!overlay || busy) return;
    change((next) => {
      next.texts.splice(selectedText, 1);
    });
    selectText(Math.max(0, selectedText - 1));
  }
  function bringTextToFront() {
    if (!overlay || !edit || busy || selectedText === edit.texts.length - 1) return;
    change((next) => {
      const [text] = next.texts.splice(selectedText, 1);
      next.texts.push(text!);
    });
    selectText(edit.texts.length - 1);
  }
  function crop(ratio: number | null) {
    if (!plane) return;
    setLocked(!!ratio);
    if (!ratio) return;
    change((value) => {
      const naturalRatio = plane.width / plane.height;
      const width = ratio >= naturalRatio ? 100 : (ratio / naturalRatio) * 100;
      const height = ratio <= naturalRatio ? 100 : (naturalRatio / ratio) * 100;
      value.crop = { x: (100 - width) / 2, y: (100 - height) / 2, width, height };
      value.width = Math.round((plane.width * width) / 100);
      value.height = Math.round((plane.height * height) / 100);
    });
  }
  function withCrop(value: NewsletterImageEdit, nextCrop: NewsletterCropRect) {
    const width = (value.width * nextCrop.width) / value.crop.width;
    const height = (value.height * nextCrop.height) / value.crop.height;
    const scale = Math.min(1, 4096 / Math.max(width, height));
    return {
      ...value,
      crop: nextCrop,
      width: Math.max(1, Math.round(width * scale)),
      height: Math.max(1, Math.round(height * scale)),
    };
  }
  function rotate(clockwise: boolean) {
    change((value) => {
      value.rotate += clockwise ? 90 : -90;
      value.quarterTurns += clockwise ? 1 : -1;
      value.crop = rotateNewsletterCrop(value.crop, clockwise);
      [value.width, value.height] = [value.height, value.width];
      [value.flipX, value.flipY] = [value.flipY, value.flipX];
    });
  }
  function straighten(angle: number, continuous: boolean) {
    if (busy) return;
    const update = (value: NewsletterImageEdit) => {
      value.rotate = value.quarterTurns * 90 + angle;
    };
    if (continuous)
      setEdit((previous) => {
        if (!previous) return previous;
        const next = { ...previous };
        update(next);
        return next;
      });
    else change(update);
  }
  return (
    <Modal
      title="Edit image"
      wide
      className="nl-photo-editor"
      hideHeader
      onClose={() => {
        if (!busy) onClose();
      }}
    >
      <div className="nl-photo-toolbar">
        <div className="nl-photo-panel-title">{panel}</div>
        <div className="nl-photo-main-toolbar">
          <div className="nl-photo-history">
            <button
              aria-label="Undo image edit"
              title="Undo"
              disabled={!history.length || busy}
              onClick={() => {
                setFuture((previous) => [{ edit: edit!, selectedText }, ...previous]);
                restore(history.at(-1)!);
                setHistory((previous) => previous.slice(0, -1));
              }}
            >
              <Undo2 size={20} />
            </button>
            <button
              aria-label="Redo image edit"
              title="Redo"
              disabled={!future.length || busy}
              onClick={() => {
                setHistory((previous) => [...previous, { edit: edit!, selectedText }]);
                restore(future[0]!);
                setFuture((previous) => previous.slice(1));
              }}
            >
              <Redo2 size={20} />
            </button>
          </div>
          <div className="nl-photo-zoom">
            <button
              aria-label="Zoom out"
              title="Zoom out"
              disabled={zoom <= 5}
              onClick={() => changeZoom(zoom - 10)}
            >
              <Minus size={14} />
            </button>
            <NumberField label="Zoom (%)" min={5} max={300} value={zoom} onChange={changeZoom} />
            <span>%</span>
            <button
              aria-label="Zoom in"
              title="Zoom in"
              disabled={zoom >= 300}
              onClick={() => changeZoom(zoom + 10)}
            >
              <Plus size={14} />
            </button>
          </div>
          <div className="nl-photo-save-actions">
            <button
              aria-label="Save image"
              disabled={!image || !edit || busy || !validPreview}
              onClick={saveImage}
            >
              {busy ? 'Saving…' : 'Save'}
            </button>
            <button disabled={busy} onClick={onClose}>
              Close
            </button>
          </div>
        </div>
      </div>
      <div className="nl-photo-body">
        <div
          className="nl-photo-tools"
          role="tablist"
          aria-label="Photo editing tools"
          aria-orientation="vertical"
        >
          {tools.map(([name, Icon], index) => (
            <button
              key={name}
              type="button"
              role="tab"
              aria-selected={panel === name}
              tabIndex={panel === name ? 0 : -1}
              title={name}
              aria-label={name}
              disabled={!edit || busy}
              onClick={() => selectTool(name)}
              onKeyDown={(event) => {
                const direction = event.key === 'ArrowDown' ? 1 : event.key === 'ArrowUp' ? -1 : 0;
                if (!direction && !['Home', 'End'].includes(event.key)) return;
                event.preventDefault();
                const next =
                  event.key === 'Home'
                    ? 0
                    : event.key === 'End'
                      ? tools.length - 1
                      : (index + direction + tools.length) % tools.length;
                selectTool(tools[next]![0]);
                (event.currentTarget.parentElement?.children[next] as HTMLButtonElement)?.focus();
              }}
            >
              <Icon size={23} />
            </button>
          ))}
        </div>
        <aside className="nl-photo-controls">
          <div className="nl-photo-controls-scroll">
            {edit && panel === 'Crop or Resize' && (
              <>
                <button
                  className="nl-photo-reset"
                  disabled={busy}
                  onClick={() => {
                    setLocked(false);
                    image &&
                      change((next) => {
                        const initial = defaultNewsletterImageEdit(
                          image.naturalWidth,
                          image.naturalHeight,
                        );
                        next.crop = initial.crop;
                        next.width = initial.width;
                        next.height = initial.height;
                        next.rotate = 0;
                        next.quarterTurns = 0;
                        next.flipX = false;
                        next.flipY = false;
                      });
                  }}
                >
                  Reset Default
                </button>
                <h3>Common crops</h3>
                <div className="nl-photo-grid nl-photo-crops">
                  {COMMON_CROPS.map(([name, ratio]) => (
                    <button
                      key={name}
                      disabled={busy}
                      aria-pressed={activeCrop === name}
                      onClick={() => crop(ratio)}
                    >
                      <span
                        className={`nl-photo-crop-shape nl-photo-crop--${String(name).toLowerCase()}`}
                      />
                      {name}
                    </button>
                  ))}
                </div>
              </>
            )}
            {edit && panel === 'Filters' && (
              <div className="nl-photo-grid">
                {FILTERS.map((name) => (
                  <button
                    key={name}
                    aria-pressed={edit.filter === name}
                    onClick={() =>
                      change((value) => {
                        value.filter = name;
                      })
                    }
                  >
                    {name}
                  </button>
                ))}
              </div>
            )}
            {edit &&
              panel === 'Adjust' &&
              IMAGE_ADJUSTMENTS.map((key) => (
                <NumberField
                  key={key}
                  label={key}
                  min={key === 'Sharpness' ? 0 : -100}
                  max={100}
                  value={edit.adjustments[key]}
                  onChange={(value) =>
                    change((next) => {
                      next.adjustments[key] = value;
                    })
                  }
                />
              ))}
            {edit && panel === 'Focus' && (
              <>
                <SelectField
                  label="Focus"
                  value={edit.focus}
                  values={['None', 'Radial', 'Mirrored', 'Linear', 'Gaussian']}
                  onChange={(value) =>
                    change((next) => {
                      next.focus = value;
                    })
                  }
                />
                <NumberField
                  label="Blur amount"
                  min={0}
                  max={30}
                  value={edit.blur}
                  onChange={(value) =>
                    change((next) => {
                      next.blur = value;
                    })
                  }
                />
                {!['None', 'Gaussian'].includes(edit.focus) && (
                  <>
                    {(['x', 'y', 'size', 'angle'] as const).map((key) => (
                      <NumberField
                        key={key}
                        label={`Focus ${key}${key === 'angle' ? ' (degrees)' : ' (%)'}`}
                        min={key === 'angle' ? -180 : key === 'size' ? 1 : 0}
                        max={key === 'angle' ? 180 : 100}
                        value={edit.focusRegion[key]}
                        onChange={(value) =>
                          change((next) => {
                            next.focusRegion[key] = value;
                          })
                        }
                      />
                    ))}
                    <p className="nl-muted">
                      Drag the focus area or its handles. Arrow keys move a focused handle; Shift
                      changes it by ten.
                    </p>
                  </>
                )}
              </>
            )}
            {edit && panel === 'Text Design' && (
              <div className="nl-photo-grid">
                {TEXT_DESIGNS.map((preset) => (
                  <button
                    key={preset.name}
                    onClick={() => {
                      addText(preset);
                      setPanel('Text');
                    }}
                  >
                    {preset.name}
                  </button>
                ))}
              </div>
            )}
            {edit && panel === 'Text' && (
              <>
                <button onClick={() => addText()}>New text</button>
                {!!edit.texts.length && (
                  <SelectField
                    label="Text layer"
                    value={String(selectedText)}
                    values={edit.texts.map((text, index) => [
                      String(index),
                      text.text.slice(0, 30) || `Text ${index + 1}`,
                    ])}
                    onChange={(value) => selectText(Number(value))}
                  />
                )}
                {overlay && (
                  <>
                    <TextField
                      label="Image text"
                      multiline
                      value={overlay.text}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.text = value;
                        })
                      }
                    />
                    <NewsletterFontField
                      label="Image text font"
                      value={overlay.font}
                      onChange={(value) =>
                        change((next) => {
                          const face = newsletterCatalogStyle(value),
                            text = next.texts[selectedText]!;
                          text.font = value;
                          text.fontWeight = face?.fontWeight ?? 400;
                          text.bold = (face?.fontWeight ?? 400) >= 700;
                          text.italic = face?.fontStyle === 'italic';
                        })
                      }
                    />
                    <NumberField
                      label="Image text size"
                      min={8}
                      max={300}
                      value={overlay.size}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.size = value;
                        })
                      }
                    />
                    <Check
                      label="Image text bold"
                      checked={overlay.bold}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.bold = value;
                          next.texts[selectedText]!.fontWeight = value ? 700 : 400;
                        })
                      }
                    />
                    <Check
                      label="Image text italic"
                      checked={overlay.italic ?? false}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.italic = value;
                        })
                      }
                    />
                    <NumberField
                      label="Image text letter spacing"
                      min={-10}
                      max={100}
                      value={overlay.letterSpacing ?? 0}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.letterSpacing = value;
                        })
                      }
                    />
                    <NumberField
                      label="Image text rotation (degrees)"
                      min={-180}
                      max={180}
                      value={overlay.rotation ?? 0}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.rotation = value;
                        })
                      }
                    />
                    <NumberField
                      label="Image text box width (%)"
                      min={1}
                      max={100}
                      value={
                        overlay.boxWidth ??
                        Math.min(
                          100,
                          ((textLayouts[selectedText]?.width ?? edit.width / 2) * 100) / edit.width,
                        )
                      }
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.boxWidth = value;
                        })
                      }
                    />
                    <SelectField
                      label="Image text alignment"
                      value={overlay.align}
                      values={['left', 'center', 'right']}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.align = value;
                        })
                      }
                    />
                    <ColorField
                      label="Image text color"
                      value={overlay.color}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.color = value;
                        })
                      }
                    />
                    <ColorField
                      label="Image text background"
                      value={overlay.background}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.background = value;
                        })
                      }
                    />
                    <button
                      onClick={() =>
                        change((next) => {
                          next.texts[selectedText]!.background = 'transparent';
                        })
                      }
                    >
                      Remove text background
                    </button>
                    <NumberField
                      label="Image text line spacing"
                      min={0.5}
                      max={3}
                      step={0.1}
                      value={overlay.lineHeight}
                      onChange={(value) =>
                        change((next) => {
                          next.texts[selectedText]!.lineHeight = value;
                        })
                      }
                    />
                    {(['x', 'y'] as const).map((key) => (
                      <NumberField
                        key={key}
                        label={`Image text ${key} (%)`}
                        value={overlay[key]}
                        min={0}
                        max={100}
                        onChange={(value) =>
                          change((next) => {
                            next.texts[selectedText]![key] = value;
                          })
                        }
                      />
                    ))}
                    <button onClick={duplicateText}>Duplicate text</button>
                    <button onClick={removeText}>Remove text</button>
                    <p className="nl-muted">Drag in the preview to position the selected text.</p>
                  </>
                )}
              </>
            )}
          </div>
          {edit && cropping && (
            <fieldset className="nl-photo-crop-dimensions" disabled={busy}>
              <Check label="Lock dimensions" checked={locked} onChange={setLocked} />
              <div className="nl-photo-dimensions">
                {(['width', 'height'] as const).map((key) => (
                  <div key={key}>
                    <NumberField
                      label={`Image ${key} (px)`}
                      value={edit[key]}
                      min={1}
                      max={4096}
                      onChange={(value) =>
                        change((next) => {
                          const other = key === 'width' ? 'height' : 'width';
                          const requested = locked
                            ? Math.min(value, (4096 * next[key]) / next[other])
                            : value;
                          if (locked)
                            next[other] = Math.max(
                              1,
                              Math.round((requested * next[other]) / next[key]),
                            );
                          next[key] = Math.max(1, Math.round(requested));
                        })
                      }
                    />
                    <span>{key === 'width' ? 'w' : 'h'}</span>
                  </div>
                ))}
              </div>
            </fieldset>
          )}
        </aside>
        <div className="nl-photo-stage">
          <div className="nl-photo-preview" ref={previewArea}>
            {!image && !error && <p role="status">Loading image…</p>}
            {loadingFonts && <p role="status">Loading image fonts…</p>}
            <div
              className="nl-photo-image-surface"
              style={{ width: edit ? `${(previewWidth * zoom) / 100}px` : '100%' }}
            >
              <canvas
                ref={canvas}
                aria-label="Edited image preview"
                style={{ width: '100%', touchAction: 'none' }}
              />
              {edit && plane && cropping && (
                <NewsletterImageCropOverlay
                  crop={edit.crop}
                  width={plane.width}
                  height={plane.height}
                  locked={locked}
                  disabled={busy}
                  onBegin={() => {
                    dragStart.current = { edit, selectedText: selectedTextRef.current };
                  }}
                  onMove={(nextCrop) => {
                    if (!busy)
                      setEdit((previous) => (previous ? withCrop(previous, nextCrop) : previous));
                  }}
                  onFinish={finishDrag}
                  onKeyChange={(nextCrop) =>
                    change((next) => Object.assign(next, withCrop(next, nextCrop)))
                  }
                />
              )}
              {edit && panel === 'Text' && (
                <NewsletterImageTextOverlay
                  edit={edit}
                  layouts={textLayouts}
                  selected={selectedText}
                  disabled={busy}
                  onSelect={selectText}
                  onBegin={() => {
                    dragStart.current = { edit, selectedText: selectedTextRef.current };
                  }}
                  onMove={(index, text) => {
                    if (!busy)
                      setEdit((previous) => {
                        if (!previous) return previous;
                        const texts = [...previous.texts];
                        texts[index] = text;
                        return { ...previous, texts };
                      });
                  }}
                  onFinish={finishDrag}
                  onKeyChange={(index, text) =>
                    change((next) => {
                      next.texts[index] = text;
                    })
                  }
                  onDuplicate={duplicateText}
                  onRemove={removeText}
                  onBringToFront={bringTextToFront}
                />
              )}
              {edit && panel === 'Focus' && (
                <NewsletterImageFocusOverlay
                  edit={edit}
                  disabled={busy}
                  onBegin={() => {
                    dragStart.current = { edit, selectedText: selectedTextRef.current };
                  }}
                  onMove={(region) => {
                    if (!busy)
                      setEdit((previous) =>
                        previous ? { ...previous, focusRegion: region } : previous,
                      );
                  }}
                  onFinish={finishDrag}
                  onKeyChange={(region) =>
                    change((next) => {
                      next.focusRegion = region;
                    })
                  }
                />
              )}
            </div>
          </div>
          {edit && cropping && (
            <div className="nl-photo-transform-controls">
              <button
                aria-label="Flip horizontal"
                title="Flip horizontal"
                aria-pressed={edit.flipX}
                disabled={busy}
                onClick={() =>
                  change((next) => {
                    next.flipX = !next.flipX;
                  })
                }
              >
                <FlipHorizontal size={18} />
              </button>
              <button
                aria-label="Flip vertical"
                title="Flip vertical"
                aria-pressed={edit.flipY}
                disabled={busy}
                onClick={() =>
                  change((next) => {
                    next.flipY = !next.flipY;
                  })
                }
              >
                <FlipVertical size={18} />
              </button>
              <NewsletterImageRotationRuler
                angle={Math.round((edit.rotate - edit.quarterTurns * 90) * 10) / 10}
                disabled={busy}
                onBegin={() => {
                  dragStart.current = { edit, selectedText: selectedTextRef.current };
                }}
                onMove={(angle) => straighten(angle, true)}
                onFinish={finishDrag}
                onKeyChange={(angle) => straighten(angle, false)}
              />
              <button
                aria-label="Rotate left"
                title="Rotate left"
                disabled={busy}
                onClick={() => rotate(false)}
              >
                <RotateCcw size={18} />
              </button>
              <button
                aria-label="Rotate right"
                title="Rotate right"
                disabled={busy}
                onClick={() => rotate(true)}
              >
                <RotateCw size={18} />
              </button>
            </div>
          )}
        </div>
      </div>
      {error && (
        <p className="nl-error" role="alert">
          {error}
        </p>
      )}
    </Modal>
  );
}

import { useRef, type KeyboardEvent, type PointerEvent } from 'react';
import { newsletterFocusGeometry, type NewsletterImageEdit } from './image-editor.js';

type Region = NewsletterImageEdit['focusRegion'];
type DragKind = 'move' | 'resize' | 'rotate';
const bound = (value: number, min = 0, max = 100) => Math.max(min, Math.min(max, value));

/** Focus handles use the same output coordinates as the raster mask. */
export function NewsletterImageFocusOverlay({
  edit,
  disabled = false,
  onBegin,
  onMove,
  onFinish,
  onKeyChange,
}: {
  edit: NewsletterImageEdit;
  disabled?: boolean;
  onBegin: () => void;
  onMove: (region: Region) => void;
  onFinish: (cancelled: boolean) => void;
  onKeyChange: (region: Region) => void;
}) {
  const drag = useRef<{ kind: DragKind; x: number; y: number; region: Region } | null>(null);
  if (edit.focus === 'None' || edit.focus === 'Gaussian') return null;
  const { width, height } = edit;
  const region = newsletterFocusGeometry(edit, width, height);
  const handle = Math.max(width, height) * 0.009;
  const line = Math.hypot(width, height);
  const angle = edit.focusRegion.angle;
  const begin = (event: PointerEvent<SVGElement>, kind: DragKind) => {
    if (disabled) return;
    event.preventDefault();
    const svg = event.currentTarget.ownerSVGElement;
    if (!svg) return;
    svg.setPointerCapture(event.pointerId);
    drag.current = { kind, x: event.clientX, y: event.clientY, region: { ...edit.focusRegion } };
    onBegin();
  };
  const keyboard = (event: KeyboardEvent<SVGElement>, kind: DragKind) => {
    if (disabled) return;
    const step = event.shiftKey ? 10 : 1;
    const next = { ...edit.focusRegion };
    if (kind === 'move') {
      if (event.key === 'ArrowLeft') next.x = bound(next.x - step);
      else if (event.key === 'ArrowRight') next.x = bound(next.x + step);
      else if (event.key === 'ArrowUp') next.y = bound(next.y - step);
      else if (event.key === 'ArrowDown') next.y = bound(next.y + step);
      else return;
    } else {
      if (!['ArrowLeft', 'ArrowDown', 'ArrowRight', 'ArrowUp'].includes(event.key)) return;
      const delta = ['ArrowLeft', 'ArrowDown'].includes(event.key) ? -step : step;
      if (kind === 'resize') next.size = bound(next.size + delta, 1);
      else next.angle = ((((next.angle + delta + 180) % 360) + 360) % 360) - 180;
    }
    event.preventDefault();
    onKeyChange(next);
  };
  return (
    <svg
      className="nl-photo-focus-overlay"
      viewBox={`0 0 ${width} ${height}`}
      role="group"
      aria-label="Focus region controls"
      aria-disabled={disabled}
      onPointerMove={(event) => {
        const active = drag.current;
        if (!active || disabled) return;
        const bounds = event.currentTarget.getBoundingClientRect();
        if (!bounds.width || !bounds.height) return;
        const x = ((event.clientX - bounds.left) * width) / bounds.width;
        const y = ((event.clientY - bounds.top) * height) / bounds.height;
        const next = { ...active.region };
        if (active.kind === 'move') {
          next.x = bound(active.region.x + ((event.clientX - active.x) * 100) / bounds.width);
          next.y = bound(active.region.y + ((event.clientY - active.y) * 100) / bounds.height);
        } else if (active.kind === 'resize') {
          const centerX = (width * active.region.x) / 100,
            centerY = (height * active.region.y) / 100;
          const distance =
            edit.focus === 'Radial'
              ? Math.hypot(x - centerX, y - centerY)
              : Math.abs((x - centerX) * region.normalX + (y - centerY) * region.normalY);
          next.size = bound((distance * 200) / Math.min(width, height), 1);
        } else {
          next.angle =
            (Math.atan2(y - (height * active.region.y) / 100, x - (width * active.region.x) / 100) *
              180) /
            Math.PI;
        }
        onMove(next);
      }}
      onPointerUp={() => {
        if (drag.current) onFinish(false);
        drag.current = null;
      }}
      onPointerCancel={() => {
        if (drag.current) onFinish(true);
        drag.current = null;
      }}
    >
      <g transform={`translate(${region.x} ${region.y}) rotate(${angle})`}>
        {edit.focus === 'Radial' ? (
          <circle
            r={region.radius}
            className="nl-photo-focus-shape"
            role="button"
            tabIndex={disabled ? -1 : 0}
            aria-label="Move focus region"
            onPointerDown={(event) => begin(event, 'move')}
            onKeyDown={(event) => keyboard(event, 'move')}
          />
        ) : (
          <>
            <rect
              x={-line}
              y={-region.radius}
              width={line * 2}
              height={region.radius * 2}
              className="nl-photo-focus-band"
              role="button"
              tabIndex={disabled ? -1 : 0}
              aria-label="Move focus region"
              onPointerDown={(event) => begin(event, 'move')}
              onKeyDown={(event) => keyboard(event, 'move')}
            />
            {(edit.focus === 'Mirrored' ? [-1, 1] : [0]).map((edge) => (
              <line
                key={edge}
                x1={-line}
                x2={line}
                y1={region.radius * edge}
                y2={region.radius * edge}
                className="nl-photo-focus-line"
              />
            ))}
          </>
        )}
        <circle
          cx={edit.focus === 'Radial' ? region.radius : 0}
          cy={edit.focus === 'Radial' ? 0 : region.radius}
          r={handle}
          className="nl-photo-focus-handle"
          role="button"
          tabIndex={disabled ? -1 : 0}
          aria-label="Resize focus region"
          onPointerDown={(event) => begin(event, 'resize')}
          onKeyDown={(event) => keyboard(event, 'resize')}
        />
        {edit.focus !== 'Radial' && (
          <circle
            cx={region.radius + handle * 4}
            r={handle}
            className="nl-photo-focus-handle"
            role="button"
            tabIndex={disabled ? -1 : 0}
            aria-label="Rotate focus region"
            onPointerDown={(event) => begin(event, 'rotate')}
            onKeyDown={(event) => keyboard(event, 'rotate')}
          />
        )}
      </g>
    </svg>
  );
}

import { useEffect, useId, useRef, useState } from 'react';
import { ChevronDown, Image } from 'lucide-react';

export function NewsletterImageReplaceMenu({
  onUpload,
  onBrowse,
  onAdvanced,
  disabled = false,
  canEdit,
  canvas = false,
  label = 'Replace',
}: {
  onUpload: () => void;
  onBrowse: () => void;
  onAdvanced: () => void;
  disabled?: boolean;
  canEdit: boolean;
  canvas?: boolean;
  label?: 'Replace' | 'Add';
}) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const menuId = useId();
  const close = (restore = false) => {
    setOpen(false);
    if (restore) trigger.current?.focus();
  };
  useEffect(() => {
    if (!open) return;
    root.current?.querySelector<HTMLButtonElement>('[role="menuitem"]:not(:disabled)')?.focus();
    const outside = (event: PointerEvent) => {
      if (event.target instanceof Node && !root.current?.contains(event.target)) setOpen(false);
    };
    window.addEventListener('pointerdown', outside);
    return () => window.removeEventListener('pointerdown', outside);
  }, [open]);
  useEffect(() => {
    if (disabled) setOpen(false);
  }, [disabled]);
  const choose = (action: () => void) => {
    close(true);
    action();
  };
  return (
    <div
      ref={root}
      className="nl-image-replace"
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false);
      }}
    >
      <button
        ref={trigger}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        disabled={disabled}
        onClick={() => setOpen((value) => !value)}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
            event.preventDefault();
            setOpen(true);
          }
        }}
      >
        {canvas && <Image size={16} />} {label} <ChevronDown size={14} />
      </button>
      {open && (
        <div
          role="menu"
          aria-label="Replace image"
          id={menuId}
          className="nl-image-replace-menu"
          onKeyDown={(event) => {
            if (event.key === 'Escape') {
              event.preventDefault();
              event.stopPropagation();
              close(true);
              return;
            }
            if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
            event.preventDefault();
            const items = Array.from(
              event.currentTarget.querySelectorAll<HTMLButtonElement>(
                '[role="menuitem"]:not(:disabled)',
              ),
            );
            const index = items.indexOf(document.activeElement as HTMLButtonElement);
            const next =
              event.key === 'Home'
                ? 0
                : event.key === 'End'
                  ? items.length - 1
                  : (index + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
            items[next]?.focus();
          }}
        >
          <button type="button" role="menuitem" tabIndex={-1} onClick={() => choose(onUpload)}>
            Upload Image
          </button>
          <button type="button" role="menuitem" tabIndex={-1} onClick={() => choose(onBrowse)}>
            Browse Library
          </button>
          <button
            type="button"
            role="menuitem"
            tabIndex={-1}
            disabled={!canEdit}
            onClick={() => choose(onAdvanced)}
          >
            Edit with Photopea
          </button>
        </div>
      )}
    </div>
  );
}

import { useRef } from 'react';

const bound = (value: number) => Math.max(-45, Math.min(45, Math.round(value * 10) / 10));
export function NewsletterImageRotationRuler({
  angle,
  disabled,
  onBegin,
  onMove,
  onFinish,
  onKeyChange,
}: {
  angle: number;
  disabled: boolean;
  onBegin: () => void;
  onMove: (angle: number) => void;
  onFinish: (cancelled: boolean) => void;
  onKeyChange: (angle: number) => void;
}) {
  const drag = useRef<{ x: number; angle: number } | null>(null);
  return (
    <div
      className="nl-photo-rotation-ruler"
      role="slider"
      aria-label="Straighten image"
      aria-valuemin={-45}
      aria-valuemax={45}
      aria-valuenow={angle}
      aria-valuetext={`${angle} degrees`}
      aria-disabled={disabled}
      tabIndex={disabled ? -1 : 0}
      onPointerDown={(event) => {
        if (disabled || event.button > 0) return;
        event.preventDefault();
        event.currentTarget.setPointerCapture(event.pointerId);
        drag.current = { x: event.clientX, angle };
        onBegin();
      }}
      onPointerMove={(event) => {
        if (!drag.current || disabled) return;
        onMove(bound(drag.current.angle + (drag.current.x - event.clientX) / 4));
      }}
      onPointerUp={() => {
        if (drag.current) onFinish(false);
        drag.current = null;
      }}
      onPointerCancel={() => {
        if (drag.current) onFinish(true);
        drag.current = null;
      }}
      onKeyDown={(event) => {
        if (disabled) return;
        let value: number;
        if (event.key === 'Home') value = -45;
        else if (event.key === 'End') value = 45;
        else if (['ArrowLeft', 'ArrowDown', 'ArrowRight', 'ArrowUp'].includes(event.key))
          value =
            angle +
            (['ArrowLeft', 'ArrowDown'].includes(event.key) ? -1 : 1) * (event.shiftKey ? 10 : 1);
        else return;
        event.preventDefault();
        onKeyChange(bound(value));
      }}
    >
      <span className="nl-photo-ruler-ticks" style={{ backgroundPositionX: `${-angle * 4}px` }} />
      <strong>{angle}°</strong>
    </div>
  );
}

import { useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { BringToFront, Copy, Trash2 } from 'lucide-react';
import {
  newsletterImageTextCenter,
  newsletterImageTextFont,
  newsletterImageTextLayout,
  type NewsletterImageEdit,
  type NewsletterImageText,
  type NewsletterImageTextLayout,
} from './image-editor.js';

type Kind = 'move' | 'resize' | 'width' | 'rotate';
const bound = (value: number, min = 0, max = 100) => Math.min(max, Math.max(min, value));
const angle = (value: number) => ((((value + 180) % 360) + 360) % 360) - 180;

export function NewsletterImageTextOverlay({
  edit,
  layouts,
  selected,
  disabled,
  onSelect,
  onBegin,
  onMove,
  onFinish,
  onKeyChange,
  onDuplicate,
  onRemove,
  onBringToFront,
}: {
  edit: NewsletterImageEdit;
  layouts: NewsletterImageTextLayout[];
  selected: number;
  disabled: boolean;
  onSelect: (index: number) => void;
  onBegin: () => void;
  onMove: (index: number, text: NewsletterImageText) => void;
  onFinish: (cancelled: boolean) => void;
  onKeyChange: (index: number, text: NewsletterImageText) => void;
  onDuplicate: () => void;
  onRemove: () => void;
  onBringToFront: () => void;
}) {
  const svg = useRef<SVGSVGElement>(null);
  const [editing, setEditing] = useState<number | null>(null);
  const drag = useRef<{
    kind: Kind;
    index: number;
    text: NewsletterImageText;
    layout: NewsletterImageTextLayout;
    start: { x: number; y: number };
    center: { x: number; y: number };
    side: number;
  } | null>(null);
  const measure = (text: NewsletterImageText) => {
    const context = document.createElement('canvas').getContext('2d');
    if (!context) return null;
    return newsletterImageTextLayout(context, text, edit.width);
  };
  const keepCenter = (text: NewsletterImageText, center: { x: number; y: number }) => {
    const layout = measure(text);
    if (!layout) return text;
    const aligned = text.align === 'center' ? 0.5 : text.align === 'right' ? 1 : 0;
    return {
      ...text,
      x: bound(((center.x - layout.width * (0.5 - aligned)) * 100) / edit.width),
      y: bound(((center.y - layout.height / 2) * 100) / edit.height),
    };
  };
  const point = (event: { clientX: number; clientY: number }) => {
    const bounds = svg.current?.getBoundingClientRect();
    return bounds?.width && bounds.height
      ? {
          x: ((event.clientX - bounds.left) * edit.width) / bounds.width,
          y: ((event.clientY - bounds.top) * edit.height) / bounds.height,
        }
      : null;
  };
  const begin = (event: PointerEvent<SVGElement>, index: number, kind: Kind, side = 1) => {
    if (disabled || editing !== null) return;
    const start = point(event),
      text = edit.texts[index],
      layout = layouts[index];
    if (!start || !text || !layout || !svg.current) return;
    event.preventDefault();
    svg.current.setPointerCapture(event.pointerId);
    drag.current = {
      kind,
      index,
      text: { ...text },
      layout,
      start,
      center: newsletterImageTextCenter(text, layout, edit.width, edit.height),
      side,
    };
    onSelect(index);
    onBegin();
  };
  const keyboard = (event: KeyboardEvent<SVGElement>, index: number, kind: Kind) => {
    if (disabled) return;
    if (event.key === 'Escape' && drag.current) {
      event.preventDefault();
      event.stopPropagation();
      onFinish(true);
      drag.current = null;
      return;
    }
    const text = edit.texts[index],
      layout = layouts[index];
    if (!text || !layout) return;
    if (kind === 'move' && event.key === 'Enter') {
      event.preventDefault();
      onSelect(index);
      onBegin();
      setEditing(index);
      return;
    }
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) return;
    event.preventDefault();
    const step = event.shiftKey ? 10 : 1;
    let next = { ...text };
    const delta = ['ArrowLeft', 'ArrowDown'].includes(event.key) ? -step : step;
    if (kind === 'move') {
      if (event.key === 'ArrowLeft') next.x = bound(next.x - step);
      if (event.key === 'ArrowRight') next.x = bound(next.x + step);
      if (event.key === 'ArrowUp') next.y = bound(next.y - step);
      if (event.key === 'ArrowDown') next.y = bound(next.y + step);
    } else if (kind === 'rotate') next.rotation = angle((next.rotation ?? 0) + delta);
    else {
      const center = newsletterImageTextCenter(text, layout, edit.width, edit.height);
      if (kind === 'width')
        next.boxWidth = bound((text.boxWidth ?? (layout.width * 100) / edit.width) + delta, 1);
      else {
        next.size = bound(text.size + delta, 8, 300);
        next.boxWidth = bound(
          ((text.boxWidth ?? (layout.width * 100) / edit.width) * next.size) / text.size,
          1,
        );
      }
      next = keepCenter(next, center);
    }
    onSelect(index);
    onKeyChange(index, next);
  };
  const activeText = edit.texts[selected],
    activeLayout = layouts[selected];
  const center =
    activeText && activeLayout
      ? newsletterImageTextCenter(activeText, activeLayout, edit.width, edit.height)
      : null;
  const handle = Math.max(edit.width, edit.height) * 0.006;
  return (
    <>
      <svg
        ref={svg}
        className="nl-photo-text-overlay"
        viewBox={`0 0 ${edit.width} ${edit.height}`}
        role="group"
        aria-label="Image text layer controls"
        aria-disabled={disabled}
        onPointerMove={(event) => {
          const active = drag.current,
            current = point(event);
          if (!active || !current || disabled) return;
          let next = { ...active.text };
          if (active.kind === 'move') {
            next.x = bound(next.x + ((current.x - active.start.x) * 100) / edit.width);
            next.y = bound(next.y + ((current.y - active.start.y) * 100) / edit.height);
          } else if (active.kind === 'rotate') {
            const initial = Math.atan2(
              active.start.y - active.center.y,
              active.start.x - active.center.x,
            );
            const now = Math.atan2(current.y - active.center.y, current.x - active.center.x);
            next.rotation = angle((next.rotation ?? 0) + ((now - initial) * 180) / Math.PI);
          } else {
            if (active.kind === 'resize') {
              const initial = Math.hypot(
                active.start.x - active.center.x,
                active.start.y - active.center.y,
              );
              const now = Math.hypot(current.x - active.center.x, current.y - active.center.y);
              next.size = bound(
                active.text.size *
                  (1 +
                    (now - initial) /
                      Math.hypot(active.layout.width / 2, active.layout.height / 2)),
                8,
                300,
              );
              next.boxWidth = bound(
                ((active.text.boxWidth ?? (active.layout.width * 100) / edit.width) * next.size) /
                  active.text.size,
                1,
              );
            } else {
              const rotation = ((next.rotation ?? 0) * Math.PI) / 180;
              const dx =
                (current.x - active.start.x) * Math.cos(rotation) +
                (current.y - active.start.y) * Math.sin(rotation);
              next.boxWidth = bound(
                ((active.layout.width + 2 * dx * active.side) * 100) / edit.width,
                1,
              );
            }
            next = keepCenter(next, active.center);
          }
          onMove(active.index, next);
        }}
        onPointerUp={() => {
          if (drag.current) onFinish(false);
          drag.current = null;
        }}
        onPointerCancel={() => {
          if (drag.current) onFinish(true);
          drag.current = null;
        }}
      >
        {edit.texts.map((text, index) => {
          const layout = layouts[index];
          if (!layout) return null;
          const middle = newsletterImageTextCenter(text, layout, edit.width, edit.height);
          const chosen = index === selected;
          return (
            <g
              key={index}
              transform={`translate(${middle.x} ${middle.y}) rotate(${text.rotation ?? 0})`}
            >
              <rect
                x={-layout.width / 2}
                y={-layout.height / 2}
                width={layout.width}
                height={layout.height}
                className={`nl-photo-text-box${chosen ? ' is-selected' : ''}`}
                role="button"
                tabIndex={disabled ? -1 : 0}
                aria-label={chosen ? 'Move image text' : `Select image text ${index + 1}`}
                onPointerDown={(event) => begin(event, index, 'move')}
                onClick={() => onSelect(index)}
                onKeyDown={(event) => keyboard(event, index, 'move')}
                onDoubleClick={() => {
                  if (!disabled) {
                    onSelect(index);
                    onBegin();
                    setEditing(index);
                  }
                }}
              />
              {chosen && editing !== index && (
                <>
                  {[-1, 1].flatMap((x) =>
                    [-1, 1].map((y) => (
                      <circle
                        key={`${x}:${y}`}
                        cx={(x * layout.width) / 2}
                        cy={(y * layout.height) / 2}
                        r={handle}
                        className="nl-photo-text-handle"
                        role="button"
                        tabIndex={disabled ? -1 : 0}
                        aria-label={`Resize image text ${y < 0 ? 'top' : 'bottom'} ${x < 0 ? 'left' : 'right'}`}
                        onPointerDown={(event) => begin(event, index, 'resize')}
                        onKeyDown={(event) => keyboard(event, index, 'resize')}
                      />
                    )),
                  )}
                  {[-1, 1].map((side) => (
                    <rect
                      key={side}
                      x={(side * layout.width) / 2 - handle / 2}
                      y={-handle}
                      width={handle}
                      height={handle * 2}
                      className="nl-photo-text-handle"
                      role="button"
                      tabIndex={disabled ? -1 : 0}
                      aria-label={`Resize image text width ${side < 0 ? 'left' : 'right'}`}
                      onPointerDown={(event) => begin(event, index, 'width', side)}
                      onKeyDown={(event) => keyboard(event, index, 'width')}
                    />
                  ))}
                  <line
                    x1={0}
                    x2={0}
                    y1={layout.height / 2}
                    y2={layout.height / 2 + handle * 4}
                    className="nl-photo-text-line"
                  />
                  <circle
                    cy={layout.height / 2 + handle * 4}
                    r={handle}
                    className="nl-photo-text-handle"
                    role="button"
                    tabIndex={disabled ? -1 : 0}
                    aria-label="Rotate image text"
                    onPointerDown={(event) => begin(event, index, 'rotate')}
                    onKeyDown={(event) => keyboard(event, index, 'rotate')}
                  />
                </>
              )}
              {editing === index && (
                <foreignObject
                  x={-layout.width / 2}
                  y={-layout.height / 2}
                  width={layout.width}
                  height={Math.max(layout.height, text.size * 2)}
                >
                  <textarea
                    autoFocus
                    aria-label="Edit image text"
                    value={text.text}
                    className="nl-photo-inline-text"
                    style={{
                      font: newsletterImageTextFont(text),
                      lineHeight: text.lineHeight,
                      letterSpacing: text.letterSpacing ?? 0,
                      textAlign: text.align,
                      color: text.color,
                    }}
                    onChange={(event) =>
                      onMove(index, { ...text, text: event.currentTarget.value })
                    }
                    onBlur={() => {
                      onFinish(false);
                      setEditing(null);
                    }}
                    onKeyDown={(event) => {
                      if (event.key === 'Escape') {
                        event.preventDefault();
                        event.stopPropagation();
                        onFinish(true);
                        setEditing(null);
                      } else if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
                        event.preventDefault();
                        onFinish(false);
                        setEditing(null);
                      }
                    }}
                  />
                </foreignObject>
              )}
            </g>
          );
        })}
      </svg>
      {center && activeLayout && editing === null && (
        <div
          className="nl-photo-layer-tools"
          style={{
            left: `${bound((center.x * 100) / edit.width, 5, 95)}%`,
            top: `${bound(((center.y - activeLayout.height / 2) * 100) / edit.height, 8, 95)}%`,
          }}
        >
          <button
            disabled={disabled}
            aria-label="Bring image text to front"
            title="Bring to front"
            onClick={onBringToFront}
          >
            <BringToFront size={18} />
          </button>
          <button
            disabled={disabled}
            aria-label="Duplicate image text"
            title="Duplicate text"
            onClick={onDuplicate}
          >
            <Copy size={18} />
          </button>
          <button
            disabled={disabled}
            aria-label="Remove image text"
            title="Remove text"
            onClick={onRemove}
          >
            <Trash2 size={18} />
          </button>
        </div>
      )}
    </>
  );
}

import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { newsletterSafeUrl } from '@capiro/shared/newsletter-render';
import { newsletterError } from './api.js';
import {
  newsletterBlockLinks,
  newsletterLinkBlock,
  type NewsletterReviewLink,
} from './newsletter-links.js';

export function NewsletterPreviewFrame({
  html,
  style,
  selected,
  links,
  onSelect,
}: {
  html: string;
  style?: CSSProperties;
  selected?: NewsletterReviewLink | null;
  links: NewsletterReviewLink[];
  onSelect?: (key: string) => void;
}) {
  const frame = useRef<HTMLIFrameElement>(null);
  const latest = useRef({ selected, links, onSelect });
  latest.current = { selected, links, onSelect };
  const previousHighlight = useRef<{
    element: HTMLElement;
    outline: string;
    offset: string;
  } | null>(null);
  const clearHighlight = () => {
    const previous = previousHighlight.current;
    if (previous) {
      previous.element.style.outline = previous.outline;
      previous.element.style.outlineOffset = previous.offset;
      previousHighlight.current = null;
    }
  };
  const highlight = () => {
    clearHighlight();
    const doc = frame.current?.contentDocument;
    const link = latest.current.selected;
    if (!doc || !link) return;
    const wrapper = doc.getElementById(link.blockId);
    const anchor =
      wrapper && (newsletterBlockLinks(wrapper)[link.index] as HTMLElement | undefined);
    if (!anchor) return;
    previousHighlight.current = {
      element: anchor,
      outline: anchor.style.outline,
      offset: anchor.style.outlineOffset,
    };
    anchor.style.outline = '3px solid #007c89';
    anchor.style.outlineOffset = '4px';
    anchor.scrollIntoView?.({ block: 'center' });
  };
  useEffect(() => {
    highlight();
  }, [selected?.key]);
  return (
    <iframe
      ref={frame}
      title="Newsletter preview"
      sandbox="allow-same-origin"
      srcDoc={html}
      style={style}
      onLoad={() => {
        clearHighlight();
        const doc = frame.current?.contentDocument;
        if (!doc) return;
        // Scripts remain disabled. Preview clicks review destinations rather than navigate.
        doc.addEventListener('click', (event) => {
          const anchor = (event.target as Element).closest?.('a');
          if (!anchor) return;
          event.preventDefault();
          const wrapper = newsletterLinkBlock(anchor);
          const index = wrapper ? newsletterBlockLinks(wrapper).indexOf(anchor) : -1;
          const link = latest.current.links.find(
            (item) => item.blockId === wrapper?.id && item.index === index,
          );
          if (link) latest.current.onSelect?.(link.key);
        });
        highlight();
      }}
    />
  );
}

export function NewsletterLinkChecker({
  links,
  selectedKey,
  checked,
  onReview,
  onSelect,
  onSave,
  onBack,
}: {
  links: NewsletterReviewLink[];
  selectedKey: string | null;
  checked: Set<string>;
  onReview: (key: string) => void;
  onSelect: (key: string | null) => void;
  onSave: (link: NewsletterReviewLink, url: string) => Promise<NewsletterReviewLink>;
  onBack: () => void;
}) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const input = useRef<HTMLInputElement>(null);
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  const index = links.findIndex((link) => link.key === selectedKey);
  const selected = links[index];
  useEffect(() => {
    setEditing(false);
    setError('');
    if (selectedKey && links.some((link) => link.key === selectedKey)) onReview(selectedKey);
  }, [selectedKey]);
  useEffect(() => {
    if (editing) input.current?.focus();
  }, [editing]);
  const select = (key: string | null) => {
    if (!busy) onSelect(key);
  };
  const count = links.filter((link) => checked.has(link.key)).length;
  return (
    <section className="nl-link-checker" aria-label="Email link checker">
      <div className="nl-link-checker-head">
        <button
          aria-label={selected ? 'Back to link list' : 'Back to email information'}
          disabled={busy}
          onClick={() => (selected ? select(null) : onBack())}
        >
          ←
        </button>
        <h3>{selected ? 'Link details' : `${count} of ${links.length} links checked`}</h3>
      </div>
      {selected ? (
        <>
          <strong className="nl-link-label">{selected.label}</strong>
          {editing ? (
            <form
              onSubmit={(event) => {
                event.preventDefault();
                if (busy || !newsletterSafeUrl(value)) return;
                setBusy(true);
                setError('');
                void onSave(selected, value)
                  .then((next) => {
                    if (!mounted.current) return;
                    onReview(next.key);
                    setEditing(false);
                    onSelect(next.key);
                  })
                  .catch((error) => {
                    if (mounted.current) setError(newsletterError(error));
                  })
                  .finally(() => {
                    if (mounted.current) setBusy(false);
                  });
              }}
            >
              <label className="nl-field">
                <span>href</span>
                <input
                  ref={input}
                  aria-label="href"
                  value={value}
                  disabled={busy}
                  onChange={(event) => setValue(event.target.value)}
                />
              </label>
              {!newsletterSafeUrl(value) && (
                <p role="alert">
                  {value.trim() ? 'Enter a valid destination.' : 'This cannot be empty.'}
                </p>
              )}
              <div className="nl-link-edit-actions">
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => {
                    setEditing(false);
                    setError('');
                  }}
                >
                  Cancel
                </button>
                <button
                  className="nl-primary"
                  type="submit"
                  disabled={busy || !newsletterSafeUrl(value)}
                >
                  {busy ? 'Saving…' : 'Save'}
                </button>
              </div>
            </form>
          ) : (
            <>
              <p className="nl-link-url">{selected.url || 'Missing destination'}</p>
              {selected.source !== 'managed' && (
                <button
                  onClick={() => {
                    setValue(selected.url);
                    setEditing(true);
                  }}
                >
                  Edit link
                </button>
              )}
            </>
          )}
          {error && <p role="alert">{error}</p>}
          {!selected.valid && (
            <p className="nl-link-warning" role="alert">
              This link needs a valid destination.
            </p>
          )}
          {selected.web ? (
            <div className="nl-link-site-preview">
              <h4>Website preview</h4>
              <iframe
                title={`Website preview: ${selected.label}`}
                src={newsletterSafeUrl(selected.url)}
                sandbox=""
                referrerPolicy="no-referrer"
              />
              <p className="nl-muted">
                Some websites prevent embedded previews. Open the link to verify its page.
              </p>
              <a
                href={newsletterSafeUrl(selected.url)}
                target="_blank"
                rel="noopener noreferrer"
                referrerPolicy="no-referrer"
              >
                Open link
              </a>
            </div>
          ) : (
            <div className="nl-link-no-preview">
              <h4>No preview available</h4>
              <p>
                This link contains a merge tag, anchor, email address, telephone number, or another
                destination that cannot display a website preview.
              </p>
              {selected.managed && <p>Recipient-specific destinations are created in Outreach.</p>}
            </div>
          )}
          <p className="nl-link-position">
            Link {index + 1} of {links.length}
          </p>
          <div className="nl-link-navigation">
            <button
              disabled={busy || editing || index === 0}
              onClick={() => select(links[index - 1]!.key)}
            >
              Back
            </button>
            <button
              className="nl-primary"
              disabled={busy || editing}
              onClick={() => select(index === links.length - 1 ? null : links[index + 1]!.key)}
            >
              {index === links.length - 1 ? 'Finish' : 'Next'}
            </button>
          </div>
        </>
      ) : (
        <>
          {!links.length && <p>No links in this newsletter.</p>}
          <ul className="nl-link-list">
            {links.map((link) => (
              <li key={link.key}>
                <button onClick={() => select(link.key)}>
                  <span aria-hidden="true" className="nl-link-reviewed">
                    {checked.has(link.key) ? '✓' : '↗'}
                  </span>
                  <span>
                    <strong>{link.label}</strong>
                    <small>{link.url || 'Missing destination'}</small>
                  </span>
                  <span aria-hidden="true">›</span>
                </button>
              </li>
            ))}
          </ul>
          <p className="nl-muted">
            Select each link to inspect its destination and edit it. Checked counts reflect your
            review.
          </p>
        </>
      )}
    </section>
  );
}

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
} from 'react';
import { Crop, Square, RectangleHorizontal, RectangleVertical, RotateCcw } from 'lucide-react';
import type { NewsletterBlock } from '@capiro/shared/newsletter';
import { newsletterBundledImageUrl } from '@capiro/shared/newsletter-render';
import { newsletterError } from './api.js';
import { NewsletterImageCropOverlay } from './NewsletterImageCropOverlay.js';
import type { NewsletterCropRect } from './image-editor-crop.js';
import {
  defaultNewsletterImageEdit,
  loadNewsletterImage,
  newsletterEditedImageFile,
} from './image-editor.js';

export interface NewsletterCropSource {
  key: number;
  documentId: string;
  blockId: string;
  url: string;
  alt: string;
  legacyCrop: NewsletterBlock['crop'];
}
type Preset = 'Freeform' | 'Square' | 'Horizontal' | 'Vertical' | 'Original';
type Draft = { crop: NewsletterCropRect; preset: Preset };
const full: NewsletterCropRect = { x: 0, y: 0, width: 100, height: 100 };
const presets = [
  ['Freeform', Crop],
  ['Square', Square],
  ['Horizontal', RectangleHorizontal],
  ['Vertical', RectangleVertical],
  ['Original', RotateCcw],
] as const;

export function newsletterQuickCropFit(width: number, height: number, ratio: number, inset = 0) {
  const offset = Math.max(0, Math.min(inset, (Math.min(width, height) - 1) / 2)) * 2;
  const w = Math.min(width - offset, (height - offset) * ratio) + offset,
    h = (w - offset) / ratio + offset;
  const cropWidth = (w / width) * 100,
    cropHeight = (h / height) * 100;
  return {
    x: (100 - cropWidth) / 2,
    y: (100 - cropHeight) / 2,
    width: cropWidth,
    height: cropHeight,
  };
}

export function useNewsletterQuickCrop({
  source,
  onCancel,
  onSave,
}: {
  source: NewsletterCropSource | null;
  onCancel: () => void;
  onSave: (file: File, source: NewsletterCropSource) => Promise<void>;
}) {
  const [loaded, setLoaded] = useState<{ key: number; image: HTMLImageElement } | null>(null);
  const [draft, setDraftState] = useState<Draft>({ crop: full, preset: 'Freeform' });
  const draftRef = useRef(draft);
  const initial = useRef(draft);
  const history = useRef<Draft[]>([]),
    future = useRef<Draft[]>([]);
  const [, refresh] = useState(0);
  const [pending, setPending] = useState(false);
  const [gesture, setGesture] = useState(false);
  const gestureStart = useRef<Draft | null>(null);
  const inFlight = useRef(false);
  const [error, setError] = useState('');
  const [retry, setRetry] = useState(0);
  const [viewport, setViewport] = useState<{ key: number; width: number; height: number } | null>(
    null,
  );
  const latest = useRef({ source, onCancel, onSave });
  latest.current = { source, onCancel, onSave };
  const reportViewport = useCallback((width: number, height: number) => {
    const key = latest.current.source?.key;
    if (
      key === undefined ||
      !Number.isFinite(width) ||
      !Number.isFinite(height) ||
      width <= 0 ||
      height <= 0
    )
      return;
    setViewport((previous) =>
      previous?.key === key && previous.width === width && previous.height === height
        ? previous
        : { key, width, height },
    );
  }, []);
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  const update = (value: Draft) => {
    draftRef.current = value;
    setDraftState(value);
  };
  useEffect(() => {
    let canceled = false;
    setLoaded(null);
    setViewport(null);
    setError('');
    setGesture(false);
    gestureStart.current = null;
    history.current = [];
    future.current = [];
    update({ crop: full, preset: 'Freeform' });
    if (source) {
      loadNewsletterImage(source.url)
        .then((image) => {
          if (canceled) return;
          let crop = { ...full };
          if (source.legacyCrop) {
            crop = newsletterQuickCropFit(
              image.naturalWidth,
              image.naturalHeight,
              source.legacyCrop.width / source.legacyCrop.height,
            );
            crop.x = ((100 - crop.width) * source.legacyCrop.x) / 100;
            crop.y = ((100 - crop.height) * source.legacyCrop.y) / 100;
          }
          initial.current = { crop, preset: 'Freeform' };
          update(initial.current);
          setLoaded({ key: source.key, image });
        })
        .catch((e) => {
          if (!canceled) setError(newsletterError(e));
        });
    }
    return () => {
      canceled = true;
    };
  }, [source?.key, retry]);
  useEffect(() => {
    if (!source) return;
    const escape = (event: KeyboardEvent) => {
      if (
        event.key === 'Escape' &&
        !event.defaultPrevented &&
        !(event.target instanceof Element && event.target.closest('[role="dialog"]')) &&
        !inFlight.current
      ) {
        event.preventDefault();
        latest.current.onCancel();
      }
    };
    window.addEventListener('keydown', escape);
    return () => window.removeEventListener('keydown', escape);
  }, [source?.key]);
  const ready = source && loaded?.key === source.key ? loaded.image : null;
  const plane =
    viewport?.key === source?.key
      ? viewport
      : ready
        ? { width: ready.naturalWidth, height: ready.naturalHeight }
        : null;
  const insetPixels = plane
    ? Math.max(0, Math.min(7, (Math.min(plane.width, plane.height) - 1) / 2))
    : 0;
  const inset = plane
    ? { x: (insetPixels / plane.width) * 100, y: (insetPixels / plane.height) * 100 }
    : { x: 0, y: 0 };
  const change = (value: Draft) => {
    if (JSON.stringify(value) === JSON.stringify(draftRef.current)) return;
    history.current.push(draftRef.current);
    if (history.current.length > 80) history.current.shift();
    future.current = [];
    update(value);
  };
  const cancel = () => {
    if (!inFlight.current) latest.current.onCancel();
  };
  return {
    source,
    reportViewport,
    inset,
    draft,
    ready,
    pending,
    gesture,
    error,
    dirty: !!ready && JSON.stringify(draft.crop) !== JSON.stringify(initial.current.crop),
    canUndo: !!history.current.length && !pending && !gesture,
    canRedo: !!future.current.length && !pending && !gesture,
    cancel,
    retry: () => setRetry((value) => value + 1),
    preset: (preset: Preset) => {
      if (!ready || inFlight.current || gestureStart.current) return;
      if (!plane) return;
      const crop =
        preset === 'Freeform'
          ? { ...full }
          : newsletterQuickCropFit(
              plane.width,
              plane.height,
              preset === 'Original'
                ? ready.naturalWidth / ready.naturalHeight
                : preset === 'Square'
                  ? 1
                  : preset === 'Horizontal'
                    ? 3 / 2
                    : 2 / 3,
              insetPixels,
            );
      change({ crop, preset });
    },
    undo: () => {
      if (inFlight.current || gestureStart.current) return;
      const value = history.current.pop();
      if (value) {
        future.current.push(draftRef.current);
        update(value);
      }
    },
    redo: () => {
      if (inFlight.current || gestureStart.current) return;
      const value = future.current.pop();
      if (value) {
        history.current.push(draftRef.current);
        update(value);
      }
    },
    begin: () => {
      if (inFlight.current) return;
      gestureStart.current = draftRef.current;
      setGesture(true);
    },
    move: (crop: NewsletterCropRect) => {
      if (gestureStart.current && !inFlight.current) update({ ...draftRef.current, crop });
    },
    finish: (cancelled: boolean) => {
      const start = gestureStart.current;
      gestureStart.current = null;
      setGesture(false);
      if (!start) return;
      if (cancelled) update(start);
      else if (JSON.stringify(start) !== JSON.stringify(draftRef.current)) {
        history.current.push(start);
        if (history.current.length > 80) history.current.shift();
        future.current = [];
        refresh((value) => value + 1);
      }
    },
    keyChange: (crop: NewsletterCropRect) => {
      if (!inFlight.current && !gestureStart.current) change({ ...draftRef.current, crop });
    },
    done: async () => {
      if (!ready || !source || inFlight.current || gestureStart.current) return;
      if (JSON.stringify(draftRef.current.crop) === JSON.stringify(initial.current.crop)) {
        cancel();
        return;
      }
      const capture = source;
      const edit = defaultNewsletterImageEdit(ready.naturalWidth, ready.naturalHeight);
      edit.crop = { ...draftRef.current.crop };
      const width = (ready.naturalWidth * edit.crop.width) / 100,
        height = (ready.naturalHeight * edit.crop.height) / 100;
      const scale = Math.min(1, 4096 / Math.max(width, height));
      edit.width = Math.max(1, Math.round(width * scale));
      edit.height = Math.max(1, Math.round(height * scale));
      inFlight.current = true;
      setPending(true);
      setError('');
      try {
        const file = await newsletterEditedImageFile(ready, edit);
        if (mounted.current && latest.current.source?.key === capture.key)
          await latest.current.onSave(file, capture);
      } catch (e) {
        if (mounted.current && latest.current.source?.key === capture.key)
          setError(newsletterError(e));
      } finally {
        inFlight.current = false;
        if (mounted.current) setPending(false);
      }
    },
  };
}
type Controller = ReturnType<typeof useNewsletterQuickCrop>;

export function NewsletterQuickCropSidebar({ crop }: { crop: Controller }) {
  return (
    <section aria-label="Crop image" className="nl-quick-crop-sidebar">
      <h2>Crop</h2>
      <div role="group" aria-label="Crop presets" className="nl-quick-crop-presets">
        {presets.map(([name, Icon]) => (
          <button
            key={name}
            type="button"
            aria-pressed={crop.draft.preset === name}
            disabled={!crop.ready || crop.pending || crop.gesture}
            onClick={() => crop.preset(name)}
          >
            <Icon size={27} />
            <span>{name}</span>
          </button>
        ))}
      </div>
      {!crop.ready && !crop.error && <p role="status">Loading image…</p>}
      {crop.error && <p role="alert">{crop.error}</p>}
      {!crop.ready && crop.error && (
        <button type="button" onClick={crop.retry}>
          Try again
        </button>
      )}
      <footer>
        <button type="button" disabled={crop.pending} onClick={crop.cancel}>
          Cancel
        </button>
        <button
          type="button"
          className="nl-primary"
          disabled={!crop.ready || crop.pending || crop.gesture}
          onClick={() => void crop.done()}
        >
          {crop.pending ? 'Saving image…' : 'Done'}
        </button>
      </footer>
    </section>
  );
}

export function NewsletterQuickCropCanvas({
  crop,
  block,
  style,
}: {
  crop: Controller;
  block: NewsletterBlock;
  style: CSSProperties;
}) {
  const image = useRef<HTMLImageElement>(null);
  const measure = useCallback(() => {
    const bounds = image.current?.getBoundingClientRect();
    if (bounds) crop.reportViewport(bounds.width, bounds.height);
  }, [crop.reportViewport]);
  useLayoutEffect(() => {
    measure();
    const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(measure);
    if (image.current) observer?.observe(image.current);
    window.addEventListener('resize', measure);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, [measure, crop.source?.key, crop.ready]);
  const {
    paddingTop = 12,
    paddingBottom = 12,
    paddingLeft = 0,
    paddingRight = 0,
    margin,
    width,
    height,
    ...imageStyle
  } = style;
  return (
    <div style={{ paddingTop, paddingBottom, paddingLeft, paddingRight, margin }}>
      <div
        className="nl-quick-crop-canvas"
        style={{
          ...imageStyle,
          width: '100%',
          marginLeft: style.textAlign === 'center' || style.textAlign === 'right' ? 'auto' : 0,
          marginRight: style.textAlign === 'right' ? 0 : 'auto',
        }}
      >
        <img
          ref={image}
          onLoad={measure}
          src={newsletterBundledImageUrl(block.imageUrl)}
          alt={block.alt}
        />
        {crop.ready && (
          <NewsletterImageCropOverlay
            crop={crop.draft.crop}
            width={crop.ready.naturalWidth}
            height={crop.ready.naturalHeight}
            locked={crop.draft.preset !== 'Freeform'}
            cornersOnly={crop.draft.preset !== 'Freeform'}
            inset={crop.inset}
            inline
            disabled={crop.pending}
            onBegin={crop.begin}
            onMove={crop.move}
            onFinish={crop.finish}
            onKeyChange={crop.keyChange}
          />
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useApiScope } from '../../../../lib/use-api-scope.js';
import { newsletterError, useNewsletterApi } from './api.js';
import { NewsletterComments } from './NewsletterComments.js';
import './newsletter.css';

export default function NewsletterReview({ documentId }: { documentId: string }) {
  const scope = useApiScope();
  return <ReviewSession key={`${JSON.stringify(scope)}:${documentId}`} id={documentId} />;
}
function ReviewSession({ id }: { id: string }) {
  const api = useNewsletterApi();
  const [review, setReview] = useState<Awaited<ReturnType<typeof api.review>> | null>(null);
  const [error, setError] = useState('');
  const [mobile, setMobile] = useState(false);
  useEffect(() => {
    let active = true;
    const load = async () => {
      try {
        const result = await api.review(id);
        if (active) {
          setReview(result);
          setError('');
        }
      } catch (error) {
        if (active) {
          setReview(null);
          setError(newsletterError(error));
        }
      }
    };
    void load();
    const timer = setInterval(() => void load(), 15000);
    return () => {
      active = false;
      clearInterval(timer);
    };
  }, [api, id]);
  return (
    <div className="nl-root nl-review">
      <header className="nl-header">
        <Link to="/workspace">← Workspace</Link>
        <h1>{review?.name || 'Newsletter review'}</h1>
        {review && ['owner', 'editor'].includes(review.role) && (
          <Link to={`/workspace/newsletters/${id}`}>Edit newsletter</Link>
        )}
        <button onClick={() => setMobile(!mobile)}>{mobile ? 'Desktop' : 'Mobile'}</button>
      </header>
      {error ? (
        <p role="alert">{error}</p>
      ) : review ? (
        <div className="nl-review-body">
          <div className="nl-preview-frame">
            <iframe
              sandbox=""
              title="Newsletter review"
              srcDoc={review.html}
              style={{ width: mobile ? 375 : 660 }}
            />
          </div>
          <NewsletterComments api={api} documentId={id} />
        </div>
      ) : (
        <p>Loading newsletter…</p>
      )}
    </div>
  );
}

import { GripVertical } from 'lucide-react';
import {
  NEWSLETTER_SOCIAL_PLATFORMS,
  NEWSLETTER_SOCIAL_ICON_STYLES,
  newsletterSocialPlatform,
  newsletterSocialSettings,
  defaultNewsletterSocialShare,
  type NewsletterBlock,
  type NewsletterSocialDevice,
} from '@capiro/shared/newsletter';
import { Field, SelectField, TextField } from './controls.js';
import { NewsletterSocialShareContent } from './NewsletterSocialShareContent.js';

export function NewsletterSocialContent({
  block,
  onChange,
}: {
  block: NewsletterBlock;
  onChange: (edit: (block: NewsletterBlock) => void) => void;
}) {
  const mode = block.social?.mode || 'follow';
  const changeMode = (mode: 'follow' | 'share') =>
    onChange((draft) => {
      const settings = structuredClone(newsletterSocialSettings(draft));
      if ((settings.mode || 'follow') === mode) return;
      if (settings.mode === 'share') settings.shareDisplay = settings.display;
      else settings.followDisplay = settings.display;
      settings.mode = mode;
      settings.display =
        mode === 'share' ? settings.shareDisplay || 'icon-text' : settings.followDisplay || 'icon';
      if (mode === 'share') settings.share ||= defaultNewsletterSocialShare();
      draft.social = settings;
    });
  return (
    <>
      <fieldset className="nl-social-type">
        <legend>Social type</legend>
        <label className="nl-check">
          <input type="radio" checked={mode === 'follow'} onChange={() => changeMode('follow')} />
          Follow
        </label>
        <p>Links to your social channels</p>
        <label className="nl-check">
          <input type="radio" checked={mode === 'share'} onChange={() => changeMode('share')} />
          Share
        </label>
        <p>Recipients post to their social channels</p>
      </fieldset>
      {mode === 'share' ? (
        <NewsletterSocialShareContent block={block} onChange={onChange} />
      ) : (
        <NewsletterSocialFollowContent block={block} onChange={onChange} />
      )}
    </>
  );
}

function NewsletterSocialFollowContent({
  block,
  onChange,
}: {
  block: NewsletterBlock;
  onChange: (edit: (block: NewsletterBlock) => void) => void;
}) {
  const move = (from: number, to: number) => {
    if (
      from === to ||
      !Number.isInteger(from) ||
      from < 0 ||
      from >= block.items.length ||
      to < 0 ||
      to >= block.items.length
    )
      return;
    onChange((draft) => {
      const [item] = draft.items.splice(from, 1);
      draft.items.splice(to, 0, item!);
    });
  };
  return (
    <section aria-label="Social profiles">
      <p>Links to your social channels</p>
      {block.items.map((item, index) => {
        const platform = newsletterSocialPlatform(item);
        return (
          <div
            className="nl-item-card"
            key={index}
            onDragOver={(event) => {
              if (event.dataTransfer.types.includes('application/x-capiro-social-index'))
                event.preventDefault();
            }}
            onDrop={(event) => {
              const value = event.dataTransfer.getData('application/x-capiro-social-index');
              if (!/^\d+$/.test(value)) return;
              event.preventDefault();
              event.stopPropagation();
              move(Number(value), index);
            }}
          >
            <div className="nl-flex">
              <button
                draggable
                aria-label={`Drag social link ${index + 1}`}
                onDragStart={(event) => {
                  event.stopPropagation();
                  event.dataTransfer.setData('application/x-capiro-social-index', String(index));
                  event.dataTransfer.effectAllowed = 'move';
                }}
              >
                <GripVertical size={16} />
              </button>
              <button
                aria-label={`Delete social link ${index + 1}`}
                onClick={() =>
                  onChange((draft) => {
                    draft.items.splice(index, 1);
                  })
                }
              >
                Delete
              </button>
            </div>
            <Field label={`Social channel ${index + 1}`}>
              <select
                value={platform}
                onChange={(event) => {
                  const selected = NEWSLETTER_SOCIAL_PLATFORMS.find(
                    ([key]) => key === event.target.value,
                  )!;
                  onChange((draft) => {
                    draft.items[index] = {
                      platform: selected[0],
                      label: selected[0] === 'twitter' ? 'X' : selected[1],
                      url: selected[2],
                    };
                  });
                }}
              >
                {NEWSLETTER_SOCIAL_PLATFORMS.map(([key, label]) => (
                  <option
                    key={key}
                    value={key}
                    disabled={
                      key !== platform &&
                      block.items.some((other) => newsletterSocialPlatform(other) === key)
                    }
                  >
                    {label}
                  </option>
                ))}
              </select>
            </Field>
            <TextField
              label={`Social URL ${index + 1}`}
              value={item.url}
              onChange={(value) =>
                onChange((draft) => {
                  draft.items[index]!.url = value;
                })
              }
            />
            <TextField
              label={`Social label ${index + 1}`}
              value={item.label}
              onChange={(value) =>
                onChange((draft) => {
                  draft.items[index]!.label = value;
                })
              }
            />
            <div className="nl-flex">
              <button
                aria-label={`Move social link ${index + 1} up`}
                disabled={index === 0}
                onClick={() => move(index, index - 1)}
              >
                Move up
              </button>
              <button
                aria-label={`Move social link ${index + 1} down`}
                disabled={index === block.items.length - 1}
                onClick={() => move(index, index + 1)}
              >
                Move down
              </button>
            </div>
          </div>
        );
      })}
      <button
        disabled={block.items.length >= NEWSLETTER_SOCIAL_PLATFORMS.length}
        onClick={() => {
          const next = NEWSLETTER_SOCIAL_PLATFORMS.find(
            ([key]) => !block.items.some((item) => newsletterSocialPlatform(item) === key),
          );
          if (next)
            onChange((draft) => {
              draft.items.push({
                platform: next[0],
                label: next[0] === 'twitter' ? 'X' : next[1],
                url: next[2],
              });
            });
        }}
      >
        Add another social link
      </button>
    </section>
  );
}

export function NewsletterSocialStyles({
  block,
  mobile,
  onChange,
}: {
  block: NewsletterBlock;
  mobile: boolean;
  onChange: (edit: (block: NewsletterBlock) => void) => void;
}) {
  const settings = newsletterSocialSettings(block),
    device = mobile ? settings.mobile : settings.desktop;
  const update = (edit: (settings: NonNullable<NewsletterBlock['social']>) => void) =>
    onChange((draft) => {
      draft.social = structuredClone(newsletterSocialSettings(draft));
      edit(draft.social);
    });
  const updateDevice = (edit: (device: NewsletterSocialDevice) => void) =>
    update((settings) => edit(mobile ? settings.mobile : settings.desktop));
  return (
    <section aria-label="Social icon styles">
      <h3>Icon Styles</h3>
      <SelectField
        label="Display"
        value={settings.display}
        values={[
          ['icon', 'Icon only'],
          ['icon-text', 'Icon & Text'],
          ['text', 'Text only'],
        ]}
        onChange={(value) =>
          update((settings) => {
            settings.display = value;
          })
        }
      />
      {settings.display !== 'text' && (
        <>
          <SelectField
            label="Icon Style"
            value={settings.iconStyle}
            values={NEWSLETTER_SOCIAL_ICON_STYLES.map(([key, label]) => [key, label])}
            onChange={(value) =>
              update((settings) => {
                settings.iconStyle = value;
              })
            }
          />
          <SelectField
            label="Icon size"
            value={device.size}
            values={[
              ['small', 'Small'],
              ['medium', 'Medium'],
              ['large', 'Large'],
            ]}
            onChange={(value) =>
              updateDevice((device) => {
                device.size = value;
              })
            }
          />
        </>
      )}
      <SelectField
        label="Layout"
        value={device.layout}
        values={[
          ['horizontal', 'Horizontal'],
          ['vertical', 'Vertical'],
        ]}
        onChange={(value) =>
          updateDevice((device) => {
            device.layout = value;
          })
        }
      />
      <Field label="Spacing">
        <input
          aria-label="Spacing"
          type="range"
          min="2"
          max="60"
          step="2"
          value={device.spacing}
          onChange={(event) =>
            updateDevice((device) => {
              device.spacing = Number(event.target.value);
            })
          }
        />
        <output>{device.spacing}px</output>
      </Field>
    </section>
  );
}

import { GripVertical } from 'lucide-react';
import {
  defaultNewsletterSocialShare,
  newsletterSocialSettings,
  NEWSLETTER_SOCIAL_SHARE_PLATFORMS,
  type NewsletterBlock,
  type NewsletterSocialShare,
} from '@capiro/shared/newsletter';
import { Field, TextField } from './controls.js';

const sharePlatforms = NEWSLETTER_SOCIAL_SHARE_PLATFORMS.filter(([key]) => key !== 'forward');

export function NewsletterSocialShareContent({
  block,
  onChange,
}: {
  block: NewsletterBlock;
  onChange: (edit: (block: NewsletterBlock) => void) => void;
}) {
  const share = block.social?.share || defaultNewsletterSocialShare();
  const update = (edit: (share: NewsletterSocialShare) => void) =>
    onChange((draft) => {
      draft.social = structuredClone(newsletterSocialSettings(draft));
      draft.social.share ||= defaultNewsletterSocialShare();
      edit(draft.social.share);
    });
  const move = (from: number, to: number) => {
    if (
      !Number.isInteger(from) ||
      from < 0 ||
      from >= share.items.length ||
      to < 0 ||
      to >= share.items.length ||
      from === to
    )
      return;
    update((value) => {
      const [item] = value.items.splice(from, 1);
      value.items.splice(to, 0, item!);
    });
  };
  return (
    <section aria-label="Social sharing">
      {share.source === 'custom' ? (
        <TextField
          label="Custom URL"
          value={share.customUrl}
          placeholder="Please enter a URL"
          onChange={(customUrl) =>
            update((value) => {
              value.customUrl = customUrl;
            })
          }
        />
      ) : (
        <>
          <p role="status">
            Campaign sharing is not enabled. Use a public article or bill page instead.
          </p>
          <button
            type="button"
            onClick={() =>
              update((value) => {
                value.source = 'custom';
              })
            }
          >
            Use a public URL
          </button>
        </>
      )}
      {share.items.some((item) => item.platform === 'forward') && (
        <p role="status">
          Forwarding is not enabled. Remove this channel or choose another channel before staging.
        </p>
      )}
      {share.items.map((item, index) => (
        <div
          className="nl-item-card"
          key={index}
          onDragOver={(event) => {
            if (event.dataTransfer.types.includes('application/x-capiro-share-index'))
              event.preventDefault();
          }}
          onDrop={(event) => {
            const value = event.dataTransfer.getData('application/x-capiro-share-index');
            if (!/^\d+$/.test(value)) return;
            event.preventDefault();
            event.stopPropagation();
            move(Number(value), index);
          }}
        >
          <div className="nl-flex">
            <button
              draggable
              aria-label={`Drag social share ${index + 1}`}
              onDragStart={(event) => {
                event.stopPropagation();
                event.dataTransfer.setData('application/x-capiro-share-index', String(index));
                event.dataTransfer.effectAllowed = 'move';
              }}
            >
              <GripVertical size={16} />
            </button>
            <button
              aria-label={`Delete social share ${index + 1}`}
              onClick={() =>
                update((value) => {
                  value.items.splice(index, 1);
                })
              }
            >
              Delete
            </button>
          </div>
          <Field label={`Share channel ${index + 1}`}>
            <select
              value={item.platform}
              onChange={(event) =>
                update((value) => {
                  value.items[index] = {
                    platform: event.target.value as typeof item.platform,
                    label: '',
                  };
                })
              }
            >
              {item.platform === 'forward' && (
                <option value="forward" disabled>
                  Forwarding not enabled
                </option>
              )}
              {sharePlatforms.map(([key, label]) => (
                <option
                  key={key}
                  value={key}
                  disabled={
                    key !== item.platform && share.items.some((other) => other.platform === key)
                  }
                >
                  {label}
                </option>
              ))}
            </select>
          </Field>
          <TextField
            label={`Share label ${index + 1}`}
            placeholder="Enter link text label"
            value={item.label}
            onChange={(label) =>
              update((value) => {
                value.items[index]!.label = label;
              })
            }
          />
          <div className="nl-flex">
            <button
              aria-label={`Move social share ${index + 1} up`}
              disabled={index === 0}
              onClick={() => move(index, index - 1)}
            >
              Move up
            </button>
            <button
              aria-label={`Move social share ${index + 1} down`}
              disabled={index === share.items.length - 1}
              onClick={() => move(index, index + 1)}
            >
              Move down
            </button>
          </div>
        </div>
      ))}
      <button
        disabled={share.items.length >= sharePlatforms.length}
        onClick={() => {
          const next = sharePlatforms.find(
            ([key]) => !share.items.some((item) => item.platform === key),
          );
          if (next)
            update((value) => {
              value.items.push({ platform: next[0], label: 'Share' });
            });
        }}
      >
        Add another social link
      </button>
    </section>
  );
}

import { useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react';
import { Modal } from './controls.js';
import {
  newsletterError,
  type NewsletterAsset,
  type NewsletterClient,
  type NewsletterStockImage,
  type NewsletterStockPage,
  type NewsletterStockStatus,
} from './api.js';

export function NewsletterStockImages({
  api,
  onInsert,
  onBusy,
}: {
  api: NewsletterClient;
  onInsert: (asset: NewsletterAsset) => void;
  onBusy: (busy: boolean) => void;
}) {
  const [status, setStatus] = useState<NewsletterStockStatus | null>(null);
  const [draft, setDraft] = useState('');
  const [query, setQuery] = useState({ search: '', page: 1 });
  const [pageInput, setPageInput] = useState('1');
  const [result, setResult] = useState<NewsletterStockPage | null>(null);
  const [selected, setSelected] = useState<NewsletterStockImage | null>(null);
  const [details, setDetails] = useState(false);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [reload, setReload] = useState(0);
  const pending = useRef(false);
  const active = useRef(true);
  useEffect(() => {
    active.current = true;
    return () => {
      active.current = false;
    };
  }, []);
  useEffect(() => {
    let cancelled = false;
    setStatus(null);
    setLoading(true);
    setError('');
    api
      .stockImageStatus()
      .then((value) => {
        if (!cancelled) {
          setStatus(value);
          if (!value.available) setLoading(false);
        }
      })
      .catch((error) => {
        if (!cancelled) {
          setError(newsletterError(error));
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [api, reload]);
  useEffect(() => {
    if (!status?.available) return;
    let cancelled = false;
    setLoading(true);
    setError('');
    setResult(null);
    setSelected(null);
    api
      .stockImages(query.search, query.page)
      .then((value) => {
        if (!cancelled) {
          setResult(value);
          setLoading(false);
        }
      })
      .catch((error) => {
        if (!cancelled) {
          setError(newsletterError(error));
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [api, status, query]);
  const pages = Math.ceil((result?.total ?? 0) / 10);
  const page = (value: number) => {
    setSelected(null);
    setError('');
    setDetails(false);
    setPageInput(String(value));
    setQuery((previous) => ({ ...previous, page: value }));
  };
  const commitPage = () => {
    const value = Number(pageInput);
    if (Number.isInteger(value) && value >= 1 && value <= pages) page(value);
    else setPageInput(String(query.page));
  };
  const insert = async () => {
    if (!selected || pending.current || loading || !status?.available) return;
    pending.current = true;
    setBusy(true);
    onBusy(true);
    setError('');
    try {
      const asset = await api.importStockImage(selected.id);
      if (active.current) onInsert(asset);
    } catch (error) {
      if (active.current) setError(newsletterError(error));
    } finally {
      pending.current = false;
      if (active.current) {
        setBusy(false);
        onBusy(false);
      }
    }
  };
  const disabled = busy || loading || !!error || !result;
  return (
    <div className="nl-studio-stock-container">
      <div
        className="nl-modal-body nl-studio-uploads"
        role="tabpanel"
        id="nl-studio-stock"
        aria-labelledby="nl-studio-stock-tab"
        aria-busy={loading || busy}
      >
        <form
          className="nl-studio-toolbar"
          onSubmit={(event) => {
            event.preventDefault();
            if (busy || !status?.available) return;
            setSelected(null);
            setDetails(false);
            setPageInput('1');
            setQuery({ search: draft.trim(), page: 1 });
          }}
        >
          <label className="nl-studio-search">
            Search stock images
            <input
              type="search"
              maxLength={100}
              placeholder="Search stock images"
              value={draft}
              disabled={busy || !status?.available}
              onChange={(event) => setDraft(event.target.value)}
            />
          </label>
          <button type="submit" disabled={busy || !status?.available}>
            Search
          </button>
        </form>
        <p>
          <a href="https://www.pexels.com" target="_blank" rel="noopener noreferrer">
            Photos provided by Pexels
          </a>
        </p>
        {loading && <p role="status">Loading stock images…</p>}
        {!loading && status && !status.available && <p role="status">{status.reason}</p>}
        {error && (
          <div role="alert">
            <p>{error}</p>
            {!busy && <button onClick={() => setReload((value) => value + 1)}>Try again</button>}
          </div>
        )}
        {!loading && !error && result && !result.items.length && (
          <p role="status">No stock images found. Try another search.</p>
        )}
        {selected && !loading && (
          <div className="nl-studio-display">
            <span role="status">1 item selected</span>
            <button
              disabled={busy}
              onClick={() => {
                setSelected(null);
                setDetails(false);
              }}
            >
              Deselect all
            </button>
            <button disabled={busy} onClick={() => setDetails(true)}>
              View details
            </button>
          </div>
        )}
        {!loading && !error && (
          <div className="nl-asset-grid nl-stock-grid" aria-label="Stock images">
            {result?.items.map((image) => (
              <div className="nl-stock-card" key={image.id}>
                <button
                  aria-label={`Select ${image.title || 'stock photo'} ${image.id}`}
                  aria-pressed={selected?.id === image.id}
                  disabled={busy}
                  onClick={() =>
                    setSelected((previous) => (previous?.id === image.id ? null : image))
                  }
                >
                  <img
                    src={image.thumbnailUrl}
                    alt=""
                    loading="lazy"
                    referrerPolicy="no-referrer"
                  />
                  <span>{image.title || 'Stock photo'}</span>
                </button>
                <a href={image.sourceUrl} target="_blank" rel="noopener noreferrer">
                  Photo by {image.photographer} on Pexels
                </a>
              </div>
            ))}
          </div>
        )}
      </div>
      <footer className="nl-studio-footer">
        <div className="nl-studio-pagination">
          <label>
            Items per page{' '}
            <select aria-label="Items per page" value="10" disabled>
              <option>10</option>
            </select>
          </label>
          <span>
            Showing results{' '}
            <strong>
              {result?.total ? (query.page - 1) * 10 + 1 : 0} –{' '}
              {Math.min(query.page * 10, result?.total ?? 0)} of {result?.total ?? 0}
            </strong>
          </span>
          <div className="nl-studio-page-buttons">
            <button
              aria-label="Go to first page"
              disabled={disabled || query.page === 1}
              onClick={() => page(1)}
            >
              <ChevronsLeft size={18} />
            </button>
            <button
              aria-label="Go to previous page"
              disabled={disabled || query.page === 1}
              onClick={() => page(query.page - 1)}
            >
              <ChevronLeft size={18} />
            </button>
            <label>
              Page{' '}
              <input
                aria-label="Page number"
                type="number"
                min={1}
                max={pages || 1}
                value={pageInput}
                disabled={disabled || !pages}
                onChange={(event) => setPageInput(event.target.value)}
                onBlur={commitPage}
                onKeyDown={(event) => {
                  if (event.key === 'Enter') {
                    event.preventDefault();
                    commitPage();
                  }
                }}
              />
            </label>
            <span>of {pages}</span>
            <button
              aria-label="Go to next page"
              disabled={disabled || query.page >= pages}
              onClick={() => page(query.page + 1)}
            >
              <ChevronRight size={18} />
            </button>
            <button
              aria-label="Go to last page"
              disabled={disabled || query.page >= pages}
              onClick={() => page(pages)}
            >
              <ChevronsRight size={18} />
            </button>
          </div>
        </div>
        <div className="nl-studio-insert">
          <span>{selected?.title}</span>
          <button
            className="nl-primary"
            disabled={busy || loading || !selected || !status?.available}
            onClick={() => void insert()}
          >
            {busy ? 'Adding image…' : 'Insert'}
          </button>
        </div>
      </footer>
      {details && selected && (
        <Modal
          title="Stock image details"
          onClose={() => {
            if (!pending.current) setDetails(false);
          }}
        >
          <div className="nl-modal-body nl-stock-details">
            <img src={selected.imageUrl} alt={selected.title} referrerPolicy="no-referrer" />
            <p>{selected.title}</p>
            <p>
              {selected.width} × {selected.height} pixels
            </p>
            <a href={selected.sourceUrl} target="_blank" rel="noopener noreferrer">
              Photo by {selected.photographer} on Pexels
            </a>
            <p>Insert saves a copy to your newsletter images.</p>
            {error && <p role="alert">{error}</p>}
          </div>
          <footer>
            <button disabled={busy} onClick={() => setDetails(false)}>
              Close
            </button>
            <button className="nl-primary" disabled={busy} onClick={() => void insert()}>
              {busy ? 'Adding image…' : 'Insert'}
            </button>
          </footer>
        </Modal>
      )}
    </div>
  );
}

import { useState } from 'react';
import {
  NEWSLETTER_SURVEY_SECTION_TYPES,
  createNewsletterSurveyQuestion,
  defaultNewsletterSurveyDefinition,
  type NewsletterSavedSurvey,
  type NewsletterSurveyDefinition,
  type NewsletterSurveyQuestion,
} from '@capiro/shared/newsletter';
import { Check, ColorField, Modal, NumberField, SelectField, TextField } from './controls.js';
import { type NewsletterClient } from './api.js';
import { NewsletterSurveyMedia } from './NewsletterSurveyMedia.js';
import { NewsletterSurveyDraftPreview } from './NewsletterSurveyPreview.js';
import { useNewsletterSurveySave } from './useNewsletterSurveySave.js';

export function NewsletterSurveyBuilder({
  api,
  mediaApi,
  documentId,
  initial,
  onDraftSaved,
  onSaved,
  onClose,
}: {
  api: Pick<NewsletterClient, 'saveSurvey'>;
  mediaApi?: NewsletterClient;
  documentId: string;
  initial?: NewsletterSavedSurvey;
  onDraftSaved?: (survey: NewsletterSavedSurvey) => void;
  onSaved: (survey: NewsletterSavedSurvey) => void;
  onClose: () => void;
}) {
  const [name, setName] = useState(initial?.name || '');
  const [definition, setDefinition] = useState(() =>
    structuredClone(initial?.definition || defaultNewsletterSurveyDefinition()),
  );
  const [step, setStep] = useState<'Setup' | 'Content' | 'Design' | 'Review'>(
    initial ? 'Content' : 'Setup',
  );
  const [selected, setSelected] = useState<string | null>(
    initial?.definition.questions[0]?.id || null,
  );
  const [mediaBusy, setMediaBusy] = useState(false);
  const { busy, error, status, save, close } = useNewsletterSurveySave({
    api,
    documentId,
    initial,
    name,
    definition,
    enabled: step !== 'Setup',
    mediaBusy,
    onDraftSaved,
    onSaved,
    onClose,
    onNameRequired: () => setStep('Setup'),
  });
  const question = definition.questions.find((q) => q.id === selected);
  const edit = (change: (value: NewsletterSurveyDefinition) => void) =>
    setDefinition((value) => {
      const copy = structuredClone(value);
      change(copy);
      return copy;
    });
  const editQuestion = (change: (value: NewsletterSurveyQuestion) => void) =>
    edit((value) => {
      const found = value.questions.find((q) => q.id === selected);
      if (found) change(found);
    });
  const introduction = question?.type === 'introduction';
  const showContent = !introduction || question.introductionType !== null;
  const showImage =
    !introduction ||
    question.introductionType === undefined ||
    question.introductionType === 'image';
  const showVideo =
    !introduction ||
    question.introductionType === undefined ||
    question.introductionType === 'video';
  return (
    <Modal
      title={step === 'Setup' ? 'Setup your survey' : `Survey · ${name}`}
      onClose={() => {
        if (!busy && !mediaBusy) void close();
      }}
      wide
      className="nl-survey-builder"
    >
      <p className="nl-muted">
        Workspace survey draft · Destinations are selected later in Outreach.
      </p>
      {error && (
        <p role="alert" className="nl-error">
          {error}
        </p>
      )}
      <fieldset disabled={busy || mediaBusy} className="nl-survey-fields">
        {step === 'Setup' ? (
          <>
            <TextField label="Survey name" value={name} onChange={setName} />
            <button type="button" disabled={!name.trim()} onClick={() => setStep('Content')}>
              Begin
            </button>
          </>
        ) : (
          <>
            <nav aria-label="Survey steps" className="nl-flex">
              {(['Content', 'Design', 'Review'] as const).map((value) => (
                <button
                  key={value}
                  type="button"
                  aria-current={step === value ? 'step' : undefined}
                  onClick={() => setStep(value)}
                >
                  {value}
                </button>
              ))}
            </nav>
            {step === 'Content' && (
              <div className="nl-survey-builder-grid">
                <aside aria-label="Survey sections">
                  <h3>Add a section</h3>
                  <div className="nl-grid2">
                    {NEWSLETTER_SURVEY_SECTION_TYPES.map(([type, label]) => (
                      <button
                        key={type}
                        type="button"
                        disabled={definition.questions.length >= 30}
                        onClick={() => {
                          const next = createNewsletterSurveyQuestion(type);
                          if (type === 'radio' || type === 'checkbox')
                            next.options = ['Option 1', 'Option 2'];
                          edit((value) => value.questions.push(next));
                          setSelected(next.id);
                        }}
                      >
                        {label}
                      </button>
                    ))}
                  </div>
                  <ol>
                    {definition.questions.map((q, index) => (
                      <li key={q.id}>
                        <button
                          type="button"
                          aria-pressed={q.id === selected}
                          onClick={() => setSelected(q.id)}
                        >
                          {index + 1}.{' '}
                          {q.prompt ||
                            NEWSLETTER_SURVEY_SECTION_TYPES.find(([type]) => type === q.type)?.[1]}
                        </button>
                      </li>
                    ))}
                  </ol>
                </aside>
                <section aria-label="Survey section editor">
                  {question ? (
                    <>
                      <h3>
                        {
                          NEWSLETTER_SURVEY_SECTION_TYPES.find(
                            ([type]) => type === question.type,
                          )?.[1]
                        }
                      </h3>
                      {introduction && (
                        <fieldset className="nl-survey-introduction-types">
                          <legend>Introduction content</legend>
                          {(
                            [
                              [
                                'video',
                                'Embed Video',
                                'Introduce your policy briefing with a YouTube or Vimeo video.',
                              ],
                              [
                                'text',
                                'Text Introduction',
                                'Explain how client feedback will inform your bill and news coverage.',
                              ],
                              [
                                'image',
                                'Image',
                                'Add an image and supporting text for your clients.',
                              ],
                            ] as const
                          ).map(([value, label, description]) => (
                            <label key={value} className="nl-survey-introduction-card">
                              <input
                                type="radio"
                                name={`introduction-${question.id}`}
                                checked={question.introductionType === value}
                                onChange={() =>
                                  editQuestion((q) => {
                                    q.introductionType = value;
                                  })
                                }
                              />
                              <span>
                                <strong>{label}</strong>
                                <small>{description}</small>
                              </span>
                            </label>
                          ))}
                          {question.introductionType === undefined && (
                            <p className="nl-muted">
                              Choose a content type for this introduction. Your existing text and
                              media will be retained.
                            </p>
                          )}
                        </fieldset>
                      )}
                      {showContent && (
                        <TextField
                          label={
                            ['introduction', 'content'].includes(question.type)
                              ? 'Content'
                              : 'What would you like to ask?'
                          }
                          value={question.prompt}
                          multiline={['introduction', 'content'].includes(question.type)}
                          onChange={(value) =>
                            editQuestion((q) => {
                              q.prompt = value;
                            })
                          }
                        />
                      )}
                      {!['introduction', 'content'].includes(question.type) && (
                        <Check
                          label="Required"
                          checked={question.required}
                          onChange={(value) =>
                            editQuestion((q) => {
                              q.required = value;
                            })
                          }
                        />
                      )}
                      {['radio', 'checkbox'].includes(question.type) && (
                        <>
                          {question.options.map((option, index) => (
                            <div className="nl-flex" key={index}>
                              <label className="nl-field">
                                <span>Choice {index + 1}</span>
                                <input
                                  value={option}
                                  onChange={(event) =>
                                    editQuestion((q) => {
                                      q.options[index] = event.target.value;
                                    })
                                  }
                                  onKeyDown={(event) => {
                                    if (event.key === 'Enter' && question.options.length < 30) {
                                      event.preventDefault();
                                      editQuestion((q) => q.options.push(''));
                                    }
                                  }}
                                />
                              </label>
                              <button
                                type="button"
                                aria-label={`Delete choice ${index + 1}`}
                                onClick={() => editQuestion((q) => q.options.splice(index, 1))}
                              >
                                ×
                              </button>
                            </div>
                          ))}
                          <button
                            type="button"
                            disabled={question.options.length >= 30}
                            onClick={() => editQuestion((q) => q.options.push(''))}
                          >
                            Add choice
                          </button>
                          <Check
                            label="Toggle Other Option"
                            checked={question.other}
                            onChange={(value) =>
                              editQuestion((q) => {
                                q.other = value;
                              })
                            }
                          />
                        </>
                      )}
                      {question.type === 'range' && (
                        <>
                          <SelectField
                            label="Range display"
                            value={question.range.display}
                            values={['numbers', 'stars', 'emojis', 'hearts']}
                            onChange={(value) =>
                              editQuestion((q) => {
                                q.range.display = value;
                              })
                            }
                          />
                          <div className="nl-grid2">
                            <NumberField
                              label="Range minimum"
                              value={question.range.min}
                              max={9}
                              onChange={(value) =>
                                editQuestion((q) => {
                                  q.range.min = Math.round(value);
                                  q.range.max = Math.max(q.range.max, q.range.min + 1);
                                })
                              }
                            />
                            <NumberField
                              label="Range maximum"
                              value={question.range.max}
                              min={1}
                              max={10}
                              onChange={(value) =>
                                editQuestion((q) => {
                                  q.range.max = Math.round(value);
                                  q.range.min = Math.min(q.range.min, q.range.max - 1);
                                })
                              }
                            />
                          </div>
                        </>
                      )}
                      {question.type === 'email' && (
                        <Check
                          label="Ask to subscribe"
                          checked={question.askToSubscribe}
                          onChange={(value) =>
                            editQuestion((q) => {
                              q.askToSubscribe = value;
                            })
                          }
                        />
                      )}
                      {question.type === 'contact' && (
                        <SelectField
                          label="Contact field"
                          value={question.contactField}
                          values={[
                            ['firstName', 'First name'],
                            ['lastName', 'Last name'],
                            ['age', 'Age'],
                            ['gender', 'Gender'],
                            ['address', 'Address'],
                          ]}
                          onChange={(value) =>
                            editQuestion((q) => {
                              q.contactField = value;
                            })
                          }
                        />
                      )}
                      {['introduction', 'content'].includes(question.type) && (
                        <>
                          {showImage && mediaApi && (
                            <NewsletterSurveyMedia
                              key={question.id}
                              api={mediaApi}
                              documentId={documentId}
                              label="Section image"
                              value={question.imageUrl}
                              alt={question.alt}
                              onBusy={setMediaBusy}
                              onChange={(url, alt) =>
                                editQuestion((q) => {
                                  q.imageUrl = url;
                                  if (alt !== undefined) q.alt = alt;
                                })
                              }
                            />
                          )}
                          {showImage && (
                            <TextField
                              label="Image URL"
                              value={question.imageUrl}
                              onChange={(value) =>
                                editQuestion((q) => {
                                  q.imageUrl = value;
                                })
                              }
                            />
                          )}
                          {showImage && (
                            <TextField
                              label="Image description"
                              value={question.alt}
                              onChange={(value) =>
                                editQuestion((q) => {
                                  q.alt = value;
                                })
                              }
                            />
                          )}
                          {showVideo && (
                            <TextField
                              label="Video URL"
                              value={question.videoUrl}
                              onChange={(value) =>
                                editQuestion((q) => {
                                  q.videoUrl = value;
                                })
                              }
                            />
                          )}
                        </>
                      )}
                      <div className="nl-flex">
                        <button
                          type="button"
                          disabled={definition.questions.length >= 30}
                          onClick={() => {
                            const next = {
                              ...structuredClone(question),
                              id: createNewsletterSurveyQuestion(question.type).id,
                            };
                            edit((value) =>
                              value.questions.splice(
                                value.questions.findIndex((q) => q.id === selected) + 1,
                                0,
                                next,
                              ),
                            );
                            setSelected(next.id);
                          }}
                        >
                          Duplicate Question
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            edit((value) => {
                              value.questions = value.questions.filter((q) => q.id !== selected);
                            });
                            setSelected(null);
                          }}
                        >
                          Delete Question
                        </button>
                        {([-1, 1] as const).map((direction) => (
                          <button
                            key={direction}
                            type="button"
                            aria-label={`Move question ${direction < 0 ? 'up' : 'down'}`}
                            disabled={
                              definition.questions.findIndex((q) => q.id === selected) + direction <
                                0 ||
                              definition.questions.findIndex((q) => q.id === selected) +
                                direction >=
                                definition.questions.length
                            }
                            onClick={() =>
                              edit((value) => {
                                const index = value.questions.findIndex((q) => q.id === selected);
                                const [q] = value.questions.splice(index, 1);
                                value.questions.splice(index + direction, 0, q!);
                              })
                            }
                          >
                            {direction < 0 ? '↑' : '↓'}
                          </button>
                        ))}
                      </div>
                    </>
                  ) : (
                    <p>
                      Choose a section type to add questions, an introduction or supporting content.
                    </p>
                  )}
                </section>
              </div>
            )}
            {step === 'Design' && (
              <>
                <h3>Branding</h3>
                {mediaApi && (
                  <NewsletterSurveyMedia
                    key="survey-logo"
                    api={mediaApi}
                    documentId={documentId}
                    label="Survey logo"
                    value={definition.logoUrl}
                    alt="Survey logo"
                    onBusy={setMediaBusy}
                    onChange={(url) =>
                      edit((d) => {
                        d.logoUrl = url;
                      })
                    }
                  />
                )}
                <TextField
                  label="Logo URL"
                  value={definition.logoUrl}
                  onChange={(value) =>
                    edit((d) => {
                      d.logoUrl = value;
                    })
                  }
                />
                <TextField
                  label="Description"
                  multiline
                  value={definition.description}
                  onChange={(value) =>
                    edit((d) => {
                      d.description = value;
                    })
                  }
                />
                <h3>Custom Messaging</h3>
                {(
                  [
                    ['title', 'Survey title'],
                    ['submitLabel', 'Submit button label'],
                    ['confirmation', 'Confirmation message'],
                    ['closedMessage', 'Closed survey message'],
                    ['requiredMessage', 'Required response error message'],
                  ] as const
                ).map(([key, label]) => (
                  <TextField
                    key={key}
                    label={label}
                    value={definition[key]}
                    onChange={(value) =>
                      edit((d) => {
                        d[key] = value;
                      })
                    }
                  />
                ))}
                <h3>Styles</h3>
                {(
                  [
                    ['background', 'Background color'],
                    ['buttonColor', 'Button color'],
                    ['buttonTextColor', 'Button text color'],
                  ] as const
                ).map(([key, label]) => (
                  <ColorField
                    key={key}
                    label={label}
                    value={definition[key]}
                    onChange={(value) =>
                      edit((d) => {
                        d[key] = value;
                      })
                    }
                  />
                ))}
              </>
            )}
            {step === 'Review' && (
              <>
                <TextField label="Survey name" value={name} onChange={setName} />
                <NewsletterSurveyDraftPreview definition={definition} />
                <p role="status">
                  Save this reusable draft to Workspace. Hosted response delivery, tagging and
                  notifications remain pending.
                </p>
              </>
            )}
            <div className="nl-flex nl-survey-footer">
              {step === 'Content' && (
                <button type="button" onClick={() => setStep('Design')}>
                  Continue to design
                </button>
              )}
              {step === 'Design' && (
                <button type="button" onClick={() => setStep('Review')}>
                  Review
                </button>
              )}
              <button type="button" onClick={() => void save()}>
                Save survey draft
              </button>
              <button type="button" onClick={() => void close()}>
                Go back
              </button>
            </div>
          </>
        )}
      </fieldset>
      {step !== 'Setup' && (
        <p role="status" className="nl-survey-save-status">
          {status === 'saving' || busy
            ? 'Saving survey…'
            : status === 'saved'
              ? 'All changes saved to Workspace.'
              : status === 'failed'
                ? 'Changes are unsaved. Use Save survey draft to retry.'
                : 'Unsaved changes'}
        </p>
      )}
    </Modal>
  );
}

import { useEffect, useRef, useState } from 'react';
import {
  type NewsletterBlock,
  type NewsletterSavedSurvey,
  type NewsletterStyle,
} from '@capiro/shared/newsletter';
import {
  Check,
  ColorField,
  Modal,
  NewsletterFontField,
  NumberField,
  SelectField,
  Tabs,
  TextField,
} from './controls.js';
import { newsletterError, type NewsletterClient } from './api.js';
import { NewsletterSurveyBuilder } from './NewsletterSurveyBuilder.js';

export function NewsletterSurveyDesign({
  block,
  defaults,
  api,
  documentId,
  onChange,
  onBeforeLoad,
}: {
  block: NewsletterBlock;
  defaults: NewsletterStyle;
  api: NewsletterClient;
  documentId: string;
  onChange: (change: (block: NewsletterBlock) => void) => void;
  onBeforeLoad: () => Promise<unknown>;
}) {
  const [items, setItems] = useState<NewsletterSavedSurvey[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [intro, setIntro] = useState(false);
  const [builder, setBuilder] = useState<NewsletterSavedSurvey | 'new' | null>(null);
  const [device, setDevice] = useState('Desktop');
  const [reload, setReload] = useState(0);
  const active = useRef(true);
  useEffect(() => {
    active.current = true;
    return () => {
      active.current = false;
    };
  }, []);
  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError('');
    void (async () => {
      try {
        await onBeforeLoad();
        const result = await api.surveys(documentId);
        if (alive) {
          setItems(result);
          if (!result.length && !block.survey?.saved && reload === 0) setIntro(true);
        }
      } catch (error) {
        if (alive) setError(newsletterError(error));
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
    };
    // The key in NewsletterEditor identifies the captured document/block; edits do not restart loading.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [api, documentId, reload]);
  const mobile = device === 'Mobile' && !block.linkedStyles;
  const style = { ...defaults, ...block.style, ...(mobile ? block.mobileStyle : {}) };
  const globalStyle = { ...defaults, ...block.style };
  const setStyle = (key: keyof NewsletterStyle, value: NewsletterStyle[keyof NewsletterStyle]) =>
    onChange((draft) => {
      const target = mobile ? draft.mobileStyle : draft.style;
      Object.assign(target, { [key]: value });
    });
  const setGlobalStyle = (
    key: keyof NewsletterStyle,
    value: NewsletterStyle[keyof NewsletterStyle],
  ) =>
    onChange((draft) => {
      Object.assign(draft.style, { [key]: value });
    });
  const radius = globalStyle.radius || 0;
  const shape = radius === 1000 ? 'pill' : radius === 8 ? 'round' : radius ? 'custom' : 'square';
  const size =
    style.paddingTop === style.paddingBottom &&
    style.paddingLeft === (style.paddingTop || 0) * 2 &&
    style.paddingRight === style.paddingLeft
      ? style.paddingTop === 8
        ? 'small'
        : style.paddingTop === 12
          ? 'medium'
          : style.paddingTop === 18
            ? 'large'
            : 'custom'
      : 'custom';
  const acceptSaved = (result: NewsletterSavedSurvey) => {
    if (!active.current) return;
    setItems((value) => [result, ...value.filter((item) => item.id !== result.id)]);
    onChange((draft) => {
      if (draft.survey) draft.survey.saved = structuredClone(result);
    });
  };
  return (
    <section aria-label="Survey button design">
      {loading && <p role="status">Loading saved surveys…</p>}
      {error && (
        <>
          <p role="alert">{error}</p>
          <button type="button" onClick={() => setReload((value) => value + 1)}>
            Retry saved surveys
          </button>
        </>
      )}
      {!loading && !error && (
        <>
          {items.length ? (
            <SelectField
              label="Link to survey"
              value={block.survey?.saved?.id || ''}
              values={[
                '',
                ...items.map((item) => [item.id, `${item.name} · Draft`] as [string, string]),
              ]}
              onChange={(value) =>
                onChange((draft) => {
                  if (draft.survey)
                    draft.survey.saved = structuredClone(
                      items.find((item) => item.id === value) || null,
                    );
                })
              }
            />
          ) : (
            <p className="nl-survey-empty">You haven't created any surveys yet.</p>
          )}
          {block.survey?.saved && (
            <p role="status">
              Linked draft: {block.survey.saved.name} · Revision {block.survey.saved.revision}
            </p>
          )}
          <div className="nl-flex">
            <button type="button" onClick={() => setBuilder('new')}>
              Create Survey
            </button>
            {block.survey?.saved && (
              <button
                type="button"
                onClick={() =>
                  setBuilder(
                    items.find((item) => item.id === block.survey?.saved?.id) ||
                      block.survey!.saved!,
                  )
                }
              >
                Edit survey
              </button>
            )}
            <button type="button" onClick={() => setReload((value) => value + 1)}>
              Refresh surveys
            </button>
          </div>
        </>
      )}
      <TextField
        label="Button text"
        value={block.text}
        onChange={(value) =>
          onChange((draft) => {
            draft.text = value;
            draft.html = '';
          })
        }
      />
      <SelectField
        label="Button shape"
        value={shape}
        values={['square', 'round', 'pill', 'custom']}
        onChange={(value) =>
          setGlobalStyle(
            'radius',
            value === 'pill' ? 1000 : value === 'round' ? 8 : value === 'square' ? 0 : 16,
          )
        }
      />
      {shape === 'custom' && (
        <NumberField
          label="Rounded corners"
          value={radius}
          max={1000}
          onChange={(value) => setGlobalStyle('radius', value)}
        />
      )}
      <h3>Colors</h3>
      <ColorField
        label="Button color"
        value={globalStyle.background || '#141414'}
        onChange={(value) => setGlobalStyle('background', value)}
      />
      <ColorField
        label="Text color"
        value={globalStyle.color || '#ffffff'}
        onChange={(value) => setGlobalStyle('color', value)}
      />
      <ColorField
        label="Block background color"
        value={block.survey?.blockBackground || ''}
        onChange={(value) =>
          onChange((draft) => {
            if (draft.survey) draft.survey.blockBackground = value;
          })
        }
      />
      <h3>Border</h3>
      <SelectField
        label="Border"
        value={globalStyle.borderStyle || 'none'}
        values={[
          'none',
          'solid',
          'dashed',
          'dotted',
          'double',
          'inset',
          'outset',
          'groove',
          'ridge',
        ]}
        onChange={(value) => setGlobalStyle('borderStyle', value)}
      />
      <div className="nl-grid2">
        <ColorField
          label="Border color"
          value={globalStyle.borderColor || '#f05f26'}
          onChange={(value) => setGlobalStyle('borderColor', value)}
        />
        <NumberField
          label="Border width"
          value={globalStyle.borderWidth ?? 1}
          max={30}
          onChange={(value) => setGlobalStyle('borderWidth', value)}
        />
      </div>
      <h3>Device-specific</h3>
      <Check
        label="Link Desktop and Mobile Styles"
        checked={block.linkedStyles}
        onChange={(value) =>
          onChange((draft) => {
            draft.linkedStyles = value;
            if (!value)
              draft.mobileStyle = {
                fontFamily: style.fontFamily,
                fontSize: style.fontSize,
                letterSpacing: style.letterSpacing,
                bold: style.bold,
                italic: style.italic,
                underline: style.underline,
                align: style.align,
                paddingTop: style.paddingTop,
                paddingBottom: style.paddingBottom,
                paddingLeft: style.paddingLeft,
                paddingRight: style.paddingRight,
              };
          })
        }
      />
      <Tabs value={device} values={['Desktop', 'Mobile']} onChange={setDevice} />
      <NewsletterFontField
        label="Font"
        value={style.fontFamily || 'Arial'}
        onChange={(value) => setStyle('fontFamily', value)}
      />
      <div className="nl-grid2">
        <NumberField
          label="Font size"
          value={style.fontSize ?? 16}
          min={1}
          max={200}
          onChange={(value) => setStyle('fontSize', value)}
        />
        <NumberField
          label="Letter spacing"
          value={style.letterSpacing ?? 0}
          max={30}
          step={0.1}
          onChange={(value) => setStyle('letterSpacing', value)}
        />
      </div>
      <div className="nl-format">
        {(['bold', 'italic', 'underline'] as const).map((key) => (
          <button
            type="button"
            key={key}
            aria-label={key}
            aria-pressed={!!style[key]}
            onClick={() =>
              onChange((draft) =>
                Object.assign(mobile ? draft.mobileStyle : draft.style, {
                  [key]: !style[key],
                  ...(key === 'bold' ? { fontWeight: !style[key] ? 700 : 400 } : {}),
                }),
              )
            }
          >
            {key}
          </button>
        ))}
      </div>
      <SelectField
        label="Size"
        value={size}
        values={['small', 'medium', 'large', 'custom']}
        onChange={(value) => {
          if (value === 'custom') return;
          const padding = value === 'small' ? 8 : value === 'medium' ? 12 : 18;
          onChange((draft) => {
            Object.assign(mobile ? draft.mobileStyle : draft.style, {
              paddingTop: padding,
              paddingBottom: padding,
              paddingLeft: padding * 2,
              paddingRight: padding * 2,
            });
            if (draft.survey) draft.survey.paddingLinked = false;
          });
        }}
      />
      <SelectField
        label="Alignment"
        value={style.align || 'center'}
        values={['left', 'center', 'right']}
        onChange={(value) => setStyle('align', value)}
      />
      <h3>Padding</h3>
      <div className="nl-grid2">
        {(['Top', 'Bottom', 'Left', 'Right'] as const).map((side) => {
          const key = `padding${side}` as
            'paddingTop' | 'paddingBottom' | 'paddingLeft' | 'paddingRight';
          return (
            <NumberField
              key={side}
              label={`Padding ${side.toLowerCase()}`}
              value={style[key] ?? (side === 'Top' || side === 'Bottom' ? 12 : 24)}
              max={1000}
              onChange={(value) =>
                onChange((draft) =>
                  Object.assign(
                    mobile ? draft.mobileStyle : draft.style,
                    draft.survey?.paddingLinked
                      ? {
                          paddingTop: value,
                          paddingBottom: value,
                          paddingLeft: value,
                          paddingRight: value,
                        }
                      : { [key]: value },
                  ),
                )
              }
            />
          );
        })}
      </div>
      <Check
        label="Apply to all sides"
        checked={!!block.survey?.paddingLinked}
        onChange={(value) =>
          onChange((draft) => {
            if (draft.survey) draft.survey.paddingLinked = value;
            if (value)
              Object.assign(mobile ? draft.mobileStyle : draft.style, {
                paddingTop: style.paddingTop ?? 12,
                paddingBottom: style.paddingTop ?? 12,
                paddingLeft: style.paddingTop ?? 12,
                paddingRight: style.paddingTop ?? 12,
              });
          })
        }
      />
      <p className="nl-muted">
        Saved survey drafts cannot be staged until hosted response delivery is complete.
      </p>
      {intro && (
        <Modal title="Create a survey" onClose={() => setIntro(false)}>
          <h3>Learn what matters to your clients</h3>
          <p>Create a reusable survey draft with questions, branding and custom messages.</p>
          <button
            type="button"
            onClick={() => {
              setIntro(false);
              setBuilder('new');
            }}
          >
            Create Survey
          </button>
        </Modal>
      )}
      {builder && (
        <NewsletterSurveyBuilder
          api={api}
          mediaApi={api}
          documentId={documentId}
          initial={builder === 'new' ? undefined : builder}
          onDraftSaved={acceptSaved}
          onClose={() => setBuilder(null)}
          onSaved={(result) => {
            acceptSaved(result);
            setBuilder(null);
          }}
        />
      )}
    </section>
  );
}

import { useEffect, useRef, useState } from 'react';
import { newsletterSafeUrl } from '@capiro/shared/newsletter-render';
import { NewsletterContentStudio } from './NewsletterContentStudio.js';
import { NewsletterImageReplaceMenu } from './NewsletterImageReplaceMenu.js';
import { NewsletterAdvancedImageEditor } from './NewsletterAdvancedImageEditor.js';
import { newsletterImageFile } from './NewsletterImageAi.js';
import { newsletterError, newsletterImageToken, type NewsletterClient } from './api.js';

/** A captured section owns the media operation, even if another section is selected later. */
export function NewsletterSurveyMedia({
  api,
  documentId,
  value,
  alt,
  label,
  onChange,
  onBusy,
}: {
  api: NewsletterClient;
  documentId: string;
  value: string;
  alt: string;
  label: string;
  onChange: (url: string, alt?: string) => void;
  onBusy: (busy: boolean) => void;
}) {
  const [studio, setStudio] = useState<string | null>(null);
  const [editor, setEditor] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const active = useRef(false);
  const pending = useRef(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const latest = useRef({ value, alt, onChange, onBusy });
  latest.current = { value, alt, onChange, onBusy };
  useEffect(() => {
    active.current = true;
    return () => {
      active.current = false;
    };
  }, []);
  const upload = async (file: File) => {
    if (pending.current) return;
    if (!file.size || file.size > 10 * 1024 * 1024) {
      setError('Choose an image between 1 byte and 10 MB.');
      return;
    }
    if (!['image/png', 'image/jpeg', 'image/gif', 'image/webp'].includes(file.type)) {
      setError('Choose a PNG, JPG, GIF or WebP image.');
      return;
    }
    const source = { value, alt };
    pending.current = true;
    setBusy(true);
    latest.current.onBusy(true);
    setError('');
    try {
      const asset = await api.upload(file);
      if (!active.current) return;
      if (latest.current.value !== source.value) {
        setError('The image changed while uploading. The upload is saved in Content Studio.');
        return;
      }
      latest.current.onChange(
        new URL(asset.url, window.location.href).href,
        latest.current.alt === source.alt ? asset.altText : undefined,
      );
    } catch (error) {
      if (active.current) setError(newsletterError(error));
    } finally {
      pending.current = false;
      if (active.current) {
        setBusy(false);
        latest.current.onBusy(false);
      }
    }
  };
  return (
    <section aria-label={label} className="nl-survey-media">
      {newsletterSafeUrl(value, true) && <img src={newsletterSafeUrl(value, true)} alt={alt} />}
      <input
        ref={fileInput}
        aria-label={`Upload ${label.toLowerCase()}`}
        type="file"
        hidden
        accept="image/png,image/jpeg,image/gif,image/webp"
        disabled={busy}
        onChange={(event) => {
          const file = event.target.files?.[0];
          event.target.value = '';
          if (file) void upload(file);
        }}
      />
      <div className="nl-flex">
        <NewsletterImageReplaceMenu
          label={value ? 'Replace' : 'Add'}
          disabled={busy}
          canEdit={!!newsletterSafeUrl(value, true)}
          onUpload={() => fileInput.current?.click()}
          onBrowse={() => setStudio(value)}
          onAdvanced={() => setEditor(value)}
        />
        {value && (
          <button type="button" disabled={busy} onClick={() => onChange('')}>
            Remove {label.toLowerCase()}
          </button>
        )}
      </div>
      {busy && <p role="status">Uploading image…</p>}
      {error && <p role="alert">{error}</p>}
      {studio !== null && (
        <NewsletterContentStudio
          api={api}
          onClose={() => setStudio(null)}
          onInsert={(asset) => {
            if (!active.current) return;
            if (latest.current.value !== studio) {
              setError('The image changed. Reopen Content Studio to replace its current version.');
              setStudio(null);
              return;
            }
            onChange(new URL(asset.url, window.location.href).href, asset.altText);
            setStudio(null);
          }}
        />
      )}
      {editor && (
        <NewsletterAdvancedImageEditor
          key={editor}
          url={editor}
          onClose={() => setEditor(null)}
          onSave={async (file) => {
            if (!active.current || latest.current.value !== editor)
              throw new Error('The source image changed. Reopen the image editor.');
            const original = newsletterImageToken(editor)
              ? undefined
              : await newsletterImageFile(editor);
            if (!active.current || latest.current.value !== editor)
              throw new Error('The source image changed. Reopen the image editor.');
            const asset = await api.saveImageRevision(file, editor, original, documentId);
            if (!active.current) return;
            if (latest.current.value !== editor)
              throw new Error('The source image changed. The edit is saved in Content Studio.');
            latest.current.onChange(asset.url);
            setEditor(null);
          }}
        />
      )}
    </section>
  );
}

import { type NewsletterSurveyDefinition, newsletterVideoSource } from '@capiro/shared/newsletter';
import { newsletterSafeUrl } from '@capiro/shared/newsletter-render';

/** Builds a player URL from a known provider's canonical source, never arbitrary iframe markup. */
export function newsletterSurveyVideoEmbed(value: string) {
  const source = newsletterVideoSource(value);
  if (!source) return null;
  const url = new URL(source.url);
  if (source.provider === 'youtube')
    return `https://www.youtube-nocookie.com/embed/${url.searchParams.get('v')}`;
  const parts = url.pathname.split('/').filter(Boolean);
  const unlisted = /^\d+$/.test(parts[0] || '') && parts.length === 2;
  const id = unlisted ? parts[0] : parts[parts.length - 1];
  const player = new URL(`https://player.vimeo.com/video/${id}`);
  const hash = url.searchParams.get('h') || (unlisted ? parts[1] : '');
  if (hash) player.searchParams.set('h', hash);
  player.searchParams.set('dnt', '1');
  return player.href;
}

export function NewsletterSurveyDraftPreview({
  definition,
}: {
  definition: NewsletterSurveyDefinition;
}) {
  return (
    <section
      className="nl-survey-draft-preview"
      aria-label="Survey draft preview"
      style={{ background: definition.background }}
    >
      {newsletterSafeUrl(definition.logoUrl, true) && (
        <img src={newsletterSafeUrl(definition.logoUrl, true)} alt="Survey logo" />
      )}
      <h2>{definition.title}</h2>
      <p>{definition.description}</p>
      {definition.questions.map((question) => {
        const introduction = question.type === 'introduction';
        if (introduction && question.introductionType === null) return null;
        const showImage =
          !introduction ||
          question.introductionType === undefined ||
          question.introductionType === 'image';
        const showVideo =
          !introduction ||
          question.introductionType === undefined ||
          question.introductionType === 'video';
        const embed = newsletterSurveyVideoEmbed(question.videoUrl);
        const count = Math.max(1, Math.min(11, question.range.max - question.range.min + 1));
        return (
          <section key={question.id}>
            <h3>
              {question.prompt}
              {question.required ? ' *' : ''}
            </h3>
            {['radio', 'checkbox'].includes(question.type) ? (
              question.options.map((option, index) => (
                <label key={index}>
                  <input disabled type={question.type === 'radio' ? 'radio' : 'checkbox'} />{' '}
                  {option}
                </label>
              ))
            ) : question.type === 'range' ? (
              <div
                role="group"
                aria-label={question.prompt || 'Rating'}
                className="nl-survey-rating"
              >
                {Array.from({ length: count }, (_, index) => {
                  const value = question.range.min + index;
                  const emoji = ['😞', '🙁', '😐', '🙂', '😄'][
                    Math.round((index / Math.max(1, count - 1)) * 4)
                  ];
                  return (
                    <button
                      type="button"
                      key={value}
                      disabled
                      aria-label={`${value} of ${question.range.max}`}
                    >
                      <span aria-hidden={question.range.display !== 'numbers'}>
                        {question.range.display === 'numbers'
                          ? value
                          : question.range.display === 'stars'
                            ? '☆'
                            : question.range.display === 'hearts'
                              ? '♡'
                              : emoji}
                      </span>
                    </button>
                  );
                })}
              </div>
            ) : question.type === 'text' ? (
              <textarea
                disabled
                aria-label={question.prompt || 'Your answer'}
                placeholder="Your answer"
              />
            ) : !['introduction', 'content'].includes(question.type) ? (
              <input
                disabled
                type={
                  question.type === 'email'
                    ? 'email'
                    : question.type === 'contact' && question.contactField === 'age'
                      ? 'number'
                      : 'text'
                }
                aria-label={question.prompt || question.type}
                placeholder={question.type === 'email' ? 'Email address' : 'Your answer'}
              />
            ) : null}
            {question.other && ['radio', 'checkbox'].includes(question.type) && (
              <p>Other: __________</p>
            )}
            {showImage && newsletterSafeUrl(question.imageUrl, true) && (
              <img src={newsletterSafeUrl(question.imageUrl, true)} alt={question.alt} />
            )}
            {showVideo &&
              (embed ? (
                <iframe
                  src={embed}
                  title={question.prompt ? `Video: ${question.prompt}` : 'Survey video'}
                  loading="lazy"
                  referrerPolicy="strict-origin-when-cross-origin"
                  allow="fullscreen; picture-in-picture"
                  allowFullScreen
                />
              ) : question.videoUrl ? (
                <p className="nl-muted">Use a YouTube or Vimeo video URL to embed this video.</p>
              ) : null)}
            {question.type === 'email' && question.askToSubscribe && (
              <label>
                <input disabled type="checkbox" /> Subscribe to email updates
              </label>
            )}
          </section>
        );
      })}
      <button
        type="button"
        disabled
        style={{ background: definition.buttonColor, color: definition.buttonTextColor }}
      >
        {definition.submitLabel}
      </button>
      <p className="nl-muted">Draft preview · Responses are not submitted.</p>
    </section>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  createNewsletterLayout,
  defaultNewsletterConfig,
  governmentAffairsNewsletter,
  type NewsletterCampaign,
  type NewsletterDesign,
  type NewsletterLibraryItem,
} from '@capiro/shared/newsletter';
import { renderNewsletterDesign } from '@capiro/shared/newsletter-render';
import { newsletterError, useNewsletterApi, type NewsletterClient } from './api.js';
import { Modal, SelectField, TextField, Tabs } from './controls.js';
