export function NewsletterTemplateChooser() {
  const api = useNewsletterApi();
  return <NewsletterTemplateChooserSession api={api} />;
}
export function NewsletterTemplateChooserSession({
  api,
  onApply,
}: {
  api: NewsletterClient;
  onApply?: (design: NewsletterDesign) => void;
}) {
  const navigate = useNavigate();
  const [templates, setTemplates] = useState<NewsletterLibraryItem[]>([]);
  const [drafts, setDrafts] = useState<NewsletterCampaign[]>([]);
  const [search, setSearch] = useState('');
  const [tab, setTab] = useState('All templates');
  const [purpose, setPurpose] = useState('All purposes');
  const [style, setStyle] = useState('All styles');
  const [industry, setIndustry] = useState('All industries');
  const [folder, setFolder] = useState('All folders');
  const [preview, setPreview] = useState<{
    name: string;
    id: string;
    design: NewsletterDesign;
  } | null>(null);
  const [previewDevice, setPreviewDevice] = useState('Desktop');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    let canceled = false;
    Promise.all([api.library('template'), api.list()])
      .then(([saved, documents]) => {
        if (!canceled) {
          setTemplates(saved);
          setDrafts(documents);
        }
      })
      .catch((e) => {
        if (!canceled) setError(newsletterError(e));
      });
    return () => {
      canceled = true;
    };
  }, [api]);
  const create = async (id: string, design: NewsletterDesign) => {
    setBusy(true);
    setError('');
    try {
      if (onApply) {
        onApply(design);
        return;
      }
      const doc = await api.create(id);
      navigate(`/workspace/newsletters/${doc.id}`, { replace: true });
    } catch (e) {
      setError(newsletterError(e));
      setBusy(false);
    }
  };
  const editLibrary = async (action: () => Promise<unknown>) => {
    setBusy(true);
    setError('');
    try {
      await action();
      setTemplates(await api.library('template'));
    } catch (error) {
      setError(newsletterError(error));
    } finally {
      setBusy(false);
    }
  };
  const card = (
    name: string,
    id: string,
    description: string,
    design: NewsletterDesign,
    thumbnail = false,
  ) => (
    <article className="nl-template-card" key={id}>
      {thumbnail ? (
        <img src="/newsletter/template-preview.svg" alt="Government affairs weekly newsletter" />
      ) : (
        <div className="nl-template-mini">{name}</div>
      )}
      <strong>{name}</strong>
      <span>{description}</span>
      <div className="nl-flex">
        <button disabled={busy} onClick={() => void create(id, design)}>
          Apply
        </button>
        <button
          onClick={() => {
            setPreview({ name, id, design });
            setPreviewDevice('Desktop');
          }}
        >
          Preview
        </button>
      </div>
      {templates.some((template) => template.id === id) && (
        <div className="nl-flex">
          <button
            disabled={busy}
            onClick={() => {
              const item = templates.find((template) => template.id === id)!;
              const name = window.prompt('Template name', item.name);
              if (!name?.trim()) return;
              const nextFolder = window.prompt('Folder', item.folder);
              if (nextFolder !== null)
                void editLibrary(() => api.updateLibrary(id, name, nextFolder));
            }}
          >
            Rename / move
          </button>
          <button
            disabled={busy}
            onClick={() => {
              if (window.confirm(`Delete the saved template “${name}”?`))
                void editLibrary(() => api.removeLibrary(id));
            }}
          >
            Delete
          </button>
        </div>
      )}
    </article>
  );
  const match = (name: string) => name.toLowerCase().includes(search.toLowerCase());
  return (
    <div className="nl-root nl-template-chooser">
      <header>
        <h1>Select a template</h1>
        {!onApply && (
          <button onClick={() => navigate('/workspace/documents/new')}>Back to Workspace</button>
        )}
      </header>
      <p>
        Build a weekly client briefing, save your edited layout, and stage it in Outreach when it’s
        ready.
      </p>
      {error ? <p role="alert">{error}</p> : null}
      <TextField label="Search newsletter templates" value={search} onChange={setSearch} />
      <Tabs
        value={tab}
        values={[
          'All templates',
          'Basic layouts',
          'Fully designed',
          'Drafts',
          'Saved templates',
          'Code your own',
        ]}
        onChange={setTab}
      />
      <div className="nl-flex">
        <SelectField
          label="Purpose"
          value={purpose}
          values={['All purposes', 'Educate & inform']}
          onChange={setPurpose}
        />
        <SelectField
          label="Style"
          value={style}
          values={['All styles', 'Newsletter']}
          onChange={setStyle}
        />
        <SelectField
          label="Industry"
          value={industry}
          values={['All industries', 'Government affairs']}
          onChange={setIndustry}
        />
        {tab === 'Saved templates' ? (
          <SelectField
            label="Folder"
            value={folder}
            values={['All folders', ...new Set(templates.map((t) => t.folder).filter(Boolean))]}
            onChange={setFolder}
          />
        ) : null}
      </div>
      <div className="nl-template-grid">
        {['All templates', 'Fully designed'].includes(tab) && match('Weekly newsletter')
          ? card(
              'Weekly newsletter',
              'bp_weekly_newsletter',
              'Educate & inform · Government affairs',
              governmentAffairsNewsletter(),
              true,
            )
          : null}
        {['All templates', 'Basic layouts'].includes(tab) &&
        purpose === 'All purposes' &&
        style === 'All styles' &&
        industry === 'All industries'
          ? [1, 2, 3, 4]
              .filter((columns) => match(`${columns} column layout`))
              .map((columns) =>
                card(
                  `${columns} column layout`,
                  `layout:${columns}`,
                  'Start with a basic layout',
                  createNewsletterLayout(columns),
                ),
              )
          : null}
        {['All templates', 'Saved templates'].includes(tab)
          ? templates
              .filter(
                (t) =>
                  !!t.design && match(t.name) && (folder === 'All folders' || t.folder === folder),
              )
              .map((t) => card(t.name, t.id, t.folder || 'Saved template', t.design!))
          : null}
        {tab === 'Drafts'
          ? drafts
              .filter((d) => match(d.name))
              .map((d) =>
                onApply ? (
                  card(d.name, d.id, 'Draft layout', d.design)
                ) : (
                  <article className="nl-template-card" key={d.id}>
                    <div className="nl-template-mini">{d.name}</div>
                    <strong>{d.name}</strong>
                    <span>
                      {d.status === 'staged' ? 'Staged in Outreach' : 'Draft'} ·{' '}
                      {new Date(d.updatedAt).toLocaleDateString()}
                    </span>
                    <button onClick={() => navigate(`/workspace/newsletters/${d.id}`)}>
                      Continue editing
                    </button>
                  </article>
                ),
              )
          : null}
        {tab === 'Code your own'
          ? card(
              'Paste your HTML',
              'code:html',
              'Create a newsletter with your own HTML',
              createNewsletterLayout(1, true),
            )
          : null}
      </div>
      <button
        className="nl-secondary"
        disabled={busy}
        onClick={() => void create('layout:1', createNewsletterLayout(1))}
      >
        Start from scratch
      </button>
      {tab === 'Saved templates' && !templates.length ? (
        <p>
          No saved templates yet. Save your edited newsletter as a template from the builder’s
          Actions menu.
        </p>
      ) : null}
      {tab === 'Drafts' && !drafts.length ? <p>No newsletter drafts yet.</p> : null}
      {preview ? (
        <Modal title={preview.name} wide onClose={() => setPreview(null)}>
          <div className="nl-modal-body">
            <Tabs
              value={previewDevice}
              values={['Desktop', 'Mobile']}
              onChange={setPreviewDevice}
            />
            <iframe
              title="Template preview"
              sandbox=""
              srcDoc={renderNewsletterDesign(
                preview.design,
                {
                  ...defaultNewsletterConfig(),
                  ...templates.find((template) => template.id === preview.id)?.config,
                },
                {
                  sanitizeHtml: sanitizeNewsletterMarkup,
                  editor: true,
                },
              )}
              style={{
                display: 'block',
                width: previewDevice === 'Mobile' ? 375 : '100%',
                maxWidth: '100%',
                height: 600,
                border: 0,
                margin: '20px auto',
              }}
            />
          </div>
          <footer>
            <button onClick={() => setPreview(null)}>Back</button>
            <button
              className="nl-primary"
              disabled={busy}
              onClick={() => void create(preview.id, preview.design)}
            >
              Apply template
            </button>
          </footer>
        </Modal>
      ) : null}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import {
  newsletterError,
  type NewsletterClient,
  type NewsletterThreadNotifications as Settings,
} from './api.js';
import { Modal } from './controls.js';

/** New-thread choices stay in the composer until its comment is saved. */
export function NewsletterThreadNotifications({
  api,
  documentId,
  rootId,
  currentUserId,
  draftUserIds,
  onSaved,
  onClose,
}: {
  api: NewsletterClient;
  documentId: string;
  rootId?: string;
  currentUserId: string;
  draftUserIds?: string[];
  onSaved: (userIds: string[]) => void;
  onClose: () => void;
}) {
  const [settings, setSettings] = useState<Settings | null>(null);
  const [selected, setSelected] = useState<string[]>([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [reload, setReload] = useState(0);
  const saving = useRef(false);
  useEffect(() => {
    let active = true;
    setLoading(true);
    setError('');
    void api
      .threadNotifications(documentId, rootId)
      .then((next) => {
        if (!active) return;
        setSettings(next);
        setSelected(
          (rootId ? next.userIds : (draftUserIds ?? next.userIds)).filter((id) =>
            next.items.some((item) => item.userId === id),
          ),
        );
      })
      .catch((error) => {
        if (active) setError(newsletterError(error));
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [api, documentId, rootId, draftUserIds, reload]);
  const close = () => {
    if (!saving.current) onClose();
  };
  const save = async () => {
    if (saving.current || !settings?.editable || loading) return;
    saving.current = true;
    setBusy(true);
    setError('');
    try {
      const ids = rootId
        ? (await api.saveThreadNotifications(documentId, rootId, selected)).userIds
        : selected;
      onSaved(ids);
    } catch (error) {
      setError(newsletterError(error));
    } finally {
      saving.current = false;
      setBusy(false);
    }
  };
  return (
    <Modal title="Notify account users" onClose={close}>
      <div className="nl-modal-body nl-thread-notifications">
        <p>
          The users selected below will receive email notifications about comments in this thread.
        </p>
        {loading && <p role="status">Loading account users…</p>}
        {error && (
          <p role="alert">
            {error}
            {!settings && !loading && (
              <button onClick={() => setReload((value) => value + 1)}>Retry</button>
            )}
          </p>
        )}
        {!loading && settings && (
          <>
            {!settings.emailAvailable && (
              <p role="status" className="nl-muted">
                Email delivery is currently unavailable. Your choices will be saved for this thread.
              </p>
            )}
            <fieldset disabled={busy || !settings.editable}>
              <legend className="nl-sr-only">Users to notify</legend>
              {settings.items.map((item) => (
                <label key={item.userId}>
                  <input
                    type="checkbox"
                    checked={selected.includes(item.userId)}
                    onChange={(event) =>
                      setSelected((ids) =>
                        event.target.checked
                          ? [...new Set([...ids, item.userId])]
                          : ids.filter((id) => id !== item.userId),
                      )
                    }
                  />
                  <span>
                    {item.name}
                    {item.userId === currentUserId ? ' (you)' : ''}
                    <small>{item.email}</small>
                  </span>
                </label>
              ))}
              {!settings.items.length && <p>No account users have access to this newsletter.</p>}
            </fieldset>
          </>
        )}
      </div>
      <footer>
        <button disabled={busy} onClick={close}>
          Cancel
        </button>
        <button
          className="nl-primary"
          disabled={busy || loading || !settings?.editable}
          onClick={() => void save()}
        >
          {busy ? 'Saving…' : 'Save'}
        </button>
      </footer>
    </Modal>
  );
}

import { useEffect, useRef, useState } from 'react';
import {
  newsletterVideoSource,
  type NewsletterBlock,
  type NewsletterStyle,
} from '@capiro/shared/newsletter';
import { newsletterError, type NewsletterClient, type NewsletterVideoThumbnail } from './api.js';
import { Check, ColorField, NumberField, SelectField, TextField } from './controls.js';
import { NewsletterImageReplaceMenu } from './NewsletterImageReplaceMenu.js';
import { NewsletterImageDescription } from './NewsletterImageControls.js';
import { newsletterBundledImageUrl } from '@capiro/shared/newsletter-render';

const corners = [
  ['radiusTopLeft', 'Top left'],
  ['radiusTopRight', 'Top right'],
  ['radiusBottomLeft', 'Bottom left'],
  ['radiusBottomRight', 'Bottom right'],
] as const;
export function NewsletterVideoDesign({
  block,
  api,
  documentId,
  onChange,
  onBeforeLoad,
  onThumbnail,
  onUpload,
  onBrowse,
  onAdvanced,
  uploading,
  disabled,
  altAvailable,
  altReason,
  onAltGenerated,
}: {
  block: NewsletterBlock;
  api: NewsletterClient;
  documentId: string;
  onChange: (edit: (block: NewsletterBlock) => void) => void;
  onBeforeLoad: () => Promise<unknown>;
  onThumbnail: (
    result: NewsletterVideoThumbnail,
    source: { url: string; imageUrl: string },
  ) => boolean;
  onUpload: () => void;
  onBrowse: () => void;
  onAdvanced: () => void;
  uploading: boolean;
  disabled: boolean;
  altAvailable: boolean;
  altReason?: string | null;
  onAltGenerated: (text: string, source: { imageUrl: string; alt: string }) => boolean;
}) {
  const [help, setHelp] = useState(false),
    [busy, setBusy] = useState(false),
    [error, setError] = useState(''),
    [retry, setRetry] = useState(0);
  const handlers = useRef({ onBeforeLoad, onThumbnail });
  handlers.current = { onBeforeLoad, onThumbnail };
  const automatic = (block.video?.thumbnail || (block.imageUrl ? 'custom' : 'auto')) === 'auto';
  const source = newsletterVideoSource(block.url),
    resolved = newsletterVideoSource(block.video?.sourceUrl || '');
  const key = source?.url || '',
    resolvedKey = resolved?.url || '',
    previousImage = block.imageUrl;
  useEffect(() => {
    let canceled = false;
    setError('');
    setBusy(false);
    if (!automatic || !key || (resolvedKey === key && previousImage)) return;
    const timer = window.setTimeout(() => {
      setBusy(true);
      void (async () => {
        try {
          await handlers.current.onBeforeLoad();
          if (canceled) return;
          const result = await api.videoThumbnail(documentId, key);
          if (canceled) return;
          if (!handlers.current.onThumbnail(result, { url: key, imageUrl: previousImage }))
            setError('The video changed. Your thumbnail is available in Content Studio.');
        } catch (error) {
          if (!canceled) setError(newsletterError(error));
        } finally {
          if (!canceled) setBusy(false);
        }
      })();
    }, 600);
    return () => {
      canceled = true;
      window.clearTimeout(timer);
    };
  }, [api, documentId, block.id, automatic, key, resolvedKey, previousImage, retry]);
  const style = block.style;
  const setStyle = <K extends keyof NewsletterStyle>(key: K, value: NewsletterStyle[K]) =>
    onChange((draft) => {
      draft.style[key] = value;
    });
  const splitCorners = corners.some(([key]) => style[key] !== undefined);
  const custom = (action: () => void) => {
    onChange((draft) => {
      draft.video = { ...draft.video, thumbnail: 'custom', sourceUrl: draft.url };
    });
    action();
  };
  return (
    <section aria-label="Video design">
      <div className="nl-flex">
        <h3>Video URL</h3>
        <button
          type="button"
          aria-label="Video URL info"
          aria-expanded={help}
          onClick={() => setHelp((v) => !v)}
        >
          Info
        </button>
      </div>
      <TextField
        label="URL"
        value={block.url}
        placeholder="https://www.example.com"
        onChange={(url) =>
          onChange((draft) => {
            draft.url = url;
            draft.linkType = 'web';
          })
        }
      />
      {help && (
        <p role="status">
          The thumbnail opens the video in a separate browser window when a recipient clicks it.{' '}
          <a
            href="https://mailchimp.com/help/use-video-content-blocks-new-builder/"
            target="_blank"
            rel="noopener noreferrer"
          >
            Learn more
          </a>
        </p>
      )}
      <p>
        YouTube and Vimeo links generate a thumbnail automatically. The thumbnail links to this URL.
      </p>
      {!block.imageUrl && (
        <>
          <h3>Upload a custom video thumbnail</h3>
          <p>Accepts PNG, JPG and GIF files up to 10 MB.</p>
        </>
      )}
      {block.imageUrl && (
        <div className="nl-image-preview">
          <img src={newsletterBundledImageUrl(block.imageUrl)} alt={block.alt} />
        </div>
      )}
      <div className="nl-flex">
        <NewsletterImageReplaceMenu
          label={block.imageUrl ? 'Replace' : 'Add'}
          disabled={uploading || disabled}
          canEdit={!!block.imageUrl}
          onUpload={() => custom(onUpload)}
          onBrowse={() => custom(onBrowse)}
          onAdvanced={() => custom(onAdvanced)}
        />
        <button disabled={uploading || disabled} onClick={() => custom(onUpload)}>
          Choose file
        </button>
        {!automatic && source && (
          <button
            disabled={disabled || uploading}
            onClick={() =>
              onChange((draft) => {
                draft.video = { ...draft.video, thumbnail: 'auto', sourceUrl: '' };
              })
            }
          >
            Use automatic thumbnail
          </button>
        )}
      </div>
      {busy && <p role="status">Generating video thumbnail…</p>}
      {uploading && <p role="status">Uploading thumbnail…</p>}
      {error && (
        <div role="alert">
          <p>{error}</p>
          <button disabled={busy || disabled} onClick={() => setRetry((v) => v + 1)}>
            Retry thumbnail
          </button>
          <p>Choose a custom thumbnail if this video is unavailable.</p>
        </div>
      )}
      <NewsletterImageDescription
        api={api}
        documentId={documentId}
        imageUrl={block.imageUrl}
        alt={block.alt}
        available={altAvailable}
        reason={altReason}
        onChange={(alt) =>
          onChange((draft) => {
            draft.alt = alt;
          })
        }
        onGenerated={onAltGenerated}
      />
      <ColorField
        label="Block background color"
        value={style.background || 'transparent'}
        onChange={(value) => setStyle('background', value)}
      />
      <SelectField
        label="Border"
        value={style.borderStyle || 'none'}
        values={[
          'none',
          'solid',
          'dashed',
          'dotted',
          'double',
          'inset',
          'outset',
          'groove',
          'ridge',
        ]}
        onChange={(value) => setStyle('borderStyle', value)}
      />
      {style.borderStyle && style.borderStyle !== 'none' && (
        <div className="nl-grid2">
          <NumberField
            label="Border width"
            value={style.borderWidth ?? 1}
            max={30}
            onChange={(value) => setStyle('borderWidth', value)}
          />
          <ColorField
            label="Border color"
            value={style.borderColor || '#777777'}
            onChange={(value) => setStyle('borderColor', value)}
          />
        </div>
      )}
      <h3>Rounded corners</h3>
      {splitCorners ? (
        <div className="nl-grid2">
          {corners.map(([key, label]) => (
            <NumberField
              key={key}
              label={label}
              value={style[key] ?? style.radius ?? 0}
              max={1000}
              onChange={(value) => setStyle(key, value)}
            />
          ))}
        </div>
      ) : (
        <NumberField
          label="Rounded corners"
          value={style.radius ?? 0}
          max={1000}
          onChange={(value) => setStyle('radius', value)}
        />
      )}
      <button
        type="button"
        aria-pressed={!splitCorners}
        onClick={() =>
          onChange((draft) => {
            if (splitCorners) {
              draft.style.radius = draft.style.radiusTopLeft ?? draft.style.radius ?? 0;
              for (const [key] of corners) delete draft.style[key];
            } else {
              for (const [key] of corners) draft.style[key] = draft.style.radius ?? 0;
            }
          })
        }
      >
        Apply to all sides
      </button>
      <SelectField
        label="Alignment"
        value={style.align || 'center'}
        values={['left', 'center', 'right']}
        onChange={(value) => setStyle('align', value)}
      />
      <h3>Padding</h3>
      {block.video?.paddingLinked ? (
        <NumberField
          label="Padding"
          value={style.paddingTop ?? 12}
          max={1000}
          onChange={(value) =>
            onChange((draft) => {
              Object.assign(draft.style, {
                paddingTop: value,
                paddingBottom: value,
                paddingLeft: value,
                paddingRight: value,
              });
            })
          }
        />
      ) : (
        <div className="nl-grid2">
          {(['Top', 'Bottom', 'Left', 'Right'] as const).map((side) => {
            const key = `padding${side}` as
              'paddingTop' | 'paddingBottom' | 'paddingLeft' | 'paddingRight';
            return (
              <NumberField
                key={key}
                label={`Padding ${side.toLowerCase()}`}
                value={style[key] ?? (['Left', 'Right'].includes(side) ? 24 : 12)}
                max={1000}
                onChange={(value) => setStyle(key, value)}
              />
            );
          })}
        </div>
      )}
      <Check
        label="Apply to all sides"
        checked={!!block.video?.paddingLinked}
        onChange={(linked) =>
          onChange((draft) => {
            draft.video = {
              ...draft.video,
              thumbnail: draft.video?.thumbnail || (draft.imageUrl ? 'custom' : 'auto'),
              sourceUrl: draft.video?.sourceUrl || draft.url,
              paddingLinked: linked,
            };
            if (!linked) return;
            const value = draft.style.paddingTop ?? 12;
            Object.assign(draft.style, {
              paddingTop: value,
              paddingBottom: value,
              paddingLeft: value,
              paddingRight: value,
            });
          })
        }
      />
    </section>
  );
}

import { useEffect, useId, useRef, useState } from 'react';
import { newsletterSafeUrl } from '@capiro/shared/newsletter-render';

function videoUrl(value: string) {
  const safe = newsletterSafeUrl(value);
  return /^https?:\/\//i.test(safe) ? safe : '';
}
/** Like the source builder, edits apply live; Save dismisses the field. */
export function NewsletterVideoUrlControl({
  url,
  onChange,
  disabled = false,
}: {
  url: string;
  onChange: (url: string) => void;
  disabled?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null),
    trigger = useRef<HTMLButtonElement>(null),
    field = useRef<HTMLInputElement>(null);
  const restoreFocus = useRef(false);
  const id = useId(),
    safe = videoUrl(url);
  const close = () => {
    restoreFocus.current = true;
    setOpen(false);
  };
  useEffect(() => {
    if (!open && restoreFocus.current) {
      restoreFocus.current = false;
      trigger.current?.focus();
    }
  }, [open]);
  useEffect(() => {
    if (!open) return;
    field.current?.focus();
    const outside = (event: PointerEvent) => {
      if (!root.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener('pointerdown', outside);
    return () => document.removeEventListener('pointerdown', outside);
  }, [open]);
  return (
    <div
      ref={root}
      className="nl-video-url-actions"
      role="toolbar"
      aria-label="Video URL actions"
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => {
        if (open && event.key === 'Escape') {
          event.preventDefault();
          event.stopPropagation();
          close();
        }
      }}
    >
      {open ? (
        <div role="group" aria-label="Edit video URL" className="nl-video-url-field">
          <label htmlFor={id}>Video URL</label>
          <input
            id={id}
            ref={field}
            value={url}
            placeholder="Please enter a URL"
            disabled={disabled}
            onChange={(event) => onChange(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && safe && !disabled) {
                event.preventDefault();
                close();
              }
            }}
          />
          {url ? (
            <button
              type="button"
              disabled={disabled}
              onClick={() => {
                onChange('');
                close();
              }}
            >
              Remove URL
            </button>
          ) : (
            <button type="button" onClick={() => close()}>
              Cancel
            </button>
          )}
          <button type="button" disabled={!safe || disabled} onClick={() => close()}>
            Save
          </button>
        </div>
      ) : (
        <>
          <button
            ref={trigger}
            type="button"
            disabled={disabled}
            aria-expanded={false}
            onClick={() => setOpen(true)}
          >
            {url ? 'Edit URL' : 'Add URL'}
          </button>
          {!!safe && (
            <a href={safe} target="_blank" rel="noopener noreferrer">
              Preview link
            </a>
          )}
        </>
      )}
    </div>
  );
}

import { useMemo } from 'react';
import type { AxiosInstance } from 'axios';
import { useApi } from '../../../../lib/use-api.js';
import type {
  NewsletterCampaign,
  NewsletterCapabilities,
  NewsletterComment,
  NewsletterLibraryItem,
  NewsletterStage,
  NewsletterCheck,
  NewsletterBrandKit,
  NewsletterFont,
  NewsletterSavedSurvey,
  NewsletterSurveyDefinition,
} from '@capiro/shared/newsletter';
export const NEWSLETTER_BASE = '/workspace-api/newsletters';
export function createNewsletterClient(api: AxiosInstance) {
  const d = (id: string) => `${NEWSLETTER_BASE}/documents/${encodeURIComponent(id)}`;
  return {
    brandKit: async () => (await api.get<NewsletterBrandKit>(`${NEWSLETTER_BASE}/brand-kit`)).data,
    saveBrandKit: async (kit: NewsletterBrandKit) =>
      (await api.patch<NewsletterBrandKit>(`${NEWSLETTER_BASE}/brand-kit`, kit)).data,
    uploadFont: async (file: File) => {
      const form = new FormData();
      form.append('file', file);
      return (await api.post<NewsletterFont>(`${NEWSLETTER_BASE}/brand-kit/fonts`, form)).data;
    },
    list: async () =>
      (await api.get<{ items: NewsletterCampaign[] }>(`${NEWSLETTER_BASE}/documents`)).data.items,
    create: async (templateId?: string) =>
      (await api.post<NewsletterCampaign>(`${NEWSLETTER_BASE}/documents`, { templateId })).data,
    get: async (id: string) => (await api.get<NewsletterCampaign>(d(id))).data,
    save: async (document: NewsletterCampaign) =>
      (
        await api.patch<NewsletterCampaign>(d(document.id), {
          revision: document.revision,
          name: document.name,
          config: document.config,
          design: document.design,
        })
      ).data,
    stage: async (id: string, revision: number) =>
      (await api.post<NewsletterStage>(`${d(id)}/stage`, { revision })).data,
    surveys: async (id: string) =>
      (await api.get<{ items: NewsletterSavedSurvey[] }>(`${d(id)}/surveys`)).data.items,
    saveSurvey: async (
      id: string,
      input: {
        name: string;
        definition: NewsletterSurveyDefinition;
        id?: string;
        revision?: number;
      },
    ) => (await api.post<NewsletterSavedSurvey>(`${d(id)}/surveys`, input)).data,
    preview: async (id: string, liveMergeTags = false) =>
      (
        await api.post<{ html: string; plainText: string; checks: NewsletterCheck[] }>(
          `${d(id)}/preview`,
          { liveMergeTags },
        )
      ).data,
    capabilities: async () =>
      (await api.get<NewsletterCapabilities>(`${NEWSLETTER_BASE}/capabilities`)).data,
    library: async (kind: 'section' | 'template') =>
      (await api.get<{ items: NewsletterLibraryItem[] }>(`${NEWSLETTER_BASE}/library/${kind}`)).data
        .items,
    saveLibrary: async (id: string, name: string, folder: string, sectionId?: string) =>
      (await api.post<NewsletterLibraryItem>(`${d(id)}/library`, { name, folder, sectionId })).data,
    updateLibrary: async (id: string, name: string, folder: string) =>
      (await api.patch(`${NEWSLETTER_BASE}/library/items/${id}`, { name, folder })).data,
    removeLibrary: async (id: string) =>
      (await api.delete(`${NEWSLETTER_BASE}/library/items/${id}`)).data,
    comments: async (id: string) =>
      (await api.get<{ items: NewsletterComment[] }>(`${d(id)}/comments`)).data.items,
    review: async (id: string) =>
      (
        await api.get<{
          id: string;
          name: string;
          role: string;
          html: string;
          comments: NewsletterComment[];
        }>(`${d(id)}/review`)
      ).data,
    reviewers: async (id: string) =>
      (await api.get<NewsletterReviewers>(`${d(id)}/reviewers`)).data,
    invite: async (id: string, userId: string, role: string) =>
      (await api.post<NewsletterReviewers>(`${d(id)}/reviewers`, { userId, role })).data,
