export function prebuiltSection(category: string, variant = 0): NewsletterSection {
  const b = createNewsletterBlock;
  const h = b('heading', {
    text:
      category === 'Hero'
        ? 'This week in policy'
        : category === 'Reviews'
          ? 'What our clients are saying'
          : `${category} headline`,
    headingLevel: category === 'Hero' ? 1 : 2,
  });
  const p = b('paragraph', {
    text: 'Add a sourced update, explain the implications for your client, and identify the next step.',
  });
  const image = b('image', {
    imageUrl: '/newsletter/policy-desk.svg',
    alt: 'Policy briefing illustration',
  });
  const button = b('button', { text: 'Learn more', url: 'https://www.congress.gov/' });
  const column = (left: NewsletterBlock[], right: NewsletterBlock[]) =>
    b('columns', { columns: [left, right], ratio: variant % 2 ? '1:2' : '2' });
  const blocks =
    category === 'Header'
      ? [b('logo', { text: 'YOUR FIRM', style: { bold: true, fontSize: 32 } }), b('divider')]
      : category === 'Footer'
        ? [b('social', { items: [{ label: 'WEBSITE', url: 'https://capiro.ai/' }] }), b('footer')]
        : category === 'Image gallery'
          ? [column([image], [cloneNewsletterBlocks([image])[0]!])]
          : category === 'Bill updates'
            ? [
                h,
                column(
                  [
                    b('heading', { text: 'Bill status', headingLevel: 3 }),
                    b('paragraph', { text: 'Add the bill number, latest action, and a source link.' }),
                  ],
                  [
                    b('heading', { text: 'Client implications', headingLevel: 3 }),
                    b('paragraph', { text: 'Explain the impact, upcoming milestones, and next steps.' }),
                  ],
                ),
              ]
            : category === 'Features'
              ? [h, column([p], [cloneNewsletterBlocks([p])[0]!])]
              : variant % 2
                ? [column([h, p, button], [image])]
                : [h, image, p, button];
  return createNewsletterSection(category, blocks);
}
export function cloneSection(section: NewsletterSection) {
  return {
    ...structuredClone(section),
    id: newsletterId(),
    blocks: cloneNewsletterBlocks(section.blocks),
  };
}
/** Client paste/display hygiene. The API validates again before saving/rendering. */
/** Bake crops into raster bytes so email clients do not need object-fit support. */
export async function rasterizeNewsletterCrop(
  url: string,
  crop: NonNullable<NewsletterBlock['crop']>,
): Promise<File> {
  const source = new Image();
  source.crossOrigin = 'anonymous';
  await new Promise<void>((resolve, reject) => {
    source.onload = () => resolve();
    source.onerror = () =>
      reject(
        new Error('This image cannot be edited. Upload a copy to Content studio and try again.'),
      );
    source.src = url;
  });
  const ratio = crop.width / crop.height;
  const width = Math.min(source.naturalWidth, source.naturalHeight * ratio);
  const height = Math.min(source.naturalHeight, source.naturalWidth / ratio);
  const canvas = document.createElement('canvas');
  const scale = Math.min(1, 2048 / Math.max(width, height));
  canvas.width = Math.max(1, Math.round(width * scale));
  canvas.height = Math.max(1, Math.round(height * scale));
  const context = canvas.getContext('2d');
  if (!context) throw new Error('Image editing is unavailable in this browser.');
  context.drawImage(
    source,
    ((source.naturalWidth - width) * crop.x) / 100,
    ((source.naturalHeight - height) * crop.y) / 100,
    width,
    height,
    0,
    0,
    canvas.width,
    canvas.height,
  );
  const blob = await new Promise<Blob>((resolve, reject) => {
    try {
      canvas.toBlob(
        (value) => (value ? resolve(value) : reject(new Error('The image could not be saved.'))),
        'image/png',
      );
    } catch {
      reject(new Error('Upload a copy of this image to Content studio before editing it.'));
    }
  });
  return new File([blob], 'newsletter-crop.png', { type: 'image/png' });
}
export function sanitizeNewsletterMarkup(html: string) {
  const parsed = new DOMParser().parseFromString(html, 'text/html');
  const allowed = new Set([
    'P',
    'BR',
    'STRONG',
    'B',
    'EM',
    'I',
    'U',
    'S',
    'SPAN',
    'DIV',
    'A',
    'H1',
    'H2',
    'H3',
    'H4',
    'UL',
    'OL',
    'LI',
    'TABLE',
    'THEAD',
    'TBODY',
    'TR',
    'TD',
    'TH',
    'IMG',
    'HR',
    'BLOCKQUOTE',
    'PRE',
    'CODE',
  ]);
  parsed
    .querySelectorAll('script,style,iframe,object,embed,svg,math,form,link,meta,base')
    .forEach((el) => el.remove());
  for (const el of Array.from(parsed.body.querySelectorAll('*'))) {
    if (!allowed.has(el.tagName)) {
      el.replaceWith(...Array.from(el.childNodes));
      continue;
    }
    for (const attribute of Array.from(el.attributes)) {
      const name = attribute.name;
      const value = attribute.value;
      if (name === 'id' && el.tagName === 'A' && /^[a-z\d_-]{1,100}$/i.test(value)) continue;
      else if (name === 'href' && el.tagName === 'A') {
        const safe = newsletterSafeUrl(value);
        if (safe) el.setAttribute(name, safe);
        else el.removeAttribute(name);
      } else if (name === 'src' && el.tagName === 'IMG') {
        const safe = newsletterSafeUrl(value, true);
        if (safe) el.setAttribute(name, safe);
        else el.removeAttribute(name);
      } else if (
        (name === 'alt' && el.tagName === 'IMG') ||
        (['width', 'height', 'colspan', 'rowspan'].includes(name) && /^\d{1,4}$/.test(value))
      )
        continue;
      else if (name === 'style') {
        const style = (el as HTMLElement).style;
        const keep: string[] = [];
        for (const key of [
          'color',
          'background-color',
          'font-family',
          'font-size',
          'font-weight',
          'font-style',
          'text-align',
          'text-decoration',
          'line-height',
        ]) {
          const entry = style.getPropertyValue(key);
          if (/^[#a-z0-9 .,\-"']{1,100}$/i.test(entry) && !/url|expression|var\(/i.test(entry))
            keep.push(`${key}:${entry}`);
        }
        el.setAttribute('style', keep.join(';'));
      } else el.removeAttribute(name);
    }
    if (el.tagName === 'A') el.setAttribute('rel', 'noopener noreferrer');
  }
  return parsed.body.innerHTML;
}

import { findNewsletterBlock, type NewsletterCampaign } from '@capiro/shared/newsletter';
import {
  newsletterMergeText,
  newsletterSafeUrl,
  renderNewsletterDesign,
} from '@capiro/shared/newsletter-render';
import { sanitizeNewsletterMarkup } from './model.js';

export interface NewsletterReviewLink {
  key: string;
  blockId: string;
  index: number;
  label: string;
  url: string;
  valid: boolean;
  web: boolean;
  managed: boolean;
  source: 'url' | 'item' | 'html' | 'app' | 'managed';
  originalHtml?: string;
}

/** These identifiers come from renderer wrappers, not custom HTML attributes. */
export function newsletterLinkBlock(anchor: Element): HTMLElement | null {
  for (let node = anchor.parentElement; node; node = node.parentElement)
    if (node.id && node.classList.contains(`nl-block-${node.id}`)) return node;
  return null;
}
export function newsletterBlockLinks(wrapper: Element): Element[] {
  return Array.from(wrapper.querySelectorAll('a')).filter(
    (anchor) =>
      newsletterLinkBlock(anchor) === wrapper &&
      (anchor.hasAttribute('href') || !anchor.hasAttribute('id')),
  );
}

/** Keep raw recipient tags even when the displayed preview has live sample values. */
export function newsletterReviewLinks(document: NewsletterCampaign): NewsletterReviewLink[] {
  const html = renderNewsletterDesign(document.design, document.config, {
    sanitizeHtml: sanitizeNewsletterMarkup,
    editor: true,
  });
  const parsed = new DOMParser().parseFromString(html, 'text/html');
  return Array.from(parsed.querySelectorAll('a')).flatMap((anchor) => {
    const wrapper = newsletterLinkBlock(anchor);
    const block = wrapper && findNewsletterBlock(document.design, wrapper.id);
    if (!block || !wrapper) return [];
    const index = newsletterBlockLinks(wrapper).indexOf(anchor);
    if (index < 0) return [];
    let source: NewsletterReviewLink['source'] = 'managed';
    let url = anchor.getAttribute('href') || '';
    if (block.kind === 'apps' && block.app?.sourceUrl) {
      source = 'app';
      url = block.app.sourceUrl;
    } else if (['heading', 'paragraph', 'code'].includes(block.kind) && block.html) {
      source = 'html';
    } else if (['button', 'video', 'image', 'logo'].includes(block.kind)) {
      source = 'url';
      url = block.url;
    } else if (block.kind === 'social' && block.social?.mode === 'share') {
      source = 'managed';
    } else if (['social', 'product', 'product-rec'].includes(block.kind)) {
      source = 'item';
      url = block.items[index]?.url || '';
    }
    const safe = newsletterSafeUrl(url);
    const merge = source !== 'app' && /\*\|[^|]+\|\*/.test(url);
    const knownMerge =
      source === 'app' ||
      !/\*\|[^|]+\|\*/.test(newsletterMergeText(url, document.config, { liveMergeTags: true }));
    const valid =
      !!safe && knownMerge && (!url.startsWith('#') || !!parsed.getElementById(url.slice(1)));
    return [
      {
        key: `${block.id}:${index}:${url}`,
        blockId: block.id,
        index,
        label:
          anchor.textContent?.trim() ||
          anchor.querySelector('img')?.getAttribute('alt') ||
          'Linked image',
        url,
        valid,
        web: !!safe && !merge && /^https?:\/\//i.test(safe),
        managed: source === 'managed' || (merge && !!safe && knownMerge),
        source,
        ...(source === 'html' ? { originalHtml: block.html } : {}),
      },
    ];
  });
}

/** A failed save may be retried against the same local edit, never another target. */
export function editNewsletterReviewLink(
  document: NewsletterCampaign,
  link: NewsletterReviewLink,
  value: string,
): boolean {
  const safe = newsletterSafeUrl(value);
  if (!safe)
    throw new Error(
      'Enter a valid web, email, telephone, anchor or supported merge-tag destination.',
    );
  const block = findNewsletterBlock(document.design, link.blockId);
  if (!block || link.source === 'managed')
    throw new Error('This destination is managed in Outreach.');
  const changed = () => new Error('The link changed. Reopen its details before editing it.');
  if (link.source === 'app') {
    if (block.kind !== 'apps' || !block.app) throw changed();
    let parsed: URL;
    try {
      parsed = new URL(safe);
    } catch {
      throw new Error('Link previews require a public HTTPS URL.');
    }
    if (parsed.protocol !== 'https:' || parsed.username || parsed.password)
      throw new Error('Link previews require a public HTTPS URL without embedded credentials.');
    if (block.app.sourceUrl === safe) return false;
    if (block.app.sourceUrl !== link.url) throw changed();
    block.app.sourceUrl = safe;
    return true;
  }
  if (link.source === 'html') {
    if (
      !['heading', 'paragraph', 'code', 'apps'].includes(block.kind) ||
      link.originalHtml === undefined
    )
      throw changed();
    const fragment = new DOMParser().parseFromString(
      sanitizeNewsletterMarkup(link.originalHtml),
      'text/html',
    );
    const anchors = Array.from(fragment.querySelectorAll('a')).filter(
      (a) => a.hasAttribute('href') || !a.hasAttribute('id'),
    );
    const anchor = anchors[link.index];
    if (!anchor || (anchor.getAttribute('href') || '') !== link.url) throw changed();
    anchor.setAttribute('href', safe);
    const next = sanitizeNewsletterMarkup(fragment.body.innerHTML);
    if (block.html === next) return false;
    if (block.html !== link.originalHtml) throw changed();
    block.html = next;
    return true;
  }
  if (link.source === 'url') {
    if (!['button', 'video', 'image', 'logo'].includes(block.kind)) throw changed();
    if (block.url === safe) return false;
    if (block.url !== link.url) throw changed();
    block.url = safe;
    return true;
  }
  if (!['social', 'product', 'product-rec'].includes(block.kind)) throw changed();
  const item = block.items[link.index];
  if (!item) throw changed();
  if (item.url === safe) return false;
  if (item.url !== link.url) throw changed();
  item.url = safe;
  return true;
}

