  const [notetakerTargetMeetingId, setNotetakerTargetMeetingId] = useState<string | null>(null);
  // Meeting whose saved notes are shown in the quick-view modal (list-row action).
  const [notesModalMeetingId, setNotesModalMeetingId] = useState<string | null>(null);
  const [reportMeetingRow, setReportMeetingRow] = useState<EngagementReportRow | null>(null);
  const [editingPrep, setEditingPrep] = useState<{ meeting: Meeting; prep: MeetingPrep } | null>(
    null,
  );
  const [meetingForm] = Form.useForm<MeetingFormValues>();
  const [taskForm] = Form.useForm<TaskFormValues>();
  const [prepForm] = Form.useForm<PrepFormValues>();
  const [targetOfficeForm] = Form.useForm<TargetOfficeFormValues>();
  const targetManualOnly = Form.useWatch('manualOnly', targetOfficeForm) === true;
  const [notetakerForm] = Form.useForm<NotetakerFormValues>();
  // Live checkbox state so the consent modal's OK button stays disabled until
  // both required acknowledgements are checked.
  const notetakerAuthorized = Form.useWatch('authorizedToRecord', notetakerForm);
  const notetakerNotified = Form.useWatch('allPartiesWillBeNotified', notetakerForm);
  const syncingFromUrlRef = useRef(false);
  const lastProcessedUrlRef = useRef<string>('');

  useEffect(() => {
    // Only sync URL → state when the URL itself has changed since we last saw it.
    // Without this guard, this effect re-runs whenever activeEngagementTab (or any
    // other dep) updates from a user click, and because the URL hasn't caught up
    // yet, it would clobber the new state back to the URL's stale value before
    // the navigate effect below ever runs. Net result: tab clicks would revert.
    const urlKey = `${location.pathname}?${searchParams.toString()}`;
    if (lastProcessedUrlRef.current === urlKey) return;
    lastProcessedUrlRef.current = urlKey;

    const segments = location.pathname.split('/').filter(Boolean);
    const rawSection = segments[0] === 'engagement' ? (segments[1] ?? 'meetings') : null;
    const isMeetingLibraryRoute = rawSection === 'meeting-library';
    // Overview is a first-class tab. Meeting Library is a first-class
    // route, but it still belongs to the shared Meetings tab.
    const section = isMeetingLibraryRoute ? 'meetings' : rawSection;
    const nextTab =
      section && ['overview', 'meetings', 'outreach', 'reports'].includes(section)
        ? (section as 'overview' | 'meetings' | 'outreach' | 'reports')
        : null;
    const nextMeetingId =
      nextTab === 'meetings' && !isMeetingLibraryRoute && segments[2]
        ? decodeURIComponent(segments[2])
        : null;
    const nextDetail = searchParams.get('detail');
    // Accepts the legacy `view=calendar` alias and normalizes it to 'month'
    // (spec Phase 2 §2a1 / edge case 4) — the stored state and every future
    // URL write only ever use the canonical 'month'.
    const nextView = parseMeetingViewMode(searchParams.get('view'));
    const nextFrom = searchParams.get('from');
    const nextTo = searchParams.get('to');
    const nextDate = searchParams.get('date');
    const nextPeriod = searchParams.get('period');
    const currentCursorKey = inputValueFromDate(meetingCursor);

    const hasUrlStateChange =
      (nextTab && nextTab !== activeEngagementTab) ||
      (nextTab === 'meetings' && nextMeetingId !== selectedMeetingId) ||
      (nextTab === 'meetings' &&
        meetingsV2Enabled &&
        isMeetingLibraryRoute !== meetingsLibraryOpen) ||
      (nextTab === 'meetings' && nextDetail && nextDetail !== meetingDetailTab) ||
      (nextTab === 'meetings' && nextView && nextView !== meetingViewMode) ||
      (nextTab === 'meetings' && nextFrom && nextFrom !== rangeStart) ||
      (nextTab === 'meetings' && nextTo && nextTo !== rangeEnd) ||
      // Meetings v2's cursor date — read `date=` when present, else fall back
      // to a legacy `from=` link opened while v2 is active (spec §2a4).
      (nextTab === 'meetings' &&
        meetingsV2Enabled &&
        Boolean(nextDate) &&
        nextDate !== currentCursorKey) ||
      (nextTab === 'meetings' &&
        meetingsV2Enabled &&
        !nextDate &&
        Boolean(nextFrom) &&
        nextFrom !== currentCursorKey) ||
      (nextTab === 'reports' &&
        ['current', 'previous', 'all'].includes(nextPeriod ?? '') &&
        nextPeriod !== reportPeriod);

    if (!hasUrlStateChange) return;
    syncingFromUrlRef.current = true;

    if (nextTab) {
      setActiveEngagementTab(nextTab);
    }
    if (nextTab === 'meetings') {
      setSelectedMeetingId(nextMeetingId);
      if (meetingsV2Enabled) setMeetingsLibraryOpen(isMeetingLibraryRoute);
      if (nextDetail) setMeetingDetailTab(nextDetail);
      if (nextView) setMeetingViewMode(nextView);
      if (nextFrom) setRangeStart(nextFrom);
      if (nextTo) setRangeEnd(nextTo);
      if (meetingsV2Enabled) {
        if (nextDate) setMeetingCursor(localDateFromInput(nextDate));
        else if (nextFrom) setMeetingCursor(localDateFromInput(nextFrom));
      }
    }
    if (nextTab === 'reports' && ['current', 'previous', 'all'].includes(nextPeriod ?? '')) {
      setReportPeriod(nextPeriod as ReportPeriod);
    }
  }, [
    activeEngagementTab,
    location.pathname,
    meetingCursor,
    meetingDetailTab,
    meetingsLibraryOpen,
    meetingsV2Enabled,
    meetingViewMode,
    rangeEnd,
    rangeStart,
    reportPeriod,
    searchParams,
    selectedMeetingId,
  ]);

  useEffect(() => {
    if (syncingFromUrlRef.current) {
      syncingFromUrlRef.current = false;
      return;
    }

    const nextParams = new URLSearchParams();
    // Overview is a first-class tab. Meetings is the default landing tab.
    let nextPath = '/engagement/meetings';

    if (activeEngagementTab === 'overview') {
      nextPath = '/engagement/overview';
    } else if (activeEngagementTab === 'meetings') {
      if (meetingsV2Enabled && meetingsLibraryOpen) {
        nextPath = '/engagement/meeting-library';
      } else {
        nextPath = selectedMeetingId
          ? `/engagement/meetings/${encodeURIComponent(selectedMeetingId)}`
          : '/engagement/meetings';
        if (meetingDetailTab && meetingDetailTab !== 'prep')
          nextParams.set('detail', meetingDetailTab);
        // Day is the default view, so only serialize the non-default views.
        if (meetingViewMode !== 'day') nextParams.set('view', meetingViewMode);
        if (meetingsV2Enabled) {
          // Meetings v2 pivots on a single cursor date for every mode
          // (day/month/list) — always serialize it, and never write the legacy
          // from/to pair (spec §2a4). The URL writer only ever emits the
          // canonical 'month', never 'calendar' (edge case 4).
          nextParams.set('date', inputValueFromDate(meetingCursor));
        } else {
          if (rangeStart) nextParams.set('from', rangeStart);
          if (rangeEnd) nextParams.set('to', rangeEnd);
        }
      }
    } else if (activeEngagementTab === 'outreach') {
      nextPath = location.pathname.startsWith('/engagement/outreach')
        ? location.pathname
        : '/engagement/outreach';
      // The staged hearing is owned by Outreach's review route. Keep its
      // identity through this host's tab synchronization and page reloads.
      if (searchParams.get('source') === 'legiwatch') {
        for (const key of ['source', 'hearingId', 'client', 'contextId']) {
          const value = searchParams.get(key);
          if (value) nextParams.set(key, value);
        }
      }
    } else if (activeEngagementTab === 'reports') {
      nextPath = '/engagement/reports';
      if (reportPeriod !== 'current') nextParams.set('period', reportPeriod);
    }

    const nextSearch = nextParams.toString();
    const currentSearch = searchParams.toString();
    if (location.pathname === nextPath && currentSearch === nextSearch) return;

    // Pre-record the URL we're about to write so the URL→state effect skips it
    // when location updates (state already reflects the change).
    lastProcessedUrlRef.current = `${nextPath}?${nextSearch}`;

    navigate(
      {
        pathname: nextPath,
        search: nextSearch ? `?${nextSearch}` : '',
      },
      { replace: true },
    );
  }, [
    activeEngagementTab,
    location.pathname,
    meetingCursor,
    meetingDetailTab,
    meetingsLibraryOpen,
    meetingsV2Enabled,
    meetingViewMode,
    navigate,
    rangeEnd,
    rangeStart,
    reportPeriod,
    searchParams,
    selectedMeetingId,
  ]);

  const meetingWindow = useMemo(
    () => dateRangeWindow(rangeStart, rangeEnd, historyBatch),
    [historyBatch, rangeEnd, rangeStart],
  );
  const hasCustomMeetingRange =
    rangeStart !== defaultRange.start || rangeEnd !== defaultRange.end || historyBatch > 0;

  const clients = useQuery<Client[]>({
    queryKey: ['clients'],
    queryFn: async () => (await api.get<Client[]>('/api/clients')).data,
  });
  const activeClients = useMemo(
    () =>
      (clients.data ?? [])
        .filter((client) => client.status !== 'archived')
        .sort((left, right) => left.name.localeCompare(right.name)),
    [clients.data],
  );
  const clientSelectOptions = useMemo(
    () => activeClients.map((client) => ({ value: client.id, label: client.name })),
    [activeClients],
  );

  const capabilities = useQuery<EngagementCapabilities>({
    queryKey: ['engagement-capabilities'],
    queryFn: async () =>
      (await api.get<EngagementCapabilities>('/api/engagement/capabilities')).data,
  });

  // Integrations query — used to populate the "Sync now" button on the Meetings tab.
  // The button triggers a manual calendar+mail sync for each connected integration.
  const integrations = useQuery<
    Array<{ id: string; provider: string; status: string; accountEmail?: string | null }>
  >({
    queryKey: ['engagement-integrations'],
    queryFn: async () => (await api.get('/api/engagement/integrations')).data,
    staleTime: 60_000,
  });
  const connectedIntegrations = useMemo(
    () => (integrations.data ?? []).filter((i) => i.status === 'connected'),
    [integrations.data],
  );

  const syncIntegration = useMutation({
    mutationFn: async (integration: { id: string; provider: string }) => {
      const basePath =
        integration.provider === 'microsoft_365'
          ? '/api/engagement/integrations/microsoft'
          : '/api/engagement/integrations/google';
      await api.post(`${basePath}/${integration.id}/sync`);
    },
    onSuccess: () => {
      message.success('Calendar sync started — new meetings will appear shortly');
      void qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
    },
    onError: () => {
      message.error('Sync failed — check your connection in Settings → Integrations');
    },
  });

  const meetings = useQuery<Meeting[]>({
    queryKey: ['engagement-meetings', selectedClientId, meetingWindow.from, meetingWindow.to],
    queryFn: async () =>
      (
        await api.get<Meeting[]>('/api/engagement/meetings', {
          params: {
            clientId: selectedClientId ?? undefined,
            from: meetingWindow.from,
            to: meetingWindow.to,
          },
        })
      ).data,
    // Purely legacy-UI fuel — Meetings v2 fetches its own data via useMeetings()
    // in meetings-api.ts (spec Phase 2 §2c2).
    enabled: !meetingsV2Enabled,
  });

  const visibleMeetings = useMemo(() => {
    const startOfToday = new Date();
    startOfToday.setHours(0, 0, 0, 0);
    const todayStart = startOfToday.getTime();
    return [...(meetings.data ?? [])].sort((left, right) => {
      const leftTime = new Date(left.startsAt).getTime();
      const rightTime = new Date(right.startsAt).getTime();
      // Today + upcoming meetings come first (soonest first); past meetings
      // sink below them (most recent past first).
      const leftUpcoming = leftTime >= todayStart;
      const rightUpcoming = rightTime >= todayStart;
      if (leftUpcoming !== rightUpcoming) return leftUpcoming ? -1 : 1;
      return leftUpcoming ? leftTime - rightTime : rightTime - leftTime;
    });
  }, [meetings.data]);
  const selectedMeetingFromVisible = useMemo(
    () => visibleMeetings.find((meeting) => meeting.id === selectedMeetingId) ?? null,
    [visibleMeetings, selectedMeetingId],
  );
  const selectedMeetingQuery = useQuery<Meeting>({
    queryKey: ['engagement-meeting', selectedMeetingId],
    queryFn: async () =>
      (await api.get<Meeting>(`/api/engagement/meetings/${selectedMeetingId}`)).data,
    // Legacy-only fallback (v2 resolves its own selection independently inside
    // MeetingsV2 via useMeetings()/useMeeting()).
    enabled: Boolean(selectedMeetingId && !selectedMeetingFromVisible) && !meetingsV2Enabled,
  });
  const selectedMeeting = selectedMeetingFromVisible ?? selectedMeetingQuery.data ?? null;
  const contextClientId = selectedClientId ?? selectedMeeting?.client?.id ?? null;

  const clientContext = useQuery<ClientContext>({
    queryKey: ['engagement-client-context', contextClientId],
    queryFn: async () =>
      (await api.get<ClientContext>(`/api/engagement/context/${contextClientId}`)).data,
    // Feeds only the legacy detail panel's Context tab.
    enabled: Boolean(contextClientId) && !meetingsV2Enabled,
  });

  const meetingAttachments = useQuery<EngagementAttachment[]>({
    queryKey: ['engagement-meeting-attachments', selectedMeeting?.id],
    queryFn: async () =>
      (
        await api.get<EngagementAttachment[]>('/api/engagement/attachments', {
          params: { meetingId: selectedMeeting?.id },
        })
      ).data,
    enabled: Boolean(selectedMeeting?.id) && !meetingsV2Enabled,
  });

  const meetingDebriefs = useQuery<MeetingDebrief[]>({
    queryKey: ['engagement-meeting-debriefs', selectedMeeting?.id],
    queryFn: async () =>
      (await api.get<MeetingDebrief[]>(`/api/engagement/meetings/${selectedMeeting?.id}/debriefs`))
        .data,
    enabled: Boolean(selectedMeeting?.id) && !meetingsV2Enabled,
  });

  const notetakerSession = useQuery<MeetingBotSession | null>({
    queryKey: ['engagement-meeting-notetaker', selectedMeeting?.id],
    queryFn: async () =>
      (
        await api.get<MeetingBotSession | null>(
          `/api/engagement/meetings/${selectedMeeting?.id}/notetaker`,
        )
      ).data,
    enabled: Boolean(selectedMeeting?.id) && !meetingsV2Enabled,
    // Poll while Meri is working, stop once the session settles (or is absent).
    refetchInterval: (query) => {
      const status = query.state.data?.status;
      return status && isNotetakerActive(status) ? 15000 : false;
    },
  });

  // Full debrief bodies for the quick notes modal — the list row only carries
  // meeting.debriefs summaries (no body), so a list-row "Notes" click loads the
  // body here. Shares the ['engagement-meeting-debriefs', id] cache with the
  // detail-panel query, so opening notes for the selected meeting is a cache hit.
  const notesModalDebriefs = useQuery<MeetingDebrief[]>({
    queryKey: ['engagement-meeting-debriefs', notesModalMeetingId],
    queryFn: async () =>
      (await api.get<MeetingDebrief[]>(`/api/engagement/meetings/${notesModalMeetingId}/debriefs`))
        .data,
    // notesModalMeetingId is only ever set by the legacy list/day/calendar
    // views' "View notes" action.
    enabled: Boolean(notesModalMeetingId) && !meetingsV2Enabled,
  });

  const tasks = useQuery<EngagementTask[]>({
    queryKey: ['engagement-tasks', selectedClientId],
    queryFn: async () =>
      (
        await api.get<EngagementTask[]>('/api/engagement/tasks', {
          params: { clientId: selectedClientId ?? undefined },
        })
      ).data,
  });

  const mailThreads = useQuery<MailThread[]>({
    queryKey: ['engagement-mail-threads', selectedClientId],
    queryFn: async () =>
      (
        await api.get<MailThread[]>('/api/engagement/mail-threads', {
          params: { clientId: selectedClientId ?? undefined },
        })
      ).data,
  });

  const report = useQuery<EngagementReport>({
    queryKey: ['engagement-report', selectedClientId, reportPeriod],
    queryFn: async () =>
      (
        await api.get<EngagementReport>('/api/engagement/reports/overview', {
          params: { clientId: selectedClientId ?? undefined, period: reportPeriod },
        })
      ).data,
  });

  const createMeeting = useMutation({
    mutationFn: async (values: MeetingFormValues) =>
      (
        await api.post<Meeting>('/api/engagement/meetings', {
          clientId: values.clientId || selectedClientId || undefined,
          subject: values.subject,
          description: optionalText(values.description),
          location: optionalText(values.location),
          startsAt: localDateTimeToIso(values.date, values.startsAt),
          endsAt: localDateTimeToIso(values.date, values.endsAt),
          attendees: parseAttendees(values.attendeesText),
        })
      ).data,
    onSuccess: (created) => {
      message.success('Meeting saved');
      setMeetingModalOpen(false);
      meetingForm.resetFields();
      qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
      // v2's own meetings-list query (meetings-api.ts) — the legacy key above
      // never overlaps with it, so both need invalidating on every create.
      qc.invalidateQueries({ queryKey: [meetingsListKey] });
      qc.invalidateQueries({ queryKey: ['engagement-tasks'] });
      // Only v2 auto-opens/jumps to the created meeting — the legacy page
      // never did this and edge case 8 keeps it that way.
      if (meetingsV2Enabled && created?.id) {
        setSelectedMeetingId(created.id);
        setMeetingDetailTab('prep');
        setMeetingCursor(localDateFromInput(localDateKey(created.startsAt)));
      }
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  const createTask = useMutation({
    mutationFn: async (values: TaskFormValues) =>
      (
        await api.post('/api/engagement/tasks', {
          clientId: selectedClientId ?? undefined,
          title: values.title,
          description: optionalText(values.description),
          dueDate: values.dueDate ? localDateTimeToIso(values.dueDate, '12:00') : undefined,
        })
      ).data,
    onSuccess: () => {
      message.success('Task saved');
      setTaskModalOpen(false);
      taskForm.resetFields();
      qc.invalidateQueries({ queryKey: ['engagement-tasks'] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  const createTargetOffice = useMutation({
    mutationFn: async (values: TargetOfficeFormValues) =>
      (
        await api.post(
          '/api/engagement/reports/target-offices',
          buildReportTargetCreateBody({
            values,
            directoryContactId: targetDirectoryContact?.id,
            editedFields: targetEditedFields,
            reportYear: report.data?.cycle.reportYear,
          }),
        )
      ).data,
    onSuccess: () => {
      message.success('Target office added');
      setTargetOfficeModalOpen(false);
      targetOfficeForm.resetFields();
      qc.invalidateQueries({ queryKey: ['engagement-report'] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  const updateReportTarget = useMutation({
    mutationFn: async ({
      row,
      field,
      status,
    }: {
      row: EngagementReportRow;
      field: ReportStatusField;
      status: ReportStatus;
    }) =>
      (
        await api.post('/api/engagement/reports/target-offices/overrides', {
          clientId: requireTargetClient(row.clientId),
          reportYear: requireReportYear(report.data?.cycle.reportYear),
          officeKey: row.officeKey,
          [field]: status,
          source: row.source === 'manual' ? 'manual' : 'manual_override',
        })
      ).data,
    onSuccess: () => qc.invalidateQueries({ queryKey: ['engagement-report'] }),
    onError: (err) => message.error(errorMessage(err)),
  });

  const restoreReportTarget = useMutation({
    mutationFn: async ({ row, field }: { row: EngagementReportRow; field: ReportStatusField }) =>
      (
        await api.delete('/api/engagement/reports/target-offices/overrides', {
          data: buildReportTargetRestoreBody({
            row,
            field,
            reportYear: report.data?.cycle.reportYear,
          }),
        })
      ).data,
    onSuccess: () => qc.invalidateQueries({ queryKey: ['engagement-report'] }),
    onError: (err) => message.error(errorMessage(err)),
  });

  const linkTargetOffice = useMutation({
    mutationFn: async () => {
      if (!linkTargetRow || !linkDirectoryContact) throw new Error('Select a Directory match.');
      return (
        await api.post('/api/engagement/reports/target-offices/link', {
          targetId: linkTargetRow.targetId ?? undefined,
          officeKey: linkTargetRow.officeKey,
          clientId: requireTargetClient(linkTargetRow.clientId ?? linkClientId),
          directoryContactId: linkDirectoryContact.id,
          conflictResolutions: linkConflictResolutions,
        })
      ).data;
    },
    onSuccess: () => {
      message.success('Target linked to Directory');
      setLinkTargetRow(null);
      qc.invalidateQueries({ queryKey: ['engagement-report'] });
    },
    onError: (err) => {
      const data = (
        err as { response?: { data?: { code?: string; conflicts?: typeof linkConflicts } } }
      ).response?.data;
      if (data?.code === 'TARGET_LINK_CONFLICT' && Array.isArray(data.conflicts)) {
        setLinkConflicts(data.conflicts);
        setLinkConflictResolutions({});
        message.error('Choose which value to keep for each conflicting field.');
      } else {
        message.error(errorMessage(err));
      }
    },
  });

  const assignTargetClient = useMutation({
    mutationFn: async ({
      row,
      clientId,
    }: {
      row: EngagementReportRow;
      clientId: string | undefined;
    }) => {
      const request = buildReportTargetAssignment(row, clientId);
      return (
        await api.patch(
          `/api/engagement/reports/target-offices/${encodeURIComponent(request.targetId)}`,
          request.body,
        )
      ).data;
    },
    onSuccess: () => {
      setAssignTargetRow(null);
      message.success('Target assigned to client');
      qc.invalidateQueries({ queryKey: ['engagement-report'] });
    },
  });

  const updateTaskStatus = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: EngagementTask['status'] }) =>
      (await api.patch(`/api/engagement/tasks/${id}`, { status })).data,
    onSuccess: () => qc.invalidateQueries({ queryKey: ['engagement-tasks'] }),
    onError: (err) => message.error(errorMessage(err)),
  });

  const generatePrep = useMutation({
    mutationFn: async ({
      meetingId,
      additionalContext,
    }: {
      meetingId: string;
      additionalContext?: string;
    }) =>
      (
        await api.post(`/api/engagement/meetings/${meetingId}/prep`, {
          additionalContext: additionalContext?.trim() || undefined,
        })
      ).data,
    onSuccess: (_prep, { meetingId }) => {
      const queued = !!_prep && typeof _prep === 'object' && 'jobId' in _prep;
      message.success(queued ? 'Preparation queued. Check progress in the meeting Prep tab.' : 'Meeting prep generated');
      if (queued) qc.setQueryData(['meeting-prep-job', meetingId], _prep);
      qc.invalidateQueries({ queryKey: ['engagement-meeting', meetingId] });
      qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-calendar-meetings'] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  const dispatchNotetaker = useMutation({
    mutationFn: async ({
      meetingId,
      meetingUrl,
      authorizedToRecord,
      allPartiesWillBeNotified,
    }: {
      meetingId: string;
      meetingUrl: string;
      authorizedToRecord: boolean;
      allPartiesWillBeNotified: boolean;
    }) =>
      (
        await api.post<MeetingBotSession>(`/api/engagement/meetings/${meetingId}/notetaker`, {
          meetingUrl,
          authorizedToRecord,
          allPartiesWillBeNotified,
        })
      ).data,
    onSuccess: (_session, { meetingId }) => {
      message.success('Meri is joining the meeting');
      setNotetakerModalOpen(false);
      notetakerForm.resetFields();
      qc.invalidateQueries({ queryKey: ['engagement-meeting', meetingId] });
      qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-calendar-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-meeting-notetaker', meetingId] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  // Open the consent modal for a SPECIFIC meeting (detail panel passes the
  // selected meeting; a list row passes its own). The target id drives the
  // dispatch so a row action can't be misattributed to the selected meeting.
  const openNotetakerModal = (meeting: Meeting | null) => {
    setNotetakerTargetMeetingId(meeting?.id ?? null);
    // Prefill ONLY when we can find an actual meeting join link (Zoom/Meet/
    // Teams/Webex) in the meeting's webLink/location/description. The Outlook
    // webLink is a CALENDAR link, not a join link — prefill with it and Recall
    // rejects the dispatch ("meeting_url is malformed") after the user already
    // affirmed consent. Blank + a clear placeholder beats a wrong prefill.
    notetakerForm.setFieldsValue({
      meetingUrl: meeting ? (extractMeetingJoinUrl(meeting) ?? '') : '',
      authorizedToRecord: false,
      allPartiesWillBeNotified: false,
    });
    setNotetakerModalOpen(true);
  };

  // Open a meeting's online join link in a new tab (the real join URL, not the
  // Outlook calendar webLink). No-op if the meeting has no supported join link.
  const handleJoinMeeting = (meeting: Meeting) => {
    const url = extractMeetingJoinUrl(meeting);
    if (url) window.open(url, '_blank', 'noopener,noreferrer');
  };

  const removeNotetaker = useMutation({
    mutationFn: async (meetingId: string) =>
      (await api.delete<MeetingBotSession>(`/api/engagement/meetings/${meetingId}/notetaker`)).data,
    onSuccess: (_session, meetingId) => {
      message.success('Meri is leaving the meeting');
      qc.invalidateQueries({ queryKey: ['engagement-meeting-notetaker', meetingId] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  // Completion signal: the detail poll notices the session settling and we toast
  // once per transition (the plan's "Meri drafted your debrief" notification).
  const notetakerStatusRef = useRef<string | null>(null);
  const notetakerStatus = notetakerSession.data?.status ?? null;
  const notetakerSessionId = notetakerSession.data?.id ?? null;
  useEffect(() => {
    const key = notetakerSessionId ? `${notetakerSessionId}:${notetakerStatus}` : null;
    const prev = notetakerStatusRef.current;
    notetakerStatusRef.current = key;
    if (!key || !notetakerSessionId || prev === key) return;
    // Only announce transitions we actually observed (skip the initial load,
    // where prev is for a different session or null).
    if (!prev || !prev.startsWith(`${notetakerSessionId}:`)) return;
    if (notetakerStatus === 'done') {
      message.success('Meri drafted your debrief — review it in the Debrief tab');
      qc.invalidateQueries({
        queryKey: ['engagement-meeting-debriefs', notetakerSession.data?.meetingId],
      });
      qc.invalidateQueries({
        queryKey: ['engagement-meeting-attachments', notetakerSession.data?.meetingId],
      });
    } else if (notetakerStatus === 'failed') {
      message.error("Meri couldn't finish the debrief for this meeting");
    }
  }, [notetakerStatus, notetakerSessionId, notetakerSession.data?.meetingId, message, qc]);

  const updatePrep = useMutation({
    mutationFn: async ({ prepId, values }: { prepId: string; values: PrepFormValues }) =>
      (
        await api.patch(`/api/engagement/meeting-preps/${prepId}`, {
          summary: optionalText(values.summary) ?? null,
          agenda: linesToArray(values.agendaText),
          talkingPoints: linesToArray(values.talkingPointsText),
          risks: linesToArray(values.risksText),
          followUps: linesToArray(values.followUpsText),
          emailEvidence: linesToArray(values.emailEvidenceText),
        })
      ).data,
    onSuccess: () => {
      message.success('Meeting prep saved');
      setEditingPrep(null);
      prepForm.resetFields();
      qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-calendar-meetings'] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  const saveDebrief = useMutation({
    mutationFn: async ({
      meetingId,
      debriefId,
      body,
    }: {
      meetingId: string;
      debriefId?: string;
      body: string;
    }) => {
      const payload = {
        body,
        confidential: true,
        accessLevel: 'tenant_members',
      };
      return debriefId
        ? (await api.patch(`/api/engagement/meetings/${meetingId}/debriefs/${debriefId}`, payload))
            .data
        : (await api.post(`/api/engagement/meetings/${meetingId}/debriefs`, payload)).data;
    },
    onSuccess: (data, variables) => {
      const savedDebrief = {
        ...(data as MeetingDebrief),
        body: variables.body,
        restricted: false,
      };
      qc.setQueryData<MeetingDebrief[]>(
        ['engagement-meeting-debriefs', variables.meetingId],
        (current = []) => {
          const withoutCurrent = current.filter((debrief) => debrief.id !== savedDebrief.id);
          return [savedDebrief, ...withoutCurrent];
        },
      );
      message.success('Debrief saved');
      qc.invalidateQueries({ queryKey: ['engagement-meeting', variables.meetingId] });
      qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-calendar-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-meeting-debriefs'] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  const generateDebriefDraft = useMutation({
    mutationFn: async ({
      meetingId,
      method,
      sourceText,
    }: {
      meetingId: string;
      method: 'upload' | 'manual' | 'voice';
      sourceText: string;
    }) =>
      (
        await api.post<MeetingDebriefDraft>(`/api/engagement/meetings/${meetingId}/debrief-draft`, {
          method,
          sourceText,
        })
      ).data,
    onError: (err) => message.error(errorMessage(err)),
  });

  const uploadTranscript = useMutation({
    mutationFn: async ({ meeting, file }: { meeting: Meeting; file: File }) => {
      const contentType = file.type || 'application/octet-stream';
      const upload = (
        await api.post<{
          url: string;
          fields: Record<string, string>;
          s3Key: string;
        }>('/api/engagement/attachments/upload-url', {
          meetingId: meeting.id,
          clientId: meeting.client?.id ?? undefined,
          fileName: file.name,
          contentType,
          contentLength: file.size,
        })
      ).data;
      const form = new FormData();
      Object.entries(upload.fields).forEach(([key, value]) => form.append(key, value));
      form.append('file', file);
      const result = await fetch(upload.url, { method: 'POST', body: form });
      if (!result.ok) throw new Error('Transcript upload failed');
      return (
        await api.post<EngagementAttachment>('/api/engagement/attachments/confirm', {
          meetingId: meeting.id,
          clientId: meeting.client?.id ?? undefined,
          fileName: file.name,
          contentType,
          s3Key: upload.s3Key,
        })
      ).data;
    },
    onSuccess: () => {
      message.success('Transcript uploaded');
      qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-calendar-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-meeting-attachments'] });
    },
  });

  const extractAttachmentText = useMutation({
    mutationFn: async (attachmentId: string) =>
      (
        await api.post<DebriefSourceExtraction>(
          `/api/engagement/attachments/${attachmentId}/extract-text`,
        )
      ).data,
  });

  const deleteAttachment = useMutation({
    mutationFn: async (attachmentId: string) =>
      (await api.delete(`/api/engagement/attachments/${attachmentId}`)).data,
    onSuccess: () => {
      message.success('Attachment removed');
      qc.invalidateQueries({ queryKey: ['engagement-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-calendar-meetings'] });
      qc.invalidateQueries({ queryKey: ['engagement-meeting-attachments'] });
    },
    onError: (err) => message.error(errorMessage(err)),
  });

  useEffect(() => {
    const handler = () => setActiveEngagementTab('outreach');
    window.addEventListener('capiro:open-outreach', handler);
    return () => window.removeEventListener('capiro:open-outreach', handler);
  }, []);

  const generatingPrepMeetingId = generatePrep.isPending
    ? (generatePrep.variables?.meetingId ?? null)
    : null;
  const detailTab = meetingDetailTab === 'notes' ? 'prep' : meetingDetailTab;

  // `defaultDate` prefills the day when invoked from a selected calendar day in
  // Meetings v2 (MeetingsV2's onCreateMeeting); the header button calls this
  // with no argument, which still defaults to today (spec Phase 2 §2b1).
  const openMeetingModal = (defaultDate?: Date) => {
    meetingForm.setFieldsValue({
      date: defaultDate ? inputValueFromDate(defaultDate) : todayInputValue(),
      startsAt: '09:00',
      endsAt: '09:30',
      clientId: selectedClientId ?? undefined,
    });
    setMeetingModalOpen(true);
  };

  // `?compose=meeting` opens the create-meeting window on arrival, so the
  // post-send "Create meeting" action in Outreach lands on a real composer
  // instead of merely dropping the user on the calendar. The param is consumed
  // immediately (replace, not push) so refresh and Back do not re-open it.
  useEffect(() => {
    if (searchParams.get('compose') !== 'meeting') return;
    const next = new URLSearchParams(searchParams);
    next.delete('compose');
    navigate(
      { pathname: location.pathname, search: next.toString() ? `?${next.toString()}` : '' },
      { replace: true },
    );
    openMeetingModal();
    // openMeetingModal is recreated every render; the param guard above is the
    // real idempotency gate, so it is intentionally not a dependency.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams, location.pathname, navigate]);

  // Resets + prefills the Add Target Office form (spec Phase 2 §2b2). Nothing
  // opened this modal before this change — the ReportsView header/empty-state
  // buttons are the first real trigger.
  const openTargetOfficeModal = () => {
    targetOfficeForm.resetFields();
    targetOfficeForm.setFieldsValue({ clientId: selectedClientId ?? undefined, manualOnly: false });
    setTargetDirectoryContact(null);
    setTargetEditedFields(new Set());
    setTargetOfficeModalOpen(true);
  };

  const handleGeneratePrep = (meeting: Meeting, additionalContext?: string) => {
    setSelectedMeetingId(meeting.id);
    setMeetingDetailTab('prep');
    generatePrep.mutate({ meetingId: meeting.id, additionalContext });
  };

  const handleTabChange = (nextKey: string) => {
    if (
      nextKey === 'overview' ||
      nextKey === 'meetings' ||
      nextKey === 'outreach' ||
      nextKey === 'reports'
    ) {
      if (nextKey === 'meetings' && activeEngagementTab !== 'meetings') {
        setMeetingsLibraryOpen(false);
      }
      setActiveEngagementTab(nextKey);
    }
  };

  const visibleClients = (clients.data ?? []).filter((c) => c.status !== 'archived');
  const selectedClient = visibleClients.find((c) => c.id === selectedClientId) ?? null;

  return (
    <section className="engagement-page redesign">
      <header className="eng-head">
        <h1 className="eng-page-h1">Engagement</h1>
        <EngClientPicker
          clients={visibleClients}
          selectedClient={selectedClient}
          onSelect={setSelectedClientId}
        />
      </header>
      <Tabs
        className="engagement-tabs"
        activeKey={activeEngagementTab}
        onChange={handleTabChange}
        tabBarExtraContent={
          activeEngagementTab === 'meetings'
            ? {
                right: meetingsV2Enabled ? (
                  // Spec Phase 2 §2b1: v2 gets BOTH a primary New Meeting action
                  // and the Library entry (superseding the older assumption that
                  // the redesigned module owned meeting creation on its own).
                  // `wrap` matches the same responsive pattern already used for
                  // the Reports header controls (edge case 34).
                  <Space size={10} wrap className="engagement-tab-actions">
                    <Button
                      type="primary"
                      icon={<PlusOutlined />}
                      onClick={() => openMeetingModal()}
                    >
                      New meeting
                    </Button>
                    <button
                      type="button"
                      className="btn"
                      style={{ gap: 7, fontWeight: 600 }}
                      onClick={() => setMeetingsLibraryOpen(true)}
                    >
                      <Library size={15} />
                      Meeting Library
                    </button>
                    {connectedIntegrations.length > 0 && (
                      <Button
                        icon={<SyncOutlined spin={syncIntegration.isPending} />}
                        loading={syncIntegration.isPending}
                        onClick={() =>
                          connectedIntegrations.forEach((i) =>
                            syncIntegration.mutate({ id: i.id, provider: i.provider }),
                          )
                        }
                      >
                        Sync now
                      </Button>
                    )}
                  </Space>
                ) : (
                  <Space size={10} wrap className="engagement-tab-actions">
                    <Button
                      type="primary"
                      icon={<PlusOutlined />}
                      onClick={() => openMeetingModal()}
                    >
                      Meeting
                    </Button>
                    {connectedIntegrations.length > 0 && (
                      <Button
                        icon={<SyncOutlined spin={syncIntegration.isPending} />}
                        loading={syncIntegration.isPending}
                        onClick={() =>
                          connectedIntegrations.forEach((i) =>
                            syncIntegration.mutate({ id: i.id, provider: i.provider }),
                          )
                        }
                      >
                        Sync now
                      </Button>
                    )}
                  </Space>
                ),
              }
            : undefined
        }
        // Overview tab — landing/orientation surface with navigation to other tabs.
        items={[
          {
            key: 'overview',
            label: 'Overview',
            children: (
              <OverviewTab
                onNavigate={(tab) => handleTabChange(tab)}
                stats={{
                  meetingsThisWeek: meetings.data?.length ?? 0,
                  debriefsPending: 0,
                  draftsOpen: 0,
                }}
              />
            ),
          },
          {
            key: 'meetings',
            label: 'Meetings',
            children: meetingsV2Enabled ? (
              <MeetingsV2
                clientId={selectedClientId}
                aiConfigured={Boolean(capabilities.data?.ai.activeProvider)}
                libraryOpen={meetingsLibraryOpen}
                onLibraryOpenChange={setMeetingsLibraryOpen}
                viewMode={meetingViewMode}
                cursor={meetingCursor}
                selectedMeetingId={selectedMeetingId}
                detailTab={toDetailTab(meetingDetailTab)}
                onViewModeChange={setMeetingViewMode}
                onCursorChange={setMeetingCursor}
                onSelectedMeetingChange={setSelectedMeetingId}
                onDetailTabChange={setMeetingDetailTab}
                onCreateMeeting={openMeetingModal}
              />
            ) : (
              <div className="engagement-meeting-shell">
                <div className="engagement-panel engagement-schedule-panel">
                  <div className="engagement-schedule-head">
                    <PanelTitle icon={<CalendarOutlined />} title="Meetings" />
                    <div className="engagement-view-toggle" aria-label="Meeting view">
                      <button
                        type="button"
                        className={meetingViewMode === 'list' ? 'active' : ''}
                        onClick={() => setMeetingViewMode('list')}
                      >
                        List
                      </button>
                      <button
                        type="button"
                        className={meetingViewMode === 'month' ? 'active' : ''}
                        onClick={() => setMeetingViewMode('month')}
                      >
                        Calendar
                      </button>
                      <button
                        type="button"
                        className={meetingViewMode === 'day' ? 'active' : ''}
                        onClick={() => setMeetingViewMode('day')}
                      >
                        Day
                      </button>
                    </div>
                  </div>

                  <MeetingWeekNav
                    rangeStart={rangeStart}
                    rangeEnd={rangeEnd}
                    onShiftWindow={(delta) => {
                      setHistoryBatch(0);
                      // Page by the CURRENT window's length so ‹ › works for any
                      // selected range, not just a fixed week.
                      const start = localDateFromInput(rangeStart);
                      const end = localDateFromInput(rangeEnd);
                      const spanDays =
                        Math.round((end.getTime() - start.getTime()) / 86_400_000) + 1;
                      setRangeStart(inputValueFromDate(addLocalDays(start, delta * spanDays)));
                      setRangeEnd(inputValueFromDate(addLocalDays(end, delta * spanDays)));
                    }}
                    onRangeChange={(start, end) => {
                      setHistoryBatch(0);
                      setRangeStart(start);
                      setRangeEnd(end);
                      // Highlight the first day of the new range in the Day view.
                      setMeetingFocusDayKey(start);
                    }}
                  />

                  {meetings.isLoading ? (
                    <Empty description="Loading Outlook meetings..." />
                  ) : visibleMeetings.length ? (
                    meetingViewMode === 'list' ? (
                      <MeetingListView
                        meetings={visibleMeetings}
                        selectedId={selectedMeeting?.id ?? null}
                        historyBatch={historyBatch}
                        generatingMeetingId={generatingPrepMeetingId}
                        aiConfigured={Boolean(capabilities.data?.ai.activeProvider)}
                        onSelect={(meeting, tab) => {
                          setSelectedMeetingId(meeting.id);
                          setMeetingDetailTab(tab ?? 'prep');
                        }}
                        onGeneratePrep={(meeting) => {
                          handleGeneratePrep(meeting);
                        }}
                        onJoin={handleJoinMeeting}
                        onSendNotetaker={openNotetakerModal}
                        onViewNotes={(meeting) => setNotesModalMeetingId(meeting.id)}
                        onLoadMore={() => setHistoryBatch((value) => value + 1)}
                      />
                    ) : meetingViewMode === 'day' ? (
                      <MeetingDayTimeline
                        meetings={visibleMeetings}
                        selectedId={selectedMeeting?.id ?? null}
                        rangeStart={rangeStart}
                        rangeEnd={rangeEnd}
                        focusDayKey={meetingFocusDayKey}
                        aiConfigured={Boolean(capabilities.data?.ai.activeProvider)}
                        generatingMeetingId={generatingPrepMeetingId}
                        onSelect={(meetingId) => {
                          setSelectedMeetingId(meetingId);
                          setMeetingDetailTab('prep');
                        }}
                        onAction={(meetingId, tab) => {
                          setSelectedMeetingId(meetingId);
                          setMeetingDetailTab(tab);
                        }}
                        onGeneratePrep={(meetingId) => {
                          const meeting = visibleMeetings.find((m) => m.id === meetingId);
                          if (meeting) handleGeneratePrep(meeting);
                        }}
                        onJoin={handleJoinMeeting}
                        onSendNotetaker={openNotetakerModal}
                        onViewNotes={(meeting) => setNotesModalMeetingId(meeting.id)}
                      />
                    ) : (
                      <MeetingCalendarList
                        meetings={visibleMeetings}
                        selectedId={selectedMeeting?.id ?? null}
                        rangeStart={rangeStart}
                        rangeEnd={rangeEnd}
                        onSelect={(meetingId) => {
                          setSelectedMeetingId(meetingId);
                          setMeetingDetailTab('prep');
                        }}
                        onAction={(meetingId, tab) => {
                          setSelectedMeetingId(meetingId);
                          setMeetingDetailTab(tab);
                        }}
                        onJoin={handleJoinMeeting}
                        onSendNotetaker={openNotetakerModal}
                        onViewNotes={(meeting) => setNotesModalMeetingId(meeting.id)}
                      />
                    )
                  ) : (
                    <MeetingListEmpty
                      hasAnySyncedMeetings={hasCustomMeetingRange}
                      onSync={() => window.dispatchEvent(new Event('capiro:sync-inbox'))}
                    />
                  )}
                </div>

                <MeetingDetailPanel
                  meeting={selectedMeeting}
                  context={clientContext.data}
                  contextLoading={clientContext.isLoading}
                  attachments={meetingAttachments.data ?? selectedMeeting?.attachments ?? []}
                  attachmentsLoading={meetingAttachments.isLoading}
                  debriefs={meetingDebriefs.data ?? []}
                  debriefsLoading={meetingDebriefs.isLoading}
                  activeTab={detailTab}
                  onTabChange={setMeetingDetailTab}
                  attachmentsConfigured={Boolean(capabilities.data?.attachments.s3Configured)}
                  aiConfigured={Boolean(capabilities.data?.ai.activeProvider)}
                  generating={generatingPrepMeetingId === selectedMeeting?.id}
                  uploadingTranscript={
                    uploadTranscript.isPending || extractAttachmentText.isPending
                  }
                  deletingAttachmentId={
                    typeof deleteAttachment.variables === 'string'
                      ? deleteAttachment.variables
                      : null
                  }
                  savingDebrief={saveDebrief.isPending}
                  generatingDebrief={generateDebriefDraft.isPending}
                  onGeneratePrep={handleGeneratePrep}
                  onUploadTranscript={(meeting, file) =>
                    uploadTranscript.mutateAsync({ meeting, file })
                  }
                  onExtractAttachmentText={(attachment) =>
                    extractAttachmentText.mutateAsync(attachment.id)
                  }
                  onRemoveAttachment={(attachmentId) => deleteAttachment.mutate(attachmentId)}
                  onSaveDebrief={(meeting, body, debriefId) =>
                    saveDebrief.mutateAsync({ meetingId: meeting.id, body, debriefId })
                  }
                  onGenerateDebrief={(meeting, method, sourceText) =>
                    generateDebriefDraft.mutateAsync({
                      meetingId: meeting.id,
                      method,
                      sourceText,
                    })
                  }
                  onEditPrep={(meeting, prep) => {
                    prepForm.setFieldsValue({
                      summary: prep.summary ?? '',
                      agendaText: prep.agenda.join('\n'),
                      talkingPointsText: prep.talkingPoints.join('\n'),
                      risksText: prep.risks.join('\n'),
                      followUpsText: prep.followUps.join('\n'),
                      emailEvidenceText: (prep.emailEvidence ?? []).join('\n'),
                    });
                    setEditingPrep({ meeting, prep });
                  }}
                  onExportPdf={(meeting) =>
                    exportMeetingPdf({
                      meeting,
                      debriefs: meetingDebriefs.data ?? [],
                      context: clientContext.data,
                    })
                  }
                  notetakerSession={notetakerSession.data ?? null}
                  dispatchingNotetaker={dispatchNotetaker.isPending}
                  onSendNotetaker={() => openNotetakerModal(selectedMeeting)}
                  removingNotetaker={removeNotetaker.isPending}
                  onRemoveNotetaker={(meetingId) => removeNotetaker.mutate(meetingId)}
                />
              </div>
            ),
          },
          {
            key: 'outreach',
            label: 'Outreach',
            children: (
              <OutreachView
                clients={activeClients}
                selectedClientId={selectedClientId}
                aiConfigured={Boolean(capabilities.data?.ai.activeProvider)}
              />
            ),
          },
          {
            key: 'reports',
            label: 'Reports',
            children: (
              <ReportsView
                report={report.data}
                loading={report.isLoading}
                period={reportPeriod}
                onPeriodChange={setReportPeriod}
                statusFilter={reportStatusFilter}
                onStatusFilterChange={setReportStatusFilter}
                sort={reportSort}
                onSortChange={setReportSort}
                onAddTargetOffice={openTargetOfficeModal}
                updatingCell={
                  updateReportTarget.isPending && updateReportTarget.variables
                    ? reportCellKey(
                        updateReportTarget.variables.row,
                        updateReportTarget.variables.field,
                      )
                    : restoreReportTarget.isPending && restoreReportTarget.variables
                      ? reportCellKey(
                          restoreReportTarget.variables.row,
                          restoreReportTarget.variables.field,
                        )
                      : null
                }
                onViewMeetings={setReportMeetingRow}
                onStatusChange={(row, field, status) =>
                  updateReportTarget.mutate({
                    row,
                    field,
                    status,
                  })
                }
                onRestore={(row, field) => restoreReportTarget.mutate({ row, field })}
                onLinkDirectory={(row) => {
                  linkTargetOffice.reset();
                  setLinkTargetRow(row);
                  setLinkDirectoryContact(null);
                  setLinkClientId(row.clientId ?? undefined);
                  setLinkConflicts([]);
                  setLinkConflictResolutions({});
                }}
                onAssignClient={(row) => {
                  assignTargetClient.reset();
                  setAssignTargetRow(row);
                  setAssignClientId(undefined);
                }}
              />
            ),
          },
        ]}
      />

      <Modal
        rootClassName="redesign"
        title="New meeting"
        open={meetingModalOpen}
        onCancel={() => setMeetingModalOpen(false)}
        onOk={() => meetingForm.submit()}
        confirmLoading={createMeeting.isPending}
        width={680}
      >
        <Form
          form={meetingForm}
          layout="vertical"
          onFinish={(values) => createMeeting.mutate(values)}
        >
          <Form.Item name="subject" label="Subject" rules={[{ required: true, min: 1 }]}>
            <Input />
          </Form.Item>
          <Form.Item name="clientId" label="Client">
            <Select
              allowClear
              showSearch={clientSelectOptions.length > 10}
              optionFilterProp="label"
              options={clientSelectOptions}
            />
          </Form.Item>
          <div className="engagement-form-grid">
            <Form.Item name="date" label="Date" rules={[{ required: true }]}>
              <Input type="date" />
            </Form.Item>
            <Form.Item name="startsAt" label="Start" rules={[{ required: true }]}>
              <Input type="time" />
            </Form.Item>
            <Form.Item name="endsAt" label="End" rules={[{ required: true }]}>
              <Input type="time" />
            </Form.Item>
          </div>
          <Form.Item name="location" label="Location">
            <Input />
          </Form.Item>
          <Form.Item name="attendeesText" label="Attendees">
            <Input.TextArea rows={3} placeholder="Jane Smith <jane@example.com>" />
          </Form.Item>
          <Form.Item name="description" label="Details">
            <Input.TextArea rows={4} />
          </Form.Item>
        </Form>
      </Modal>

      <Modal
        rootClassName="redesign"
        title="New task"
        open={taskModalOpen}
        onCancel={() => setTaskModalOpen(false)}
        onOk={() => taskForm.submit()}
        confirmLoading={createTask.isPending}
      >
        <Form form={taskForm} layout="vertical" onFinish={(values) => createTask.mutate(values)}>
          <Form.Item name="title" label="Title" rules={[{ required: true, min: 1 }]}>
            <Input />
          </Form.Item>
          <Form.Item name="dueDate" label="Due date">
            <Input type="date" />
          </Form.Item>
          <Form.Item name="description" label="Description">
            <Input.TextArea rows={3} />
          </Form.Item>
        </Form>
      </Modal>

      <Modal
        rootClassName="redesign"
        title="Add target office"
        destroyOnClose
        open={targetOfficeModalOpen}
        onCancel={() => setTargetOfficeModalOpen(false)}
        onOk={() => targetOfficeForm.submit()}
        confirmLoading={createTargetOffice.isPending}
        okText={targetManualOnly ? 'Save manual-only target' : 'Add target office'}
        okButtonProps={{
          disabled:
            !report.data?.cycle.reportYear || (!targetManualOnly && !targetDirectoryContact),
        }}
        width={640}
      >
        <Form
          form={targetOfficeForm}
          layout="vertical"
          onFinish={(values: TargetOfficeFormValues) => createTargetOffice.mutate(values)}
          onValuesChange={(changed: Partial<TargetOfficeFormValues>) =>
            setTargetEditedFields((previous) => new Set([...previous, ...Object.keys(changed)]))
          }
        >
          <Form.Item
            name="clientId"
            label="Client"
            rules={[{ required: true, message: 'Select the client this target belongs to.' }]}
          >
            <Select
              placeholder="Select a client"
