              placeholder="Assign this legacy target to a client"
              options={clientSelectOptions}
              onChange={(value: string) => {
                linkTargetOffice.reset();
                setLinkClientId(value);
                setLinkConflicts([]);
                setLinkConflictResolutions({});
              }}
