            <Select
              value={statusFilter}
              onChange={onStatusFilterChange}
              options={[
                { value: 'all', label: 'Filter: All Statuses' },
                { value: 'complete', label: 'Filter: Complete' },
                { value: 'in_progress', label: 'Filter: In Progress' },
                { value: 'not_started', label: 'Filter: Not Started' },
