  if (!options.editor && !newsletterBlockVisible(block, options.recipient)) return '';
  const button = block.kind === 'button' || (block.kind === 'survey' && !!block.survey);
  const defaults =
    block.kind === 'heading'
      ? design.styles.text[`h${block.headingLevel}`]
