      moveBlock(design, parent.id, {
        sectionId: design.sections[1]!.id,
        columnId: nested.id,
        column: 0,
      }),
    ).toBe(false);
    const child = parent.columns[0]![0]!;
    expect(moveBlock(design, child.id, { sectionId: design.sections[2]!.id })).toBe(true);
    expect(design.sections[2]!.blocks.at(-1)!.id).toBe(child.id);
    expect(locateBlock(design, child.id)?.list).toBe(design.sections[2]!.blocks);
    const copy = cloneSection(design.sections[1]!);
    expect(copy.id).not.toBe(design.sections[1]!.id);
    expect(copy.blocks[0]!.id).not.toBe(design.sections[1]!.blocks[0]!.id);
  });
  it('removes executable paste markup before putting it on the canvas', () => {
    const html = sanitizeNewsletterMarkup(
      '<script>evil()</script><img src="javascript:evil()" onerror="evil()"><p style="background:url(https://evil.example)">Safe</p>',
    );
    expect(html).toContain('Safe');
    expect(html).not.toMatch(/script|javascript|onerror|url\(/);
  });
  it('adds a real Apps Link Preview, saves the selected app before import and autosaves the resulting card', async () => {
    setup();
    mocks.client.linkPreview = vi.fn().mockResolvedValue({
      sourceUrl: 'https://news.example/policy',
      title: 'Committee update',
      description: 'Illustrative policy story.',
      imageUrl: '',
      warnings: [],
    });
    await screen.findByLabelText('Newsletter name');
    fireEvent.click(screen.getByRole('button', { name: /^Apps$/ }));
    const sidebar = within(screen.getByRole('complementary'));
    fireEvent.click(sidebar.getByText('Link Preview').closest('summary')!);
    fireEvent.click(sidebar.getByRole('button', { name: 'Use Link Preview' }));
    fireEvent.change(sidebar.getByLabelText('Source URL'), {
      target: { value: 'https://news.example/policy' },
    });
    fireEvent.click(sidebar.getByRole('button', { name: 'Load preview' }));
    await waitFor(() =>
      expect(mocks.client.linkPreview).toHaveBeenCalledWith('doc1', 'https://news.example/policy'),
    );
    await waitFor(() =>
      expect(
        mocks.client
          .save!.mock.calls.at(-1)![0]
          .design.sections.some((section: { blocks: { app?: { title: string } }[] }) =>
            section.blocks.some((block) => block.app?.title === 'Committee update'),
          ),
      ).toBe(true),
    );
    expect(
      within(screen.getByRole('main'))
        .getByRole('link', { name: /Committee update/ })
        .getAttribute('href'),
    ).toBe('https://news.example/policy');
    expect(
      within(screen.getByRole('main')).getByRole('link', { name: /Committee update/ }),
    ).toHaveStyle({ color: '#1f2937', background: '#f3f4f6' });
    expect(screen.queryByLabelText('Apps text')).toBeNull();
  });
});

import React, { Suspense } from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { ClerkProvider } from '@clerk/clerk-react';
import { App as AntApp, ConfigProvider } from 'antd';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { App } from './App.js';
import { config, isVNextSurface } from './env.js';
import { ANTD_THEME, CLERK_APPEARANCE } from './theme-antd.js';
import { shouldRetryQuery } from './lib/query-retry.js';
import { initializeMeriInstallExperience } from './vnext/meri/meri-install.js';

// theme.css is the LEGACY surface's global stylesheet. One bundle serves two
// surfaces (see env.ts): app.capiro.ai still renders antd and needs it;
// os.capiro.ai is fully vNext-native (no-legacy-ui.contract.test.ts holds the
// allowlist at zero) and must not have legacy selectors repainting its DOM.
// Loaded dynamically so the vNext surface never fetches or applies it.
if (!isVNextSurface) {
  void import('./theme.css');
} else {
  initializeMeriInstallExperience();
  // AuthPage (App.tsx) is shared by both surfaces and renders before either
  // ClerkAuth or BillingGate mounts VNextApp — its vNext styling has to load
  // here rather than being carried in by any lazy vNext route.
  void import('./vnext/app/auth/vnext-auth.css');
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: { staleTime: 30_000, refetchOnWindowFocus: false, retry: shouldRetryQuery },
  },
});

const publicShareMatch =
  /^\/share\/([^/]+)\/?$/.exec(window.location.pathname);
const PublicWorkspaceShare = React.lazy(() =>
  import('./vnext/pages/workspace/share/WorkspaceShareView.js').then(
    (module) => ({ default: module.WorkspaceShareView }),
  ),
);

function FoundationProviders({ children }: { children: React.ReactNode }) {
  const core = (
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>{children}</BrowserRouter>
    </QueryClientProvider>
  );

  // The antd theme context and <App> chrome exist for the legacy surface
  // only. On os.capiro.ai nothing antd renders (guard test), so the vNext
  // tree mounts without them — no .ant-app wrapper, no antd message/modal
  // context, no antd theme tokens.
  if (isVNextSurface) return core;

  return (
    <ConfigProvider theme={ANTD_THEME}>
      <AntApp>{core}</AntApp>
    </ConfigProvider>
  );
}

function PublicShareEntry({ token }: { token: string }) {
  return (
    <FoundationProviders>
      <Suspense
        fallback={
          <div
            role="status"
            style={{
              minHeight: '100vh',
              display: 'grid',
              placeItems: 'center',
              color: '#667085',
              background: '#f9fafb',
              fontFamily: 'Inter, sans-serif',
            }}
          >
            Loading shared document…
          </div>
        }
      >
        <PublicWorkspaceShare token={token} />
      </Suspense>
    </FoundationProviders>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root')!);

if (publicShareMatch?.[1]) {
  // Public Workspace shares intentionally mount outside Clerk, billing,
  // tenant context and the authenticated vNext shell.
  root.render(
    <React.StrictMode>
      <PublicShareEntry token={decodeURIComponent(publicShareMatch[1])} />
    </React.StrictMode>,
  );
} else {
  root.render(
    <React.StrictMode>
      <ClerkProvider
        publishableKey={config.clerkPublishableKey}
        signInUrl="/sign-in"
        signUpUrl="/sign-up"
        signInFallbackRedirectUrl="/"
        signUpFallbackRedirectUrl="/"
        appearance={CLERK_APPEARANCE}
      >
        <FoundationProviders>
          <App />
        </FoundationProviders>
      </ClerkProvider>
    </React.StrictMode>,
  );
}
